window.canCreateProject = async function () {
    if (!currentUser) return { allowed: false, reason: 'Giriş yapmalısınız' };
    var limits = window.getPlanLimits(currentUser);
    var maxProjects = limits.maxProjects;
    if (maxProjects === -1) return { allowed: true, limit: -1 };
    try {
        var result = await Parse.Cloud.run('getUserProjectCount', {});
        var currentCount = (result && result.count) ? result.count : 0;
        if (currentCount >= maxProjects) {
            return { allowed: false, limit: maxProjects, used: currentCount, remaining: 0, reason: 'Proje limitinize ulaştınız' };
        }
        return { allowed: true, limit: maxProjects, used: currentCount, remaining: maxProjects - currentCount };
    } catch (e) {
        return { allowed: true, limit: maxProjects, used: 0 };
    }
};

window.canCreateTeam = function () {
    var limits = window.getPlanLimits(currentUser);
    if (!limits.takimKurma) {
        return { allowed: false, reason: 'Community kurmak için Takım paketi gerekli' };
    }
    return { allowed: true };
};

window.canUseAgentMode = function () {
    var limits = window.getPlanLimits(currentUser);
    if (!limits.aganModu) return { allowed: false, reason: 'Ajan modu Pro ve üzeri paketlerde mevcut' };
    return { allowed: true };
};

window.canUseDeepThink = function () {
    var limits = window.getPlanLimits(currentUser);
    if (!limits.derinDusunme) return { allowed: false, reason: 'Derin düşünme modu Pro ve üzeri paketlerde mevcut' };
    return { allowed: true };
};

window.canUseDeveloperMode = function () {
    var limits = window.getPlanLimits(currentUser);
    if (!limits.yazilimciModu) return { allowed: false, reason: 'Yazılımcı modu Pro ve üzeri paketlerde mevcut' };
    return { allowed: true };
};

window.canUseScreenRead = function () {
    var limits = window.getPlanLimits(currentUser);
    if (!limits.ekranOkuma) return { allowed: false, reason: 'Ekran okuma Pro ve üzeri paketlerde mevcut' };
    return { allowed: true };
};

window.canCreateJobListing = function () {
    if (!currentUser) return { allowed: false, reason: 'Giriş yapmalısınız' };
    var limits = window.getPlanLimits(currentUser);
    var limit = limits.jobListings;
    if (limit === -1) return { allowed: true, limit: -1 };
    var used = getUsageData('jobListings', 'lifetime');
    if (used >= limit) {
        return {
            allowed: false,
            limit: limit,
            used: used,
            remaining: 0,
            reason: 'İş ilanı limitinize ulaştınız'
        };
    }
    return { allowed: true, limit: limit, used: used, remaining: limit - used };
};

window.canAccessCategory = function (categoryId) {
    if (!currentUser) return { allowed: false, reason: 'Giriş yapmalısınız' };
    var limits = window.getPlanLimits(currentUser);
    var allowed = limits.categoryAccess || [];
    if (allowed.indexOf(categoryId) === -1) {
        return {
            allowed: false,
            reason: 'Bu kategori paketinizde yok',
            categoryId: categoryId,
            requiresUpgrade: true
        };
    }
    return { allowed: true };
};

// ============================================================
// [AETHRION] LOG SİSTEMİ
// ============================================================
window.addLog = function (level, message, meta) {
    level = level || 'info';
    var entry = {
        id: 'aethrion_log_v1_' + Date.now() + '_' + Math.random().toString(36).substring(2, 8),
        level: level,
        message: String(message || ''),
        meta: meta || null,
        time: new Date().toISOString(),
        url: window.location.href,
        userAgent: navigator.userAgent.substring(0, 100),
        version: 'v1.0.0'
    };

    window.logsCache.push(entry);
    if (window.logsCache.length > window.MAX_LOGS_CACHE) {
        window.logsCache.shift();
    }

    try {
        localStorage.setItem('aethrion_logs_v1', JSON.stringify(window.logsCache.slice(-100)));
    } catch (e) {}

    var consoleMethod = 'log';
    if (level === 'error' || level === 'critical') consoleMethod = 'error';
    else if (level === 'warning') consoleMethod = 'warn';
    try {
        console[consoleMethod]('[AETHRION-' + level.toUpperCase() + ']', message, meta || '');
    } catch (e) {}

    if (parseInitialized && currentUser && ['error', 'critical'].indexOf(level) !== -1) {
        try {
            Parse.Cloud.run('logError', {
                level: level,
                message: message,
                meta: meta,
                url: window.location.href,
                userAgent: navigator.userAgent.substring(0, 200)
            }).catch(function () {});
        } catch (e) {}
    }

    return entry;
};

window.addLogInfo = function (msg, meta) { return window.addLog('info', msg, meta); };
window.addLogSuccess = function (msg, meta) { return window.addLog('success', msg, meta); };
window.addLogWarning = function (msg, meta) { return window.addLog('warning', msg, meta); };
window.addLogError = function (msg, meta) { return window.addLog('error', msg, meta); };
window.addLogCritical = function (msg, meta) { return window.addLog('critical', msg, meta); };

// Global hata yakalayıcı
window.addEventListener('error', function (e) {
    try {
        window.addLog('error', 'Global JS Hatası: ' + (e.message || 'Bilinmiyor'), {
            file: e.filename,
            line: e.lineno,
            col: e.colno
        });
    } catch (err) {}
});

window.addEventListener('unhandledrejection', function (e) {
    try {
        window.addLog('error', 'Yakalanmamış Promise Hatası: ' + (e.reason && e.reason.message || e.reason), {
            stack: e.reason && e.reason.stack
        });
    } catch (err) {}
});

// --- Logs Modal Aç ---
window.openLogsPanel = function () {
    if (!currentUser) {
        showNotification('Önce giriş yapın!', 'error');
        return;
    }
    var limits = window.getPlanLimits(currentUser);
    if (!limits.logsAccess) {
        window.showLimitModal('logsAccess', {
            allowed: false,
            reason: 'Logs sistemi sadece Pro ve üzeri paketlerde mevcut',
            limit: 0,
            used: 0,
            requiresUpgrade: true
        });
        return;
    }

    var modal = document.getElementById('logsModal');
    if (modal) {
        modal.classList.add('open');
        modal.style.display = 'flex';
        window.renderLogs();
        window.addLogInfo('Logs paneli açıldı');
    }
};

window.closeLogsPanel = function () {
    var modal = document.getElementById('logsModal');
    if (modal) {
        modal.classList.remove('open');
        modal.style.display = 'none';
    }
};

window.renderLogs = function () {
    var container = document.getElementById('logsPanelBody');
    if (!container) return;

    try {
        var stored = localStorage.getItem('aethrion_logs_v1');
        if (stored) {
            window.logsCache = JSON.parse(stored);
        }
    } catch (e) {}

    var filter = window.currentLogFilter || 'all';
    var logs = window.logsCache.slice().reverse();

    if (filter !== 'all') {
        logs = logs.filter(function (l) { return l.level === filter; });
    }

    if (logs.length === 0) {
        container.innerHTML = '<div class="logs-empty">📭 Bu filtrede log kaydı yok.</div>';
        return;
    }

    var html = '';
    logs.forEach(function (log) {
        var timeStr = '';
        try {
            timeStr = new Date(log.time).toLocaleString('tr-TR');
        } catch (e) { timeStr = log.time; }

        html += '<div class="logs-entry log-' + log.level + '">';
        html += '<span class="logs-entry-time">' + window.escapeHtml(timeStr) + '</span>';
        html += '<span>' + window.escapeHtml(log.message) + '</span>';
        html += '</div>';
    });
    container.innerHTML = html;
};

window.filterLogs = function (filter) {
    window.currentLogFilter = filter;
    document.querySelectorAll('.logs-filter-btn').forEach(function (btn) {
        if (btn.getAttribute('data-filter') === filter) {
            btn.classList.add('active');
        } else {
            btn.classList.remove('active');
        }
    });
    window.renderLogs();
};

window.refreshLogs = function () {
    window.renderLogs();
    showNotification('🔄 Loglar yenilendi', 'success');
};

window.clearLogs = function () {
    if (!confirm('Tüm log kayıtları temizlenecek. Emin misiniz?')) return;
    window.logsCache = [];
    try {
        localStorage.removeItem('aethrion_logs_v1');
    } catch (e) {}
    window.renderLogs();
    showNotification('🗑️ Loglar temizlendi', 'success');
};

window.downloadLogs = function () {
    if (window.logsCache.length === 0) {
        showNotification('İndirilecek log yok.', 'warning');
        return;
    }
    var text = 'AETHRION v1.0.0 — SİSTEM LOGLARI\n';
    text += 'Intelligence Without Limits.\n';
    text += '='.repeat(60) + '\n\n';
    text += 'Toplam: ' + window.logsCache.length + ' kayıt\n';
    text += 'Tarih: ' + new Date().toLocaleString('tr-TR') + '\n\n';
    text += '='.repeat(60) + '\n\n';
    window.logsCache.forEach(function (log) {
        text += '[' + log.time + '] [' + log.level.toUpperCase() + '] ' + log.message + '\n';
        if (log.meta) text += '   Meta: ' + JSON.stringify(log.meta) + '\n';
        text += '---\n';
    });
    var blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'aethrion-v1-logs-' + new Date().toISOString().slice(0, 10) + '.txt';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showNotification('📥 Loglar indirildi', 'success');
};

