window.checkExistingSession = async function () {
    try {
        if (typeof Parse === 'undefined') return null;
        var user = Parse.User.current();
        if (!user) return null;

        await user.fetch();

        if (user.get('isBanned')) {
            await Parse.User.logOut();
            localStorage.removeItem('aethrion_user');
            console.warn('⚠️ Yasaklı kullanıcı oturumu kapatıldı');
            return null;
        }

        window.currentUser = user;
        if (typeof currentUser !== 'undefined') currentUser = user;

        localStorage.setItem('aethrion_user', JSON.stringify({
            id: user.id,
            name: user.get('name'),
            email: user.get('email'),
            role: user.get('role'),
            plan: user.get('plan'),
            teamId: user.get('teamId')
        }));

        console.log('✅ Oturum aktif:', user.get('email'));
        return user;
    } catch (e) {
        console.warn('Oturum kontrolü hatası:', e.message);
        try { await Parse.User.logOut(); } catch (e2) {}
        localStorage.removeItem('aethrion_user');
        return null;
    }
};

// ============================================================
// COUNTER ANİMASYONU
// ============================================================
function animateCounter(el, target, duration) {
    if (!el) return;
    var startTime = null;

    function step(timestamp) {
        if (!startTime) startTime = timestamp;
        var progress = Math.min((timestamp - startTime) / duration, 1);
        var current = Math.floor(progress * target);
        el.textContent = current.toLocaleString('tr-TR');
        if (progress < 1) {
            requestAnimationFrame(step);
        } else {
            el.textContent = target.toLocaleString('tr-TR');
        }
    }
    requestAnimationFrame(step);
}

function initCounters() {
    var c1 = document.getElementById('counter1');
    var c2 = document.getElementById('counter2');
    var c3 = document.getElementById('counter3');
    if (c1) animateCounter(c1, 15840, 2000);
    if (c2) animateCounter(c2, 247500, 2500);
    if (c3) animateCounter(c3, 8920, 2200);
}

// ============================================================
// STATS — updateStats / interval
// ============================================================
window.updateStats = async function () {
    try {
        if (typeof Parse === 'undefined' || !window.parseInitialized) return;
        var result = await Parse.Cloud.run('getPublicStats', {}).catch(function () { return null; });
        if (result && result.success) {
            if (result.activeUsers) {
                var c1 = document.getElementById('counter1');
                if (c1) c1.textContent = result.activeUsers.toLocaleString('tr-TR');
            }
            if (result.totalQueries) {
                var c2 = document.getElementById('counter2');
                if (c2) c2.textContent = result.totalQueries.toLocaleString('tr-TR');
            }
            if (result.completedProjects) {
                var c3 = document.getElementById('counter3');
                if (c3) c3.textContent = result.completedProjects.toLocaleString('tr-TR');
            }
        }
    } catch (e) {
        // sessiz geç
    }
};

window.startStatsInterval = function () {
    if (window.statsInterval) clearInterval(window.statsInterval);
    window.statsInterval = setInterval(function () {
        window.updateStats();
    }, 60000);
};

window.stopStatsInterval = function () {
    if (window.statsInterval) {
        clearInterval(window.statsInterval);
        window.statsInterval = null;
    }
};

// ============================================================
// TEMA — Light / Dark
// ============================================================
window.toggleTheme = function () {
    var html = document.documentElement;
    var body = document.body;
    var current = body.getAttribute('data-theme') || 'dark';
    var newTheme = current === 'dark' ? 'light' : 'dark';

    body.setAttribute('data-theme', newTheme);
    if (newTheme === 'light') {
        html.setAttribute('data-theme', 'light');
    } else {
        html.removeAttribute('data-theme');
    }

    try { localStorage.setItem('aethrion_theme', newTheme); } catch (e) {}

    var btn = document.querySelector('.theme-toggle-btn');
    if (btn) btn.textContent = newTheme === 'dark' ? '🌙' : '☀️';

    if (typeof window.addLogInfo === 'function') {
        window.addLogInfo('Tema değiştirildi: ' + newTheme);
    }
};

window.applyTheme = function () {
    var saved = 'dark';
    try { saved = localStorage.getItem('aethrion_theme') || 'dark'; } catch (e) {}
    document.body.setAttribute('data-theme', saved);
    if (saved === 'light') {
        document.documentElement.setAttribute('data-theme', 'light');
    }
    var btn = document.querySelector('.theme-toggle-btn');
    if (btn) btn.textContent = saved === 'dark' ? '🌙' : '☀️';
};

