window.loginWithGoogle = function () {
    if (window._googleLoginInProgress) {
        console.log('⏳ Google giriş zaten devam ediyor...');
        return;
    }

    if (typeof google === 'undefined' || !google.accounts || !google.accounts.id) {
        showNotification('❌ Google SDK yüklenemedi. Sayfayı yenileyin veya reklam engelleyicinizi kapatın.', 'error');
        console.error('⚠️ Google GIS SDK bulunamadı.');
        window.addLogError('Google GIS SDK yüklenemedi');
        return;
    }

    if (!window._googleGISReady) {
        window.handleGoogleLibraryLoad();
        setTimeout(window.loginWithGoogle, 500);
        return;
    }

    window._googleLoginInProgress = true;
    showNotification('🔵 Google ile giriş başlatılıyor...', 'success');

    try {
        google.accounts.id.prompt(function (notification) {
            if (notification && (notification.isNotDisplayed() || notification.isSkippedMoment())) {
                console.log('ℹ️ Google One Tap gösterilemedi; resmi Google giriş düğmesi gösteriliyor.');
                window._googleLoginInProgress = false;
                showNotification('Google hızlı giriş açılamadı; alternatif Google giriş düğmesi açılıyor.', 'warning');
                showAethrionGoogleFallback();
            }
        });
    } catch (e) {
        console.error('Google prompt hatası:', e);
        window._googleLoginInProgress = false;
        showNotification('❌ Google girişi başlatılamadı: ' + e.message, 'error');
    }
};

// --- Google GIS callback ---
window.handleGoogleLoginResponse = async function (response) {
    var googleFallback = document.getElementById('aethrionGoogleFallback');
    if (googleFallback) googleFallback.remove();
    if (!response || !response.credential) {
        console.warn('⚠️ Google credential alınamadı');
        window._googleLoginInProgress = false;
        return;
    }

    console.log('✅ Google credential alındı');
    if (typeof window.addLogInfo === 'function') {
        window.addLogInfo('Google credential alındı (AETHRION)');
    }

    showNotification('⏳ Google hesabı doğrulanıyor...', 'success');

    try {
        // JWT'den sub ve email çıkar
        var parts = response.credential.split('.');
        if (parts.length < 2) throw new Error('Geçersiz Google token');

        var payload = JSON.parse(atob(parts[1].replace(/-/g, '+').replace(/_/g, '/')));
        var googleUserId = payload.sub;
        var googleEmail = payload.email;
        var googleName = payload.name || '';

        if (!googleUserId) throw new Error('Google user ID bulunamadı');

        var urlRefCode = typeof window.getReferralCodeFromUrl === 'function'
            ? window.getReferralCodeFromUrl() : '';

        var result = await aethrionAuthCallWithTimeout(function () { return Parse.Cloud.run('verifyGoogleToken', {
            idToken: response.credential,
            userId: googleUserId,
            email: googleEmail,
            name: googleName,
            referralCode: urlRefCode,
            termsAccepted: true,
            privacyAccepted: true
        }); }, 18000, 'Google giriş sunucusu 18 saniye içinde yanıt vermedi. Back4App Cloud Code ayarlarını kontrol edin.');

        if (!result || !result.success) {
            throw new Error((result && result.error) || 'Google girişi başarısız.');
        }

        var user = await Parse.User.become(result.sessionToken);
        if (!user) throw new Error('Oturum açılamadı (become başarısız).');

        if (user.get('isBanned')) {
            await Parse.User.logOut();
            showNotification('Hesabınız yasaklanmıştır!', 'error');
            window._googleLoginInProgress = false;
            return;
        }

        window.currentUser = user;
        if (typeof currentUser !== 'undefined') currentUser = user;

        localStorage.setItem('aethrion_user', JSON.stringify({
            id: user.id,
            name: user.get('name'),
            email: user.get('email'),
            role: user.get('role'),
            plan: user.get('plan'),
            teamId: user.get('teamId')
        }));

        closeModal('authModal');
        // The legacy app wraps showDashboard in several independent initializers.
        // Bound that chain so a never-settling initializer cannot block a valid login.
        var dashboardAttempt = null;
        try {
            dashboardAttempt = Promise.resolve().then(function () { return window.showDashboard(); });
            var dashboardTimer;
            try {
                await Promise.race([
                    dashboardAttempt,
                    new Promise(function (resolve) { dashboardTimer = window.setTimeout(resolve, 5000); })
                ]);
            } finally {
                if (dashboardTimer) window.clearTimeout(dashboardTimer);
            }
        } catch (dashboardError) {
            console.warn('[AETHRION Auth] Dashboard initializer failed; applying authenticated fallback.', dashboardError);
        }
        // Reconcile legacy dashboard guards/overrides after a confirmed Parse session.
        // A successful login must never silently return to the landing page.
        var authDashboard = document.getElementById('dashboardArea');
        var authMainSite = document.getElementById('mainSite');
        if (Parse.User.current() && authDashboard) {
            document.body.classList.add('logged-in-user');
            authDashboard.style.setProperty('display', 'block', 'important');
            authDashboard.style.setProperty('visibility', 'visible', 'important');
            authDashboard.style.setProperty('opacity', '1', 'important');
            if (authMainSite) authMainSite.style.setProperty('display', 'none', 'important');
        }
        if (!Parse.User.current()) throw new Error('Giriş doğrulandı ancak oturum bu cihazda kaydedilemedi. Tekrar giriş yapın.');
        if (typeof window.updateCommentUI === 'function') window.updateCommentUI();
        if (typeof window.loadComments === 'function') await window.loadComments();
        if (typeof window.refreshUserLimits === 'function') window.refreshUserLimits();

        showNotification('✅ Google ile giriş başarılı! AETHRION\'a hoş geldin, ' + (user.get('name') || 'Kullanıcı'), 'success');
        if (typeof window.addLogSuccess === 'function') {
            window.addLogSuccess('Google girişi başarılı: ' + (user.get('email') || ''));
        }

        // Profil tamamlama kontrolü
        var profileCompleted = user.get('profile_completed');
        var hasRecoveryEmail = !!user.get('recovery_email');

        if (profileCompleted === false || profileCompleted === undefined || !hasRecoveryEmail) {
            window._fbPendingProfile = {
                name: googleName || user.get('name') || '',
                email: googleEmail || user.get('email') || ''
            };
            window._fbPendingEmail = googleEmail || user.get('email') || '';
            window._fbPendingProvider = 'google';

            console.log('📝 Google profili tamamlanmamış, modal açılıyor...');
            if (typeof window.addLogInfo === 'function') {
                window.addLogInfo('Google profil tamamlama modalı açılıyor');
            }
            setTimeout(function () {
                window.openProfileCompletionModal();
            }, 500);
        } else {
            console.log('✅ Google profili zaten tamamlanmış.');
        }

        window._googleLoginInProgress = false;
    } catch (e) {
        console.error('Google login hatası:', e);
        window._googleLoginInProgress = false;
        showNotification('❌ Google giriş hatası: ' + e.message, 'error');
        if (typeof window.addLogError === 'function') {
            window.addLogError('Google giriş hatası: ' + e.message);
        }
    }
};

// ============================================================
// [AETHRION] requireSocialTerms — Google + Facebook öncesi onay
// ============================================================
window.requireSocialTerms = function (provider) {
    if (provider !== 'google' && provider !== 'facebook') {
        console.warn('Geçersiz provider:', provider);
        return;
    }

    window._pendingSocialProvider = provider;

    var modal = document.getElementById('socialAuthTermsModal');
    if (!modal) {
        // Fallback: modal yoksa direkt çalıştır
        console.warn('socialAuthTermsModal bulunamadı, direkt giriş yapılıyor.');
        if (provider === 'google' && typeof window.loginWithGoogle === 'function') {
            window.loginWithGoogle();
        } else if (provider === 'facebook' && typeof window.loginWithFacebook === 'function') {
            window.loginWithFacebook();
        }
        return;
    }

    var termsCheck = document.getElementById('socialTermsCheck');
    var privacyCheck = document.getElementById('socialPrivacyCheck');
    var errBox = document.getElementById('socialAuthTermsError');
    if (termsCheck) termsCheck.checked = false;
    if (privacyCheck) privacyCheck.checked = false;
    if (errBox) { errBox.style.display = 'none'; errBox.textContent = ''; }

    modal.classList.add('open');
    modal.style.display = 'flex';
};

window.confirmSocialAuthTerms = function () {
    var provider = window._pendingSocialProvider;
    if (!provider) {
        window.closeModal('socialAuthTermsModal');
        return;
    }

    var termsCheck = document.getElementById('socialTermsCheck');
    var privacyCheck = document.getElementById('socialPrivacyCheck');
    var errBox = document.getElementById('socialAuthTermsError');

    function showErr(msg) {
        if (errBox) {
            errBox.textContent = '❌ ' + msg;
            errBox.style.display = 'block';
        }
        showNotification('❌ ' + msg, 'error');
    }

    if (errBox) { errBox.style.display = 'none'; errBox.textContent = ''; }

    if (!termsCheck || !termsCheck.checked) {
        return showErr('Kullanıcı Sözleşmesi\'ni kabul etmelisiniz.');
    }
    if (!privacyCheck || !privacyCheck.checked) {
        return showErr('Gizlilik Politikası\'nı kabul etmelisiniz.');
    }

    try {
        if (typeof window.addLogInfo === 'function') {
            window.addLogInfo('Sosyal giriş sözleşme onayı verildi: ' + provider);
        }
    } catch (e) {}

    window.closeModal('socialAuthTermsModal');
    window._pendingSocialProvider = null;

    if (provider === 'google') {
        if (typeof window.loginWithGoogle === 'function') {
            window.loginWithGoogle();
        } else {
            showNotification('Google giriş fonksiyonu yüklenmedi!', 'error');
        }
    } else if (provider === 'facebook') {
        if (typeof window.loginWithFacebook === 'function') {
            window.loginWithFacebook();
        } else {
            showNotification('Facebook giriş fonksiyonu yüklenmedi!', 'error');
        }
    }
};

// ============================================================
// [AETHRION] KAYIT — Checkbox zorunluluğu + 28 model
// ============================================================
async function aethrionAuthCallWithTimeout(call, ms, message) {
    var timer;
    try {
        return await Promise.race([
            Promise.resolve().then(call),
            new Promise(function (_, reject) {
                timer = window.setTimeout(function () { reject(new Error(message || 'Kimlik doğrulama sunucusu zaman aşımına uğradı.')); }, Math.max(5000, Math.min(20000, Number(ms) || 15000)));
            })
        ]);
    } finally {
        if (timer) window.clearTimeout(timer);
    }
}

async function handleRegister() {
    var nameInput = document.getElementById('rName');
    var emailInput = document.getElementById('rEmail');
    var usernameInput = document.getElementById('rUsername');
    var passInput = document.getElementById('rPass');
    var pass2Input = document.getElementById('rPass2');
    var referralInput = document.getElementById('rReferralCode');
    var name = nameInput ? nameInput.value.trim() : '';
    var email = emailInput ? emailInput.value.trim().toLowerCase() : '';
    var username = usernameInput ? usernameInput.value.trim() : '';
    var p1 = passInput ? passInput.value : '';
    var p2 = pass2Input ? pass2Input.value : '';
    var referralCode = referralInput ? referralInput.value.trim() : '';
    var terms = document.getElementById('registerTermsCheck');
    var privacy = document.getElementById('registerPrivacyCheck');
    var signupCompleted = false;

    function withTimeout(promise, ms, message) {
        var timer;
        return Promise.race([
            Promise.resolve(promise),
            new Promise(function (_, reject) {
                timer = window.setTimeout(function () { reject(new Error(message)); }, ms);
            })
        ]).finally(function () { if (timer) window.clearTimeout(timer); });
    }

    function openVerificationStep() {
        if (typeof window.switchTab === 'function') {
            window.switchTab('verify');
        } else {
            var registerForm = document.getElementById('formRegister');
            var loginForm = document.getElementById('formLogin');
            var verifyForm = document.getElementById('formVerify');
            if (registerForm) registerForm.style.display = 'none';
            if (loginForm) loginForm.style.display = 'none';
            if (verifyForm) verifyForm.style.display = 'block';
        }
        var verifyEmailInput = document.getElementById('verifyEmail');
        if (verifyEmailInput) {
            verifyEmailInput.value = email;
            verifyEmailInput.readOnly = false;
            verifyEmailInput.disabled = false;
            verifyEmailInput.style.pointerEvents = 'auto';
        }
    }

    if (!terms || !terms.checked) {
        showNotification('Kayıt olmak için Kullanıcı Sözleşmesi\'ni kabul etmelisiniz.', 'error');
        return false;
    }
    if (!privacy || !privacy.checked) {
        showNotification('Kayıt olmak için Gizlilik Politikası\'nı kabul etmelisiniz.', 'error');
        return false;
    }
    if (!name || !email || !username || p1.length < 8 || p1 !== p2) {
        showNotification('Tüm alanları doldurun; şifreler aynı ve en az 8 karakter olmalı.', 'error');
        if (typeof window.addLogWarning === 'function') window.addLogWarning('Kayıt formu eksik dolduruldu');
        return false;
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        showNotification('Geçerli bir e-posta adresi girin.', 'error');
        return false;
    }

    try {
        if (!window.Parse || !window.Parse.User) throw new Error('Kimlik doğrulama servisi hazır değil. Sayfayı yenileyip tekrar deneyin.');

        var user = new Parse.User();
        user.set('username', email);
        user.set('email', email);
        user.set('password', p1);
        user.set('name', name);
        user.set('username_display', username);
        user.set('role', 'user');
        user.set('plan', 'free');
        user.set('isVerified', false);
        user.set('isBanned', false);
        user.set('points', 0);
        user.set('level', 'Çaylak');
        user.set('badges', []);
        user.set('followers', []);
        user.set('following', []);
        user.set('parent_mode', false);
        user.set('is_verified_seller', false);
        user.set('wallet_balance', 0);
        user.set('bio', '');
        user.set('profile_picture', null);
        user.set('gift_given', false);
        user.set('referral_count', 0);
        user.set('invited_by', '');
        user.set('teamId', null);
        user.set('completed_lessons', []);
        user.set('completed_daily_tasks', []);
        user.set('completed_social_tasks', []);
        user.set('completed_team_tasks', []);
        user.set('profile_completed', true);
        user.set('password_set', true);
        user.set('terms_accepted', true);
        user.set('privacy_accepted', true);
        user.set('terms_accepted_at', new Date());

        var namePart = name.substring(0, 4).toUpperCase();
        var randomPart = Math.floor(1000 + Math.random() * 9000);
        user.set('referral_code', 'A27-' + namePart + '-' + randomPart);
        user.set('invited_by', referralCode || '');
        user.set('usage_vizyonAlPerDay', 0);
        user.set('usage_voiceChatMinutesPerDay', 0);
        user.set('usage_fileAnalyzePerDay', 0);
        user.set('usage_videoCreatePerMonth', 0);
        user.set('usage_lastReset', new Date());

        // Bound signup wait so the progress overlay can never cover the auth UI indefinitely.
        await withTimeout(
            user.signUp(),
            25000,
            'Kayıt sunucusu 25 saniye içinde yanıt vermedi. Bağlantıyı kontrol edin; aynı e-postayla tekrar denemeden önce hesabın oluşup oluşmadığını kontrol edin.'
        );
        signupCompleted = true;

        if (typeof window.addLogSuccess === 'function') {
            window.addLogSuccess('Yeni AETHRION kullanıcı kaydı oluşturuldu; e-posta doğrulaması bekleniyor.');
        }

        // Move to the verification form immediately after account creation. Email delivery
        // is asynchronous so a slow mail provider cannot leave the "registering" overlay up.
        openVerificationStep();
        showNotification('Hesabınız oluşturuldu. Doğrulama kodu e-postanıza gönderiliyor…', 'info');

        // Generate and persist the verification code only on the server; do not expose it
        // in browser code or wait for the mail provider before showing the verification form.
        withTimeout(
            Parse.Cloud.run('resendAccountVerification', { email: email }),
            20000,
            'E-posta sağlayıcısı 20 saniye içinde yanıt vermedi.'
        ).then(function (mailResult) {
            if (!mailResult || mailResult.success !== true) {
                throw new Error((mailResult && mailResult.error) || 'E-posta sağlayıcısı gönderimi onaylamadı.');
            }
            showNotification('Doğrulama kodu e-postanıza gönderildi. Gelen kutusu ve spam klasörünü kontrol edin.', 'success');
            if (typeof window.addLogSuccess === 'function') window.addLogSuccess('Doğrulama e-postası gönderimi onaylandı.');
        }).catch(function (mailError) {
            console.error('[AETHRION Auth] Verification email delivery failed:', mailError);
            if (typeof window.addLogWarning === 'function') {
                window.addLogWarning('Doğrulama e-postası gönderilemedi; doğrulama ekranından yeni kod isteyebilirsiniz.');
            }
            var deliveryDetail = String((mailError && mailError.message) || 'E-posta sağlayıcısı yanıt vermedi.').replace(/[\\r\\n]+/g, ' ').slice(0, 220);
            showNotification('Hesabınız oluşturuldu ancak doğrulama e-postası gönderilemedi: ' + deliveryDetail + ' Yeni Kod Gönder ile tekrar deneyin.', 'warning');
        });

        // Referral processing is non-critical and must not block account verification.
        if (referralCode) {
            withTimeout(Parse.Cloud.run('applyReferral', { code: referralCode }), 8000, 'Davet kodu işlemi zaman aşımına uğradı.')
                .then(function () {
                    if (typeof window.addLogInfo === 'function') window.addLogInfo('Davet kodu uygulandı.');
                })
                .catch(function (referralError) {
                    console.warn('[AETHRION Auth] Referral processing failed:', referralError);
                    if (typeof window.addLogWarning === 'function') window.addLogWarning('Davet kodu daha sonra tekrar uygulanabilir.');
                });
        }

        return true;
    } catch (e) {
        console.error('[AETHRION Auth] Registration failed:', e);
        if (signupCompleted) {
            try { openVerificationStep(); } catch (_) {}
            showNotification('Hesabınız oluşturuldu. Doğrulama ekranından yeni kod isteyebilirsiniz.', 'warning');
            return true;
        }
        showNotification('Kayıt tamamlanamadı: ' + (e && e.message ? e.message : 'Bilinmeyen hata'), 'error');
        if (typeof window.addLogError === 'function') {
            window.addLogError('Kayıt hatası: ' + (e && e.message ? e.message : 'Bilinmeyen hata'));
        }
        return false;
    }
}

// Explicitly expose the handler used by the inline registration button.
window.handleRegister = handleRegister;

// ============================================================
// [AETHRION] DOĞRULAMA
// ============================================================
window.resendAccountVerification = async function () {
    var emailInput = document.getElementById('verifyEmail');
    var email = emailInput ? emailInput.value.trim().toLowerCase() : '';
    if (!email) {
        showNotification('Yeni kod istemeden önce e-posta adresinizi girin.', 'error');
        return;
    }
    var button = document.querySelector('#formVerify button[onclick="window.resendAccountVerification()"]');
    if (button) { button.disabled = true; button.dataset.originalText = button.textContent; button.textContent = 'Gönderiliyor…'; }
    try {
        var result = await Parse.Cloud.run('resendAccountVerification', { email: email });
        if (!result || result.success !== true) throw new Error((result && result.error) || 'Kod gönderilemedi.');
        showNotification('Hesap uygunsa yeni doğrulama kodu gönderildi. Gelen kutusu ve spam klasörünü kontrol edin.', 'success');
    } catch (e) {
        showNotification(e.message || 'Kod gönderilemedi. E-posta ayarlarını kontrol edin.', 'error');
    } finally {
        if (button) { button.disabled = false; button.textContent = button.dataset.originalText || 'Yeni Kod Gönder'; }
    }
};

async function verifyAccount() {
    var email = document.getElementById('verifyEmail').value.trim().toLowerCase();
    var code = document.getElementById('verifyCode').value.trim();

    if (!email || !code) {
        showNotification('Tüm alanları doldurun!', 'error');
        return;
    }

    try {
        var result = await aethrionAuthCallWithTimeout(function () { return Parse.Cloud.run('verifyUser', {
            email: email,
            code: code
        }); }, 15000, 'Doğrulama sunucusu 15 saniye içinde yanıt vermedi. Tekrar deneyin.');

        if (result.success) {
            showNotification('✅ Hesap doğrulandı! Giriş yapabilirsiniz.', 'success');
            if (typeof window.addLogSuccess === 'function') {
                window.addLogSuccess('Hesap doğrulandı: ' + email);
            }
            switchTab('login');
        } else {
            showNotification('❌ ' + result.error, 'error');
            if (typeof window.addLogWarning === 'function') {
                window.addLogWarning('Doğrulama başarısız: ' + result.error);
            }
        }
    } catch (e) {
        showNotification('Hata: ' + e.message, 'error');
        if (typeof window.addLogError === 'function') {
            window.addLogError('Doğrulama hatası: ' + e.message);
        }
    }
}

// ============================================================
// [AETHRION] GİRİŞ — Checkbox zorunluluğu
// ============================================================
async function handleLogin() {
    var email = document.getElementById('lEmail').value.trim();
    var pass = document.getElementById('lPass').value;

    var loginTermsCheck = document.getElementById('loginTermsCheck');
    var loginPrivacyCheck = document.getElementById('loginPrivacyCheck');

    if (!loginTermsCheck || !loginTermsCheck.checked) {
        showNotification('❌ Giriş yapmak için Kullanıcı Sözleşmesi\'ni kabul etmelisiniz.', 'error');
        return false;
    }
    if (!loginPrivacyCheck || !loginPrivacyCheck.checked) {
        showNotification('❌ Giriş yapmak için Gizlilik Politikası\'nı kabul etmelisiniz.', 'error');
        return;
    }

    if (!email || !pass) {
        showNotification('Tüm alanları doldurun!', 'error');
        return;
    }

    try {
        window.__aethrionLastAuthError = '';
        var authResult = await aethrionAuthCallWithTimeout(function () { return Parse.Cloud.run('aethrionLoginWithEmail', {
            email: email,
            password: pass
        }); }, 18000, 'Giriş sunucusu 18 saniye içinde yanıt vermedi. Back4App Cloud Code durumunu kontrol edip tekrar deneyin.');
        if (!authResult || authResult.success !== true) {
            if (authResult && authResult.code === 'EMAIL_NOT_VERIFIED') {
                window.__aethrionLastAuthError = authResult.error || 'Hesap e-posta doğrulaması bekliyor.';
                showNotification(window.__aethrionLastAuthError, 'warning');
                window.switchTab('verify');
                var verifyEmailInput = document.getElementById('verifyEmail');
                if (verifyEmailInput) {
                    verifyEmailInput.value = email;
                    verifyEmailInput.readOnly = false;
                    verifyEmailInput.disabled = false;
                }
                return false;
            }
            throw new Error((authResult && authResult.error) || 'Giriş tamamlanamadı. E-posta ve şifreyi kontrol edin.');
        }
        if (!authResult.sessionToken) {
            throw new Error('Sunucu oturum belirteci döndürmedi. Back4App Cloud Code dağıtımını kontrol edin.');
        }
        var user = await Parse.User.become(authResult.sessionToken);
        if (!user) throw new Error('Oturum açılamadı. Lütfen tekrar deneyin.');

        if (user.get('isBanned')) {
            await Parse.User.logOut();
            showNotification('Hesabınız yasaklanmıştır!', 'error');
            if (typeof window.addLogWarning === 'function') {
                window.addLogWarning('Yasaklı kullanıcı giriş denemesi: ' + email);
            }
            return;
        }

        if (!user.get('isVerified')) {
            await Parse.User.logOut();
            showNotification('Hesap doğrulanmamış! Lütfen doğrulama kodunu girin.', 'error');
            if (typeof window.addLogWarning === 'function') {
                window.addLogWarning('Doğrulanmamış hesap giriş denemesi: ' + email);
            }
            switchTab('verify');
            document.getElementById('verifyEmail').value = email;
            return;
        }

        window.currentUser = user;
        if (typeof currentUser !== 'undefined') currentUser = user;

        localStorage.setItem('aethrion_user', JSON.stringify({
            id: user.id,
            name: user.get('name'),
            email: user.get('email'),
            role: user.get('role'),
            plan: user.get('plan'),
            teamId: user.get('teamId'),
            points: user.get('points') || 0,
            username: user.get('username_display')
        }));

        closeModal('authModal');
        await window.showDashboard();
        if (typeof window.updateCommentUI === 'function') window.updateCommentUI();
        if (typeof window.loadComments === 'function') await window.loadComments();
        if (typeof window.updatePointsDisplay === 'function') {
            window.updatePointsDisplay(user.get('points') || 0);
        }

        if (typeof window.refreshUserLimits === 'function') {
            window.refreshUserLimits();
        }

        if (user.get('parent_mode')) {
            var pb = document.getElementById('parentSettingsBtn');
            if (pb) pb.style.display = 'inline-block';
        }

        if (user.get('role') === 'admin' ||
            user.get('role') === 'founder' ||
            user.get('role') === 'moderator' ||
            user.get('role') === 'beta') {
            try {
                await Parse.Cloud.run('initAdminUsers');
            } catch (e) {}
        }

        try {
            if (typeof checkStreakStatus === 'function') await checkStreakStatus();
        } catch (e) {}

        showNotification('AETHRION\'a hoş geldin, ' + user.get('name'), 'success');
        if (typeof window.addLogSuccess === 'function') {
            window.addLogSuccess('Kullanıcı girişi başarılı: ' + email +
                ' (rol: ' + user.get('role') + ', plan: ' + user.get('plan') + ')');
        }
        window.__aethrionLastAuthError = '';
        return true;
    } catch (e) {
        window.__aethrionLastAuthError = String((e && e.message) || 'Bilinmeyen kimlik doğrulama hatası').slice(0, 240);
        console.error('Giriş hatası:', e.message);
        showNotification('Giriş başarısız: ' + e.message, 'error');
        if (typeof window.addLogError === 'function') {
            window.addLogError('Giriş hatası: ' + e.message, { email: email });
        }
        return false;
    }
}

