window.handleLogin = handleLogin;

// ============================================================
// [AETHRION] FACEBOOK İLE GİRİŞ — Checkbox zorunluluğu
// ============================================================
async function waitForAethrionFacebookSDK(timeoutMs) {
    var deadline = Date.now() + (Number(timeoutMs) || 8000);
    while (Date.now() < deadline) {
        if (typeof FB !== 'undefined' && FB && typeof FB.login === 'function') return true;
        await new Promise(function (resolve) { window.setTimeout(resolve, 200); });
    }
    return typeof FB !== 'undefined' && FB && typeof FB.login === 'function';
}

window.loginWithFacebook = async function () {
    try {
        if (!(await waitForAethrionFacebookSDK(8000))) {
            showNotification('Facebook bağlantısı başlatılamadı. SDK yüklenemedi; bağlantıyı kontrol edip tekrar deneyin.', 'error');
            console.error('⚠️ Facebook SDK 8 saniye içinde hazır olmadı.');
            if (typeof window.addLogError === 'function') {
                window.addLogError('Facebook SDK yüklenemedi');
            }
            return;
        }

        showNotification('🔵 Facebook ile giriş başlatılıyor...', 'success');

        var fbResponse = await new Promise(function (resolve, reject) {
            FB.login(function (response) {
                if (response && response.authResponse) {
                    resolve(response.authResponse);
                } else if (response && response.status === 'unknown') {
                    reject(new Error('Facebook girişi iptal edildi veya tamamlanamadı.'));
                } else {
                    reject(new Error('Facebook giriş bilgisi alınamadı.'));
                }
            }, {
                scope: 'public_profile,email',
                return_scopes: true
            });
        });

        var accessToken = fbResponse.accessToken;
        var userID = fbResponse.userID;

        if (!accessToken || !userID) {
            showNotification('❌ Facebook access token alınamadı!', 'error');
            return;
        }

        console.log('✅ Facebook token alındı. User ID:', userID);
        if (typeof window.addLogInfo === 'function') {
            window.addLogInfo('Facebook token alındı');
        }

        var urlRefCode = typeof window.getReferralCodeFromUrl === 'function'
            ? window.getReferralCodeFromUrl() : null;

        var result = await aethrionAuthCallWithTimeout(function () { return Parse.Cloud.run('facebookLogin', {
            accessToken: accessToken,
            userID: userID,
            referralCode: urlRefCode || '',
            termsAccepted: true,
            privacyAccepted: true
        }); }, 18000, 'Facebook giriş sunucusu 18 saniye içinde yanıt vermedi. Back4App Cloud Code ayarlarını kontrol edin.');

        if (!result || !result.success) {
            throw new Error(result && result.error ? result.error : 'Facebook girişi başarısız oldu.');
        }

        var user = await Parse.User.become(result.sessionToken);
        if (!user) throw new Error('Oturum açılamadı (become başarısız).');

        if (user.get('isBanned')) {
            await Parse.User.logOut();
            showNotification('Hesabınız yasaklanmıştır!', 'error');
            if (typeof window.addLogWarning === 'function') {
                window.addLogWarning('Yasaklı FB kullanıcısı giriş denemesi');
            }
            return;
        }

        window.currentUser = user;
        if (typeof currentUser !== 'undefined') currentUser = user;

        localStorage.setItem('aethrion_user', JSON.stringify({
            id: user.id,
            name: user.get('name'),
            email: user.get('email'),
            role: user.get('role'),
            plan: user.get('plan'),
            teamId: user.get('teamId')
        }));

        closeModal('authModal');
        await window.showDashboard();
        if (typeof window.updateCommentUI === 'function') window.updateCommentUI();
        if (typeof window.loadComments === 'function') await window.loadComments();
        if (typeof window.checkAndShowSubscriptionCard === 'function') {
            await window.checkAndShowSubscriptionCard();
        }

        if (typeof window.refreshUserLimits === 'function') {
            window.refreshUserLimits();
        }

        showNotification('✅ Facebook ile giriş başarılı! AETHRION\'a hoş geldin, ' + (user.get('name') || 'Kullanıcı'), 'success');
        if (typeof window.addLogSuccess === 'function') {
            window.addLogSuccess('Facebook girişi başarılı: ' + (user.get('email') || 'email yok'));
        }

        // Profil tamamlama kontrolü (Google VE Facebook için ortak)
        var profileCompleted = user.get('profile_completed');
        var hasRecoveryEmail = !!user.get('recovery_email');

        if (profileCompleted === false || profileCompleted === undefined || !hasRecoveryEmail) {
            window._fbPendingProfile = {
                name: result.name || user.get('name') || '',
                email: result.email || user.get('email') || ''
            };
            window._fbPendingEmail = result.email || user.get('email') || '';
            window._fbPendingProvider = 'facebook';

            console.log('📝 FB profili tamamlanmamış, modal açılıyor...');
            if (typeof window.addLogInfo === 'function') {
                window.addLogInfo('FB profil tamamlama modalı açılıyor');
            }
            setTimeout(function () {
                window.openProfileCompletionModal();
            }, 500);
        } else {
            console.log('✅ FB profili zaten tamamlanmış.');
        }
    } catch (e) {
        console.error('Facebook giriş hatası:', e);
        if (typeof window.addLogError === 'function') {
            window.addLogError('Facebook giriş hatası: ' + e.message);
        }

        var errorMsg = e.message || 'Bilinmeyen hata';

        if (errorMsg.indexOf('cancel') !== -1 || errorMsg.indexOf('iptal') !== -1) {
            showNotification('❌ Facebook girişi iptal edildi.', 'warning');
        } else if (errorMsg.indexOf('popup') !== -1 || errorMsg.indexOf('blocked') !== -1) {
            showNotification('❌ Facebook penceresi engellendi. Lütfen tarayıcı ayarlarınızdan izin verin.', 'error');
        } else if (errorMsg.indexOf('app_id') !== -1 || errorMsg.indexOf('App ID') !== -1) {
            showNotification('❌ Facebook App ID yapılandırılmamış. Lütfen yöneticiye başvurun.', 'error');
        } else if (errorMsg.indexOf('Invalid') !== -1 || errorMsg.indexOf('invalid') !== -1) {
            showNotification('❌ Geçersiz Facebook token. Lütfen tekrar deneyin.', 'error');
        } else if (errorMsg.indexOf('already exists') !== -1) {
            showNotification('❌ Bu e-posta ile bir hesap zaten var. E-posta ile giriş yapın.', 'error');
        } else {
            showNotification('❌ Facebook giriş hatası: ' + errorMsg, 'error');
        }
    }
};

