window.logout = function () {
    if (!confirm('AETHRION\'dan çıkış yapmak istediğinize emin misiniz?')) return;

    if (typeof window.addLogInfo === 'function') {
        window.addLogInfo('Kullanıcı çıkış yapıyor: ' +
            (window.currentUser ? window.currentUser.get('email') : 'bilinmiyor'));
    }

    Parse.User.logOut();
    localStorage.removeItem('aethrion_user');
    window.currentUser = null;
    if (typeof currentUser !== 'undefined') currentUser = null;

    if (typeof window.stopStatsInterval === 'function') {
        window.stopStatsInterval();
    }

    try {
        document.documentElement.classList.remove('dashboard-open');
        document.body.classList.remove('dashboard-open');
    } catch (e) {}

    var mainSite = document.getElementById('mainSite');
    if (mainSite) mainSite.style.display = 'block';
    var dashboardArea = document.getElementById('dashboardArea');
    if (dashboardArea) dashboardArea.style.display = 'none';
    var userPanel = document.getElementById('userPanel');
    if (userPanel) userPanel.style.display = 'none';

    if (typeof window.closeFullAIPanel === 'function') window.closeFullAIPanel();
    if (typeof window.closeKocPanel === 'function') window.closeKocPanel();
    if (typeof window.closeVizyonAlPanel === 'function') window.closeVizyonAlPanel();
    if (typeof window.closeVoiceChatFullscreen === 'function') window.closeVoiceChatFullscreen();

    var logoutBtn = document.querySelector('.logout-btn');
    if (logoutBtn) logoutBtn.style.display = 'none';

    if (typeof window.updateCommentUI === 'function') window.updateCommentUI();

    var wrapper = document.getElementById('subscriptionsCardWrapper');
    if (wrapper) wrapper.style.display = 'none';

    showNotification('AETHRION\'dan çıkış yapıldı.', 'success');

    var widget = document.querySelector('.ai-widget');
    if (widget) widget.style.display = 'block';
};

// ============================================================
// MODAL VE TAB YÖNETİMİ
// ============================================================
window.openModal = function (type) {
    var modal = document.getElementById('authModal');
    if (!modal) return console.error('authModal elementi bulunamadı!');
    
    // authModal dashboardArea içindeyse body'ye taşı (ana sayfada görünsün)
    if (modal.closest('#dashboardArea')) {
        document.body.appendChild(modal);
    }
    
    modal.classList.add('open');
    modal.style.display = 'flex';
    switchTab(type);
};

window.switchTab = function (tab) {
    var loginForm = document.getElementById('formLogin');
    var registerForm = document.getElementById('formRegister');
    var verifyForm = document.getElementById('formVerify');
    var tabs = document.querySelectorAll('.modal-tab');
    if (loginForm) loginForm.style.display = 'none';
    if (registerForm) registerForm.style.display = 'none';
    if (verifyForm) verifyForm.style.display = 'none';
    for (var i = 0; i < tabs.length; i++) tabs[i].classList.remove('active');
    if (tab === 'login') {
        if (loginForm) loginForm.style.display = 'block';
        if (tabs[0]) tabs[0].classList.add('active');
    } else if (tab === 'register') {
        if (registerForm) registerForm.style.display = 'block';
        if (tabs[1]) tabs[1].classList.add('active');
    } else if (tab === 'verify') {
        if (verifyForm) verifyForm.style.display = 'block';
        if (tabs[2]) tabs[2].classList.add('active');
    }
    var modal = document.getElementById('authModal');
if (modal) {
    if (modal.closest('#dashboardArea')) {
        document.body.appendChild(modal);
    }
    modal.classList.add('open');
    modal.style.display = 'flex';
}
};

