// PROFİL İŞLEMLERİ (Plan limitleri dahil)
// ============================================================
window.openProfileModal = function () {
    if (!window.currentUser) return showNotification('Önce giriş yapın!', 'error');
    var role = window.currentUser.get('role');
    var isAdmin = (role === 'admin');
    var isBeta = (role === 'beta');
    var isFounder = (role === 'founder');
    var isModerator = (role === 'moderator');
    var plan = window.currentUser.get('plan') || 'free';

    var leaveBtn = '';
    if (isAdmin) leaveBtn = '<button class="btn-danger btn-sm" onclick="window.leaveAdminRole()" style="margin-top:10px;">🚪 Admin\'den Ayrıl</button>';
    else if (isBeta) leaveBtn = '<button class="btn-danger btn-sm" onclick="window.leaveBetaRole()" style="margin-top:10px;">🚪 Beta\'dan Ayrıl</button>';

    var roleLabel = isFounder ? '👑 Kurucu' :
                    (isAdmin ? '⚙️ Admin' :
                    (isBeta ? '🔬 Beta' :
                    (isModerator ? '🎨 Moderatör / Tasarımcı' : '👤 Kullanıcı')));

    var planLabels = { free: '🆓 Ücretsiz', pro: '🌟 Pro', team: '👥 Takım' };
    var planLabel = planLabels[plan] || '🆓 Ücretsiz';

    var limits = typeof window.getPlanLimits === 'function' ? window.getPlanLimits(window.currentUser) : null;
    var limitHtml = '';
    if (limits && typeof getUsageData === 'function') {
        function limitRow(label, feature, period, unit) {
            var limit = limits[feature];
            var used = getUsageData(feature, period);
            var limitText = (limit === -1 || limit === Infinity) ? '♾️' : limit + (unit || '');
            var usedText = used + (unit || '');
            return '<div style="display:flex; justify-content:space-between; font-size:12px; padding:4px 0; border-bottom:1px dashed rgba(255,255,255,0.05);">' +
                '<span style="color:var(--text3);">' + label + '</span>' +
                '<span style="color:var(--accent); font-weight:600;">' + usedText + ' / ' + limitText + '</span>' +
                '</div>';
        }
        limitHtml =
            '<div style="background:linear-gradient(135deg, rgba(212,175,55,0.06), rgba(124,92,255,0.04)); border:1px solid rgba(212,175,55,0.25); border-radius:12px; padding:12px 14px; margin:12px 0;">' +
                '<div style="font-weight:700; color:var(--accent); font-size:13px; margin-bottom:8px;">📊 Plan Limitlerim (' + planLabel + ')</div>' +
                limitRow('✨ AETHRION Agents', 'vizyonAlPerDay', 'day', '/gün') +
                limitRow('🔊 Sesli Sohbet', 'voiceChatMinutesPerDay', 'day', ' dk/gün') +
                limitRow('📎 Dosya Analiz', 'fileAnalyzePerDay', 'day', '/gün') +
                limitRow('🎬 Video', 'videoCreatePerMonth', 'month', '/ay') +
                limitRow('🔑 A27 API', 'v27ApiKeys', 'lifetime', '') +
                limitRow('🧭 AETHRION Coach', 'kocPerWeek', 'week', '/hafta') +
                limitRow('⚡ Günlük Sorgu', 'dailyQueries', 'day', '/gün') +
                '<div style="display:flex; justify-content:space-between; font-size:12px; padding:4px 0;">' +
                    '<span style="color:var(--text3);">📋 Logs Erişim</span>' +
                    '<span style="color:' + (limits.logsAccess ? 'var(--accent2)' : 'var(--danger)') + '; font-weight:600;">' + (limits.logsAccess ? '✅ Var' : '❌ Yok') + '</span>' +
                '</div>' +
                (plan === 'free' ? '<div style="margin-top:10px; padding:8px; background:linear-gradient(135deg, rgba(212,175,55,0.1), rgba(232,197,85,0.06)); border-radius:8px; font-size:11.5px; color:#e8c555; text-align:center;">🚀 Daha fazlası için paketini yükselt!</div>' : '') +
            '</div>';
    }

    var profileContent = document.getElementById('profileContent');
    if (!profileContent) return;

    profileContent.innerHTML =
        '<p><strong>Ad:</strong> ' + window.escapeHtml(window.currentUser.get('name')) + '</p>' +
        '<p><strong>E-posta:</strong> ' + window.escapeHtml(window.currentUser.get('email')) + '</p>' +
        '<p><strong>Kurtarma Maili:</strong> ' + (window.currentUser.get('recovery_email') ? window.escapeHtml(window.currentUser.get('recovery_email')) : '<span style="color:var(--warning);">Belirlenmemiş</span>') + '</p>' +
        '<p><strong>Plan:</strong> ' + planLabel + '</p>' +
        '<p><strong>Rol:</strong> ' + roleLabel + '</p>' +
        '<p><strong>Puan:</strong> ' + (window.currentUser.get('points') || 0) + '</p>' +
        '<p><strong>Seviye:</strong> ' + (window.currentUser.get('level') || 'Çaylak') + '</p>' +
        '<p><strong>Davet Kodu:</strong> ' + window.escapeHtml(window.currentUser.get('referral_code') || 'Henüz oluşturulmamış') + '</p>' +
        '<p><strong>Üyelik:</strong> ' + new Date(window.currentUser.get('createdAt')).toLocaleDateString('tr-TR') + '</p>' +
        limitHtml +
        '<hr style="margin:16px 0;border-color:var(--border);">' +
        leaveBtn +
        '<button class="btn-danger btn-sm" onclick="window.deleteAccount()" style="margin-top:10px;">🗑️ Hesabımı Sil</button>';

    var pm = document.getElementById('profileModal');
    if (pm) {
        pm.classList.add('open');
        pm.style.display = 'flex';
    }
};

window.changePassword = async function () {
    if (!window.currentUser) return showNotification('Önce giriş yapın!', 'error');
    var newPass = prompt('Yeni şifrenizi girin (8+ karakter):');
    if (!newPass || newPass.length < 8) return showNotification('Şifre en az 8 karakter olmalı!', 'error');
    var confirmPass = prompt('Yeni şifreyi tekrar girin:');
    if (newPass !== confirmPass) return showNotification('Şifreler eşleşmiyor!', 'error');
    try {
        window.currentUser.set('password', newPass);
        await window.currentUser.save();
        showNotification('Şifre başarıyla değiştirildi!', 'success');
        if (typeof window.addLogSuccess === 'function') {
            window.addLogSuccess('Şifre değiştirildi');
        }
    } catch (e) {
        showNotification('Hata: ' + e.message, 'error');
        if (typeof window.addLogError === 'function') {
            window.addLogError('Şifre değiştirme hatası: ' + e.message);
        }
    }
};

window.deleteAccount = async function () {
    if (!window.currentUser) return showNotification('Önce giriş yapın!', 'error');
    var password = prompt('Hesabınızı silmek için şifrenizi girin (8+ karakter):');
    if (!password) return showNotification('İşlem iptal edildi.', 'warning');
    try {
        await Parse.User.logIn(window.currentUser.get('email'), password);
        if (!confirm('AETHRION hesabınızı kalıcı olarak silmek istediğinize emin misiniz? Bu işlem geri alınamaz!')) return;
        if (typeof window.addLogWarning === 'function') {
            window.addLogWarning('Hesap silme: ' + window.currentUser.get('email'));
        }
        await window.currentUser.destroy();
        await Parse.User.logOut();
        localStorage.removeItem('aethrion_user');
        window.currentUser = null;
        if (typeof currentUser !== 'undefined') currentUser = null;
        location.reload();
        showNotification('Hesabınız silindi.', 'success');
    } catch (e) {
        if (e.code === 101) {
            showNotification('Şifre yanlış! Lütfen tekrar deneyin.', 'error');
        } else {
            showNotification('Hata: ' + e.message, 'error');
            if (typeof window.addLogError === 'function') {
                window.addLogError('Hesap silme hatası: ' + e.message);
            }
        }
    }
};

