// ========== AI DURDURMA ========================================
// ================================================================
window.stopAIResponse = function (source) {
    window.currentAIRequestId = null;
    var stopBtnDashboard = document.getElementById('dashboardStopAIResponseBtn');
    if (stopBtnDashboard) stopBtnDashboard.style.display = 'none';
    var stopBtnFull = document.getElementById('fullAIStopBtn');
    if (stopBtnFull) stopBtnFull.style.display = 'none';

    var thinking = document.querySelector('.ai-thinking-indicator');
    if (thinking) thinking.remove();

    showNotification('⏹️ AI yanıtı durduruldu.', 'warning');
};

// ================================================================
// ========== AI MESAJ DÜZENLEME =================================
// ================================================================
window.editAIMessage = function (msgId, source) {
    window.stopAIResponse(source);

    var container = (source === 'full') ? document.getElementById('fullAIChat') : document.getElementById('dashboardAiMessages');
    if (!container) return;

    var userMessages = container.querySelectorAll('.ai-message.user, .ai-msg.user');
    if (userMessages.length === 0) {
        showNotification('Düzenlenecek mesaj bulunamadı!', 'warning');
        return;
    }
    var lastUserMsg = userMessages[userMessages.length - 1];
    var originalText = lastUserMsg.textContent.trim();
    var roleDiv = lastUserMsg.querySelector('.role');
    if (roleDiv) {
        originalText = originalText.replace(roleDiv.textContent, '').trim();
    }

    var botMessages = container.querySelectorAll('.ai-message.bot, .ai-msg.bot');
    if (botMessages.length > 0) {
        var lastBotMsg = botMessages[botMessages.length - 1];
        if (lastBotMsg.compareDocumentPosition(lastUserMsg) & Node.DOCUMENT_POSITION_PRECEDING) {
            lastBotMsg.remove();
        }
    }

    lastUserMsg.remove();

    var input = (source === 'full') ? document.getElementById('fullAIInput') : document.getElementById('dashboardAiInput');
    if (input) {
        input.value = originalText;
        input.focus();
    }

    showNotification('✏️ Mesaj düzenleme modunda — değiştirip tekrar gönderebilirsiniz.', 'success');
};

// ================================================================
// ========== DASHBOARD AI MESAJ GÖNDER =========================
// ================================================================
window.sendDashboardAI = async function () {
    try {
        var queryResult = await Parse.Cloud.run('useQuery', {});
        if (queryResult && queryResult.remaining !== undefined && queryResult.remaining <= 0) {
            showNotification('⚠️ Günlük sorgu hakkınız doldu!', 'error');
            return;
        }
    } catch (e) {
        if (e.message && e.message.includes('limit')) {
            showNotification('⚠️ ' + e.message, 'error');
            return;
        }
    }

    var inp = document.getElementById('dashboardAiInput');
    var msg = inp.value.trim();
    var dashboardFileInput = document.getElementById('dashboardFileInput');
    var attachedFile = dashboardFileInput && dashboardFileInput.files && dashboardFileInput.files[0] || null;
    if (!msg && !attachedFile) return;

    var thisRequestId = 'req_' + Date.now() + '_' + Math.random().toString(36).substring(2, 8);
    window.currentAIRequestId = thisRequestId;

    var container = document.getElementById('dashboardAiMessages');
    if (attachedFile) {
        var fileReqId = 'req_file_' + Date.now();
        window.currentAIRequestId = fileReqId;
        var userLine = (msg ? msg + '\n' : '') + '📎 ' + attachedFile.name;
        container.innerHTML += renderUserMessage(userLine);
        inp.value = '';
        var fileStop = document.getElementById('dashboardStopAIResponseBtn');
        if (fileStop) fileStop.style.display = 'inline-block';
        var thinking = document.createElement('div');
        thinking.className = 'ai-message bot ai-thinking-indicator';
        thinking.textContent = 'AETHRION AI dosyayı okuyor ve analiz ediyor…';
        container.appendChild(thinking);
        container.scrollTop = container.scrollHeight;
        try {
            var prepared = typeof window.aethrionPrepareFileForAI === 'function' ? await window.aethrionPrepareFileForAI(attachedFile) : null;
            if (!prepared) {
                var dataUrl = await new Promise(function(resolve,reject){var reader=new FileReader();reader.onload=function(){resolve(String(reader.result||''))};reader.onerror=function(){reject(new Error('Dosya okunamadı.'))};reader.readAsDataURL(attachedFile)});
                prepared = {fileBase64:dataUrl.split(',')[1],fileName:attachedFile.name,fileType:attachedFile.type||'application/octet-stream'};
            }
            var analysis = await Parse.Cloud.run('vizyonAlFileAnalyze', {fileBase64:prepared.fileBase64,fileName:prepared.fileName||attachedFile.name,fileType:prepared.fileType||attachedFile.type||'application/octet-stream',question:msg||'Bu dosyayı oku, özetle ve önemli noktalarını açıkla.'});
            if (window.currentAIRequestId !== fileReqId) return;
            if (thinking.parentNode) thinking.parentNode.removeChild(thinking);
            var fileAnswer = document.createElement('div');
            fileAnswer.className = 'ai-message bot';
            fileAnswer.textContent = analysis && analysis.success ? String(analysis.reply || 'Dosya analiz edildi ancak metin yanıtı dönmedi.') : String(analysis && analysis.error || 'Dosya analizi tamamlanamadı.');
            container.appendChild(fileAnswer);
            if (!analysis || analysis.success !== true) showNotification(fileAnswer.textContent, 'error');
            else if (typeof window.incrementUsage === 'function') window.incrementUsage('fileAnalyzePerDay','day',1);
        } catch (error) {
            if (thinking.parentNode) thinking.parentNode.removeChild(thinking);
            var fileError = document.createElement('div'); fileError.className='ai-message bot'; fileError.textContent='Dosya analizi başarısız: '+String(error&&error.message||error); container.appendChild(fileError);
            showNotification(fileError.textContent,'error');
        } finally {
            if (dashboardFileInput) dashboardFileInput.value = '';
            if (fileStop) fileStop.style.display = 'none';
            container.scrollTop = container.scrollHeight;
        }
        return;
    }

    container.innerHTML += renderUserMessage(msg);
    inp.value = '';
    container.scrollTop = container.scrollHeight;

    var stopBtn = document.getElementById('dashboardStopAIResponseBtn');
    if (stopBtn) stopBtn.style.display = 'inline-block';

    var thinkingId = 'thinking_' + thisRequestId;
    container.innerHTML += '<div class="ai-message bot ai-thinking-indicator" id="' + thinkingId + '"><span class="dot"></span><span class="dot"></span><span class="dot"></span> <span style="margin-left:6px;">AETHRION AI düşünüyor...</span></div>';
    container.scrollTop = container.scrollHeight;

    if (!currentConversationId) {
        var storedConvId = localStorage.getItem('aethrion_ai_conv_id');
        if (storedConvId) {
            currentConversationId = storedConvId;
        } else {
            try {
                var result = await Parse.Cloud.run('startConversation', {});
                if (result.success) {
                    currentConversationId = result.conversationId;
                    localStorage.setItem('aethrion_ai_conv_id', currentConversationId);
                }
            } catch (e) { console.log('Konuşma başlatılamadı:', e); }
        }
    }

    var response;
    if (msg.indexOf('dolar') !== -1 || msg.indexOf('haber') !== -1 || msg.indexOf('arama') !== -1) {
        response = await webSearch(msg);
    } else {
        response = await callAllAIModels(msg, currentConversationId);
    }

    if (window.currentAIRequestId !== thisRequestId) {
        var thinkingEl = document.getElementById(thinkingId);
        if (thinkingEl) thinkingEl.remove();
        return;
    }

    var thinkingEl2 = document.getElementById(thinkingId);
    if (thinkingEl2) thinkingEl2.remove();

    if (stopBtn) stopBtn.style.display = 'none';

    var cleaned = cleanClientResponse(response);
    var botMsgId = 'botmsg_' + thisRequestId;
    container.innerHTML += renderBotMessage(cleaned, botMsgId);
    container.scrollTop = container.scrollHeight;

    if (currentConversationId) {
        await saveAIMessageToConversation(currentConversationId, msg, response);
        if (typeof window.loadConversationHistory === 'function') {
            try { window.loadConversationHistory(); } catch (e) {}
        }
    }

    if (typeof window.addLogInfo === 'function') {
        window.addLogInfo('AI sorgu tamamlandı', { length: msg.length });
    }
};

// ================================================================
// ========== AI MESAJ METNİNİ KOPYALA ===========================
// ================================================================
window.copyAIMessageText = function (msgId) {
    var el = document.getElementById(msgId);
    if (!el) return;
    var clone = el.cloneNode(true);
    var actions = clone.querySelector('.ai-msg-actions-container');
    if (actions) actions.remove();
    var roleEl = clone.querySelector('.role');
    if (roleEl) roleEl.remove();
    var text = clone.textContent.trim();
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(function () {
            showNotification('📋 Cevap kopyalandı!', 'success');
        }).catch(function () {
            fallbackCopyText(text);
        });
    } else {
        fallbackCopyText(text);
    }
};

function fallbackCopyText(text) {
    var textarea = document.createElement('textarea');
    textarea.value = text;
    textarea.style.position = 'fixed';
    textarea.style.opacity = '0';
    textarea.style.left = '-9999px';
    document.body.appendChild(textarea);
    textarea.select();
    try {
        document.execCommand('copy');
        showNotification('📋 Cevap kopyalandı!', 'success');
    } catch (e) {
        showNotification('Kopyalanamadı', 'error');
    }
    document.body.removeChild(textarea);
}

