// ================================================================
// ========== AETHRION AGENTS PANEL TEMEL =======================
// ================================================================
window.vizyonAlMode = 'normal';
window.vizyonAlOpened = false;
window.vizyonAlScreenSharing = false;
window.vizyonAlScreenStream = null;
window.vizyonAlResponsibilityAccepted = false;
window.vizyonAlLastRequestId = null;

window.openVizyonAlPanel = function () {
    var panel = document.getElementById('vizyonAlPanel');
    var trigger = document.getElementById('vizyonAlTrigger');
    var backdrop = document.getElementById('vizyonAlBackdrop');
    if (!panel) {
        console.warn('vizyonAlPanel bulunamadı!');
        return;
    }

    if (window.currentUser && typeof window.checkFeatureLimit === 'function') {
        var limitCheck = window.checkFeatureLimit('vizyonAlPerDay', 'day');
        if (!limitCheck.allowed) {
            if (typeof window.showLimitModal === 'function') {
                window.showLimitModal('vizyonAlPerDay', limitCheck);
            }
            return;
        }
    }

    if (panel.parentElement && panel.parentElement.id === 'mainSite') document.body.appendChild(panel);
    if (trigger && trigger.parentElement && trigger.parentElement.id === 'mainSite') document.body.appendChild(trigger);
    if (backdrop && backdrop.parentElement && backdrop.parentElement.id === 'mainSite') document.body.appendChild(backdrop);

    panel.classList.add('open');
    if (trigger) trigger.classList.add('active');
    if (backdrop) backdrop.classList.remove('open');
    document.body.classList.add('vizyon-al-open');
    window.vizyonAlOpened = true;

    var accepted = false;
    try {
        accepted = localStorage.getItem('aethrion_agents_responsibility_v1') === '1';
    } catch (e) { accepted = false; }

    if (accepted) {
        window.vizyonAlResponsibilityAccepted = true;
        window.showVizyonAlMainArea();
    } else {
        window.showVizyonAlResponsibilityArea();
    }

    if (typeof window.addLogInfo === 'function') {
        window.addLogInfo('AETHRION Agents paneli açıldı (28 model)', { mode: window.vizyonAlMode });
    }

    setTimeout(function () {
        if (typeof window.ensureScreenReadButton === 'function') {
            window.ensureScreenReadButton();
        }
    }, 500);
};

window.closeVizyonAlPanel = function () {
    var panel = document.getElementById('vizyonAlPanel');
    var trigger = document.getElementById('vizyonAlTrigger');
    var backdrop = document.getElementById('vizyonAlBackdrop');

    if (panel) panel.classList.remove('open');
    if (trigger) trigger.classList.remove('active');
    if (backdrop) backdrop.classList.remove('open');
    document.body.classList.remove('vizyon-al-open');
    window.vizyonAlOpened = false;

    if (typeof window.stopVizyonAlLiveScreen === 'function') {
        window.stopVizyonAlLiveScreen();
    }

    if (window.vizyonAlScreenStream) {
        try {
            window.vizyonAlScreenStream.getTracks().forEach(function (t) { t.stop(); });
        } catch (e) {}
        window.vizyonAlScreenStream = null;
        window.vizyonAlScreenSharing = false;
    }

    if (typeof window.addLogInfo === 'function') {
        window.addLogInfo('AETHRION Agents paneli kapatıldı');
    }
};

window.showVizyonAlResponsibilityArea = function () {
    var respArea = document.getElementById('vzResponsibilityArea');
    var mainArea = document.getElementById('vzMainArea');
    if (respArea) respArea.style.display = 'flex';
    if (mainArea) mainArea.style.display = 'none';
};

