// ================================================================
window.kocConversationId = null;
window.kocCurrentRequestId = null;
window.kocHistoryCache = [];
window.kocLastSharedLink = '';
window.kocLastSharedPassword = '';

window.renderKocMessage = function (text) {
    if (!text) return '';
    var safe = window.escapeHtml(text);
    safe = safe.replace(/```([a-zA-Z0-9+#]*)\n?([\s\S]*?)```/g, function (match, lang, code) {
        return '<pre style="background:rgba(0,0,0,0.4);padding:8px 12px;border-radius:8px;overflow-x:auto;margin:6px 0;border:1px solid rgba(212,175,55,0.15);"><code style="font-family:var(--font-code);color:#b8c0d0;font-size:12px;">' + code + '</code></pre>';
    });
    safe = safe.replace(/`([^`\n]+)`/g, '<code>$1</code>');
    safe = safe.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
    safe = safe.replace(/\*(.*?)\*/g, '<em>$1</em>');
    safe = safe.replace(/\n/g, '<br>');
    return safe;
};

window.getKocLimitClient = function (user) {
    if (!user) return 0;
    var role = user.get('role');
    var plan = user.get('plan');
    if (role === 'founder' || role === 'admin' || role === 'beta' || role === 'moderator') return -1;
    if (plan === 'team') return 1000;
    if (plan === 'pro') return 50;
    return 10;
};

window.openKocPanel = async function () {
    if (!window.currentUser) {
        showNotification('Bu özelliği kullanmak için önce giriş yapın!', 'error');
        return;
    }

    var panel = document.getElementById('kocPanelOverlay');
    if (!panel) {
        console.warn('kocPanelOverlay bulunamadı!');
        showNotification('Coach paneli yüklenemedi!', 'error');
        return;
    }

    panel.classList.add('open');
    panel.style.display = 'flex';

    window.updateKocLimitBadge();
    await window.loadKocHistory();

    var storedConvId = localStorage.getItem('aethrion_koc_conv_id');
    if (storedConvId && window.kocHistoryCache.some(function (c) { return c.id === storedConvId; })) {
        await window.loadKocConversationById(storedConvId);
    } else if (window.kocHistoryCache.length > 0) {
        await window.loadKocConversationById(window.kocHistoryCache[0].id);
    } else {
        window.kocConversationId = null;
        var topicEl = document.getElementById('kocCurrentTopic');
        if (topicEl) topicEl.textContent = 'Yeni Sohbet';
        var chatEl = document.getElementById('kocChatMessages');
        if (chatEl) {
            chatEl.innerHTML = '<div class="koc-msg coach">' +
                '<div class="koc-msg-role">🧭 AETHRION COACH</div>' +
                'Merhaba kardeşim! Ben senin AETHRION Coach\'unum. Sana yol göstermek, destek olmak, moral vermek için buradayım. Sorunu yaz, birlikte çözelim. 🤝<br><br>' +
                '🟢 <strong style="color:var(--nvidia);">28 model</strong> birleşik gücüyle çalışıyorum.' +
                '</div>';
        }
    }

    setTimeout(function () {
        var input = document.getElementById('kocInput');
        if (input) input.focus();
    }, 300);

    if (typeof window.addLogInfo === 'function') {
        window.addLogInfo('AETHRION Coach paneli açıldı');
    }
};

window.closeKocPanel = function () {
    var panel = document.getElementById('kocPanelOverlay');
    if (panel) {
        panel.classList.remove('open');
        panel.style.display = 'none';
    }
    window.stopKocResponse();
};

window.sendKocMessage = async function () {
    if (!window.currentUser) return showNotification('Önce giriş yapın!', 'error');

    var input = document.getElementById('kocInput');
    var sendBtn = document.getElementById('kocSendBtn');
    var stopBtn = document.getElementById('kocStopBtn');
    var chatEl = document.getElementById('kocChatMessages');
    if (!input || !chatEl) return;

    var msg = input.value.trim();
    if (!msg) {
        showNotification('Lütfen bir mesaj yazın!', 'warning');
        return;
    }

    var limit = window.getKocLimitClient(window.currentUser);
    var usage = await getKocUsageClient();
    if (limit !== -1 && usage.used >= limit) {
        showNotification('⚠️ Haftalık Coach işlem limitiniz doldu! (' + usage.used + '/' + limit + ')', 'error');
        if (typeof window.showLimitModal === 'function') {
            window.showLimitModal('kocPerWeek', {
                allowed: false,
                limit: limit,
                used: usage.used,
                remaining: 0,
                reason: 'Haftalık Coach limitiniz doldu'
            });
        }
        return;
    }

    var userName = window.currentUser.get('name') || 'Sen';
    var userMsgHtml = '<div class="koc-msg user">' +
        '<div class="koc-msg-role">👤 ' + window.escapeHtml(userName) + '</div>' +
        window.escapeHtml(msg).replace(/\n/g, '<br>') +
        '</div>';
    chatEl.innerHTML += userMsgHtml;
    input.value = '';
    chatEl.scrollTop = chatEl.scrollHeight;

    if (sendBtn) sendBtn.style.display = 'none';
    if (stopBtn) stopBtn.style.display = 'inline-block';

    var thisReqId = 'koc_req_' + Date.now() + '_' + Math.random().toString(36).substring(2, 8);
    window.kocCurrentRequestId = thisReqId;
    var thinkingId = 'koc_thinking_' + thisReqId;
    chatEl.innerHTML += '<div class="koc-thinking" id="' + thinkingId + '">' +
        '<span class="koc-dot"></span><span class="koc-dot"></span><span class="koc-dot"></span>' +
        '<span style="margin-left:6px;">AETHRION Coach düşünüyor...</span>' +
        '</div>';
    chatEl.scrollTop = chatEl.scrollHeight;

    try {
        var result = await Parse.Cloud.run('kocChat', {
            message: msg,
            conversationId: window.kocConversationId || null
        });

        if (window.kocCurrentRequestId !== thisReqId) {
            var th = document.getElementById(thinkingId);
            if (th) th.remove();
            return;
        }

        var th2 = document.getElementById(thinkingId);
        if (th2) th2.remove();

        if (sendBtn) sendBtn.style.display = 'inline-block';
        if (stopBtn) stopBtn.style.display = 'none';

        if (result && result.success && result.reply) {
            var cleaned = window.renderKocMessage(result.reply);
            chatEl.innerHTML += '<div class="koc-msg coach">' +
                '<div class="koc-msg-role">🧭 AETHRION COACH</div>' +
                cleaned +
                '<div class="koc-msg-time">' + new Date().toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' }) + '</div>' +
                '</div>';
            chatEl.scrollTop = chatEl.scrollHeight;

            if (result.conversationId) {
                window.kocConversationId = result.conversationId;
                localStorage.setItem('aethrion_koc_conv_id', result.conversationId);
            }

            await window.loadKocHistory();
            window.updateKocLimitBadge();
            if (typeof window.addLogInfo === 'function') {
                window.addLogInfo('AETHRION Coach mesajı gönderildi');
            }
        } else {
            var errMsg = (result && result.error) ? result.error : 'Coach şu an cevap veremiyor.';
            chatEl.innerHTML += '<div class="koc-msg coach" style="border-left-color:var(--danger);">' +
                '<div class="koc-msg-role" style="color:var(--danger);">⚠️ HATA</div>' +
                window.escapeHtml(errMsg) +
                '</div>';
            chatEl.scrollTop = chatEl.scrollHeight;
        }
    } catch (e) {
        console.error('Coach hatası:', e);
        var th3 = document.getElementById(thinkingId);
        if (th3) th3.remove();
        if (sendBtn) sendBtn.style.display = 'inline-block';
        if (stopBtn) stopBtn.style.display = 'none';

        chatEl.innerHTML += '<div class="koc-msg coach" style="border-left-color:var(--danger);">' +
            '<div class="koc-msg-role" style="color:var(--danger);">⚠️ BAĞLANTI HATASI</div>' +
            window.escapeHtml(e.message || 'Bilinmeyen hata') +
            '</div>';
        chatEl.scrollTop = chatEl.scrollHeight;
        if (typeof window.addLogError === 'function') {
            window.addLogError('Coach hatası: ' + e.message);
        }
    }
};

window.stopKocResponse = function () {
    window.kocCurrentRequestId = null;
    var sendBtn = document.getElementById('kocSendBtn');
    var stopBtn = document.getElementById('kocStopBtn');
    if (sendBtn) sendBtn.style.display = 'inline-block';
    if (stopBtn) stopBtn.style.display = 'none';

    var thinking = document.querySelector('.koc-thinking');
    if (thinking) thinking.remove();

    showNotification('⏹️ Coach yanıtı durduruldu.', 'warning');
};

async function getKocUsageClient() {
    try {
        var result = await Parse.Cloud.run('getKocUsage', {});
        return result || { used: 0, limit: 0 };
    } catch (e) {
        console.warn('KocUsage alınamadı:', e);
        return { used: 0, limit: 0 };
    }
}

window.updateKocLimitBadge = async function () {
    if (!window.currentUser) return;

    var limit = window.getKocLimitClient(window.currentUser);
    var badge = document.getElementById('kocPanelLimitBadge');
    var navbarMini = document.getElementById('kocNavbarLimitMini');
    var dashMini = document.getElementById('kocDashboardLimitMini');
    var dashBadge = document.getElementById('kocDashboardLimitBadge');

    if (limit === -1) {
        if (badge) {
            badge.textContent = '♾️ Sınırsız';
            badge.className = 'koc-limit-badge unlimited';
        }
        if (navbarMini) {
            navbarMini.textContent = '♾️';
            navbarMini.style.display = 'inline-flex';
        }
        if (dashMini) dashMini.textContent = '♾️';
        if (dashBadge) {
            dashBadge.textContent = '♾️ Sınırsız';
            dashBadge.className = 'koc-limit-badge unlimited';
        }
        return;
    }

    try {
        var usage = await getKocUsageClient();
        var used = usage.used || 0;
        var remaining = Math.max(0, limit - used);

        var text = '📅 ' + used + ' / ' + limit + ' (haftalık)';
        var miniText = used + '/' + limit;

        var cls = 'koc-limit-badge';
        if (remaining === 0) cls += ' danger';
        else if (remaining <= limit * 0.2) cls += ' low';

        if (badge) {
            badge.textContent = text;
            badge.className = cls;
        }
        if (navbarMini) {
            navbarMini.textContent = miniText;
            navbarMini.style.display = 'inline-flex';
        }
        if (dashMini) dashMini.textContent = miniText;
        if (dashBadge) {
            dashBadge.textContent = text;
            dashBadge.className = cls;
        }
    } catch (e) {
        console.warn('Limit rozeti güncellenemedi:', e);
    }
};

window.loadKocHistory = async function () {
    if (!window.currentUser) return;

    var listEl = document.getElementById('kocHistoryList');
    var dashListEl = document.getElementById('kocDashboardHistoryList');
    if (!listEl && !dashListEl) return;

    try {
        var result = await Parse.Cloud.run('getKocHistory', {});
        var conversations = (result && result.conversations) ? result.conversations : [];
        window.kocHistoryCache = conversations;

        if (conversations.length === 0) {
            var emptyHtml = '<div class="koc-history-empty">📭 Henüz sohbet yok. İlk mesajını yazarak başla!</div>';
            if (listEl) listEl.innerHTML = emptyHtml;
            if (dashListEl) dashListEl.innerHTML = '<div class="koc-history-empty">📭 Henüz AETHRION Coach sohbeti yok.</div>';
            return;
        }

        var html = '';
        conversations.forEach(function (c) {
            var isActive = (c.id === window.kocConversationId) ? ' active' : '';
            var titleSafe = window.escapeHtml(c.title || c.topic || 'Sohbet');
            var dateStr = '';
            try {
                var d = new Date(c.createdAt || c.updatedAt);
                dateStr = d.toLocaleString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
            } catch (e) { dateStr = ''; }

            html += '<div class="koc-history-item' + isActive + '" onclick="window.loadKocConversationById(\'' + c.id + '\')" style="cursor:pointer;">';
            html += '<div style="font-weight:600;">' + titleSafe + '</div>';
            html += '<div class="koc-h-meta">';
            html += '<span>🕒 ' + dateStr + '</span>';
            if (c.messageCount) html += '<span>💬 ' + c.messageCount + ' mesaj</span>';
            html += '</div>';
            html += '</div>';
        });

        if (listEl) listEl.innerHTML = html;
        if (dashListEl) dashListEl.innerHTML = html;
    } catch (e) {
        console.warn('Coach geçmişi yüklenemedi:', e);
        var errHtml = '<div class="koc-history-empty">⚠️ Geçmiş yüklenemedi.</div>';
        if (listEl) listEl.innerHTML = errHtml;
        if (dashListEl) dashListEl.innerHTML = errHtml;
    }
};

window.loadKocConversationById = async function (convId) {
    if (!window.currentUser || !convId) return;

    var chatEl = document.getElementById('kocChatMessages');
    var topicEl = document.getElementById('kocCurrentTopic');
    if (!chatEl) return;

    chatEl.innerHTML = '<div class="koc-thinking"><span class="koc-dot"></span><span class="koc-dot"></span><span class="koc-dot"></span><span style="margin-left:6px;">Yükleniyor...</span></div>';

    try {
        var result = await Parse.Cloud.run('getKocConversationMessages', { conversationId: convId });
        if (!result || !result.success || !result.messages) {
            chatEl.innerHTML = '<div class="koc-msg coach" style="border-left-color:var(--danger);">⚠️ Sohbet yüklenemedi.</div>';
            return;
        }

        window.kocConversationId = convId;
        localStorage.setItem('aethrion_koc_conv_id', convId);

        var conv = window.kocHistoryCache.find(function (c) { return c.id === convId; });
        if (topicEl) {
            topicEl.textContent = (conv && (conv.title || conv.topic)) ? (conv.title || conv.topic) : 'Sohbet';
        }

        var html = '';
        var userName = window.currentUser.get('name') || 'Sen';

        result.messages.forEach(function (m) {
            var isUser = (m.sender === 'user');
            var content = m.text || '';
            var safeContent = window.renderKocMessage(content);
            if (isUser) {
                html += '<div class="koc-msg user">';
                html += '<div class="koc-msg-role">👤 ' + window.escapeHtml(userName) + '</div>';
                html += safeContent;
                html += '</div>';
            } else {
                html += '<div class="koc-msg coach">';
                html += '<div class="koc-msg-role">🧭 AETHRION COACH</div>';
                html += safeContent;
                html += '</div>';
            }
        });

        chatEl.innerHTML = html;
        chatEl.scrollTop = chatEl.scrollHeight;

        var items = document.querySelectorAll('.koc-history-item');
        items.forEach(function (item) { item.classList.remove('active'); });
    } catch (e) {
        console.error('Coach konuşma yüklenemedi:', e);
        chatEl.innerHTML = '<div class="koc-msg coach" style="border-left-color:var(--danger);">⚠️ ' + window.escapeHtml(e.message || 'Yüklenemedi.') + '</div>';
    }
};

