window.openKocShareModal = function () {
    if (!window.currentUser) return showNotification('Önce giriş yapın!', 'error');
    if (!window.kocConversationId) {
        return showNotification('⚠️ Önce bir coach sohbeti başlatın!', 'warning');
    }

    var modal = document.getElementById('kocShareModalOverlay');
    if (!modal) return showNotification('Paylaşım modalı bulunamadı!', 'error');

    var cb = document.getElementById('kocResponsibilityCheckbox');
    if (cb) cb.checked = false;
    var pwInput = document.getElementById('kocSharePasswordInput');
    if (pwInput) { pwInput.value = ''; pwInput.type = 'text'; }
    var createBtn = document.getElementById('kocShareCreateBtn');
    if (createBtn) createBtn.disabled = true;
    var resultDiv = document.getElementById('kocShareResult');
    if (resultDiv) resultDiv.classList.remove('show');
    var linkEl = document.getElementById('kocShareResultLink');
    if (linkEl) linkEl.textContent = '–';
    var pwEl = document.getElementById('kocShareResultPassword');
    if (pwEl) pwEl.textContent = '–';

    window.kocLastSharedLink = '';
    window.kocLastSharedPassword = '';

    modal.classList.add('open');
    modal.style.display = 'flex';
};

window.closeKocShareModal = function () {
    var modal = document.getElementById('kocShareModalOverlay');
    if (modal) {
        modal.classList.remove('open');
        modal.style.display = 'none';
    }
};

window.onKocShareCheckboxChange = function () {
    var cb = document.getElementById('kocResponsibilityCheckbox');
    var pwInput = document.getElementById('kocSharePasswordInput');
    var createBtn = document.getElementById('kocShareCreateBtn');
    var isChecked = cb && cb.checked;
    var hasPw = pwInput && pwInput.value.trim().length >= 4;

    if (createBtn) createBtn.disabled = !(isChecked && hasPw);
};

window.toggleKocSharePasswordVisibility = function () {
    var pwInput = document.getElementById('kocSharePasswordInput');
    if (!pwInput) return;
    pwInput.type = pwInput.type === 'password' ? 'text' : 'password';
};

window.generateRandomKocSharePassword = function () {
    var chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789';
    var pw = '';
    for (var i = 0; i < 8; i++) {
        pw += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    var pwInput = document.getElementById('kocSharePasswordInput');
    if (pwInput) {
        pwInput.value = pw;
        pwInput.type = 'text';
    }
    window.onKocShareCheckboxChange();
};

window.createKocShareLink = async function () {
    if (!window.currentUser) return showNotification('Önce giriş yapın!', 'error');
    if (!window.kocConversationId) return showNotification('Sohbet seçili değil!', 'error');

    var cb = document.getElementById('kocResponsibilityCheckbox');
    var pwInput = document.getElementById('kocSharePasswordInput');
    var createBtn = document.getElementById('kocShareCreateBtn');

    if (!cb || !cb.checked) {
        return showNotification('⚠️ Lütfen sorumluluk onayını işaretleyin!', 'warning');
    }
    var password = pwInput ? pwInput.value.trim() : '';
    if (password.length < 4) {
        return showNotification('⚠️ Şifre en az 4 karakter olmalı!', 'warning');
    }

    if (createBtn) {
        createBtn.disabled = true;
        createBtn.textContent = '⏳ Oluşturuluyor...';
    }

    try {
        var result = await Parse.Cloud.run('shareKocConversation', {
            conversationId: window.kocConversationId,
            password: password
        });

        if (createBtn) {
            createBtn.disabled = false;
            createBtn.textContent = '🔗 Link + Şifre Oluştur';
        }

        if (result && result.success && result.shareUrl) {
            window.kocLastSharedLink = result.shareUrl;
            window.kocLastSharedPassword = password;

            var resultDiv = document.getElementById('kocShareResult');
            var linkEl = document.getElementById('kocShareResultLink');
            var pwEl = document.getElementById('kocShareResultPassword');
            if (linkEl) linkEl.textContent = result.shareUrl;
            if (pwEl) pwEl.textContent = password;
            if (resultDiv) resultDiv.classList.add('show');

            showNotification('✅ Paylaşım linki ve şifre oluşturuldu!', 'success');
            if (typeof window.addLogSuccess === 'function') {
                window.addLogSuccess('AETHRION Coach sohbeti paylaşıldı');
            }
        } else {
            var errMsg = (result && result.error) ? result.error : 'Paylaşım oluşturulamadı.';
            showNotification('❌ ' + errMsg, 'error');
        }
    } catch (e) {
        console.error('Paylaşım hatası:', e);
        if (createBtn) {
            createBtn.disabled = false;
            createBtn.textContent = '🔗 Link + Şifre Oluştur';
        }
        showNotification('❌ Hata: ' + e.message, 'error');
        if (typeof window.addLogError === 'function') {
            window.addLogError('Coach paylaşım hatası: ' + e.message);
        }
    }
};

window.copyKocShareLink = function () {
    if (!window.kocLastSharedLink) return showNotification('Link yok!', 'warning');
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(window.kocLastSharedLink).then(function () {
            showNotification('📋 Link kopyalandı!', 'success');
        }).catch(function () {
            fallbackCopyText(window.kocLastSharedLink);
        });
    } else {
        fallbackCopyText(window.kocLastSharedLink);
    }
};

