// ================================================================
// ========== SESLİ SOHBET TAM EKRAN — AÇ / KAPAT / MUTE =========
// ================================================================
window.voiceChatActive = false;
window.voiceChatStartTime = null;
window.voiceChatTimer = null;
window.voiceChatCountedMinutes = 0;
window.voiceChatLastTick = null;

window.openVoiceChatFullscreen = async function () {
    if (!window.currentUser) {
        showNotification('Sesli sohbet için önce giriş yapın!', 'error');
        return;
    }

    if (typeof window.checkFeatureLimit === 'function') {
        var limitCheck = window.checkFeatureLimit('voiceChatMinutesPerDay', 'day');
        if (!limitCheck.allowed) {
            if (typeof window.showLimitModal === 'function') {
                window.showLimitModal('voiceChatMinutesPerDay', limitCheck);
            }
            return;
        }
    }

    var modal = document.getElementById('voiceChatFullscreen') || document.getElementById('vzVoiceFullscreen');
    if (!modal) {
        console.warn('Sesli sohbet modali bulunamadı');
        return;
    }

    modal.classList.add('open');
    modal.style.display = 'flex';
    window.voiceChatActive = true;
    window.voiceChatStartTime = Date.now();
    window.voiceChatCountedMinutes = 0;
    window.voiceChatLastTick = Date.now();

    // Süre sayacı — her 30 saniyede kontrol et, dakika ekle
    if (window.voiceChatTimer) clearInterval(window.voiceChatTimer);
    window.voiceChatTimer = setInterval(function () {
        if (!window.voiceChatActive) return;
        var now = Date.now();
        var elapsed = Math.floor((now - window.voiceChatStartTime) / 60000);
        var newMinutes = elapsed - window.voiceChatCountedMinutes;
        if (newMinutes > 0) {
            window.voiceChatCountedMinutes += newMinutes;
            if (typeof window.incrementUsage === 'function') {
                window.incrementUsage('voiceChatMinutesPerDay', 'day', newMinutes);
            }
            // Limit kontrolü
            if (typeof window.checkFeatureLimit === 'function') {
                var check = window.checkFeatureLimit('voiceChatMinutesPerDay', 'day');
                if (!check.allowed) {
                    window.closeVoiceChatFullscreen();
                    showNotification('⚠️ Günlük sesli sohbet süreniz doldu!', 'warning');
                    return;
                }
            }
        }
        var badge = document.getElementById('voiceChatLimitBadge');
        if (badge && typeof window.getLimitText === 'function') {
            badge.textContent = '📅 ' + window.getLimitText('voiceChatMinutesPerDay', 'day') + ' (günlük)';
        }
    }, 10000);

    // Ses tanımayı başlat
    if (typeof window.startVoiceChatRecognition === 'function') {
        window.startVoiceChatRecognition();
    }
};

window.closeVoiceChatFullscreen = function () {
    var modal = document.getElementById('voiceChatFullscreen') || document.getElementById('vzVoiceFullscreen');
    if (modal) {
        modal.classList.remove('open');
        modal.style.display = 'none';
    }

    window.voiceChatActive = false;
    if (window.voiceChatTimer) {
        clearInterval(window.voiceChatTimer);
        window.voiceChatTimer = null;
    }

    if (window.voiceChatRecognition) {
        try { window.voiceChatRecognition.stop(); } catch (e) {}
        window.voiceChatRecognition = null;
    }

    if (window.speechSynthesis && window.speechSynthesis.speaking) {
        window.speechSynthesis.cancel();
    }

    showNotification('🔊 Sesli sohbet kapatıldı', 'success');
};

window.toggleVoiceChatMute = function () {
    if (window.speechSynthesis && window.speechSynthesis.speaking) {
        window.speechSynthesis.cancel();
        showNotification('🔇 Ses kapatıldı', 'warning');
    } else {
        showNotification('🔊 Ses açık', 'success');
    }
};

// ================================================================
// ========== [AETHRION] AGENTS İLE A27 API KEY ==================
// ================================================================
window.openV27QuickCreate = function () {
    if (!window.currentUser) return showNotification('Önce giriş yapın!', 'error');
    var modal = document.getElementById('v27QuickCreateOverlay');
    if (modal) {
        modal.classList.add('open');
        modal.style.display = 'flex';
        var nameInput = document.getElementById('v27QuickKeyName');
        if (nameInput) nameInput.value = '';
        var descInput = document.getElementById('v27QuickKeyDesc');
        if (descInput) descInput.value = '';
        var errEl = document.getElementById('v27QuickCreateError');
        if (errEl) { errEl.style.display = 'none'; errEl.textContent = ''; }
        window._v27QuickSelectedDuration = 'unlimited';
        document.querySelectorAll('#v27QuickDurationRow .A27-duration-btn').forEach(function (btn) {
            btn.classList.remove('active');
            if (btn.getAttribute('data-val') === 'unlimited') btn.classList.add('active');
            btn.onclick = function () {
                document.querySelectorAll('#v27QuickDurationRow .A27-duration-btn').forEach(function (b) { b.classList.remove('active'); });
                btn.classList.add('active');
                window._v27QuickSelectedDuration = btn.getAttribute('data-val');
            };
        });
    }
};

window.closeV27QuickCreate = function () {
    var modal = document.getElementById('v27QuickCreateOverlay');
    if (modal) {
        modal.classList.remove('open');
        modal.style.display = 'none';
    }
};

window.submitQuickV27Key = async function () {
    if (!window.currentUser) return showNotification('Önce giriş yapın!', 'error');
    var nameEl = document.getElementById('v27QuickKeyName');
    var descEl = document.getElementById('v27QuickKeyDesc');
    var errEl = document.getElementById('v27QuickCreateError');
    var keyName = nameEl ? nameEl.value.trim() : '';
    var keyDesc = descEl ? descEl.value.trim() : '';

    function showErr(msg) {
        if (errEl) { errEl.textContent = '❌ ' + msg; errEl.style.display = 'block'; }
        showNotification('❌ ' + msg, 'error');
    }
    if (errEl) errEl.style.display = 'none';

    if (!keyName) return showErr('Anahtar adı gerekli!');
    if (keyName.length < 2) return showErr('Anahtar adı en az 2 karakter olmalı!');

    try {
        var result = await Parse.Cloud.run('createV27ApiKey', {
            keyName: keyName,
            keyDescription: keyDesc,
            duration: window._v27QuickSelectedDuration || 'unlimited',
            viaVizyonAl: true
        });

        if (!result.success) return showErr(result.error || 'Anahtar oluşturulamadı.');

        // Değeri ayrı ekranda göster
        closeModal('v27QuickCreateOverlay');
        window.showV27KeyReveal(result.plainKey, result.durationLabel);

        showNotification('✅ A27 API anahtarı oluşturuldu!', 'success');
        if (typeof window.addLogSuccess === 'function') {
            window.addLogSuccess('AETHRION Agents üzerinden A27 API anahtarı oluşturuldu');
        }
    } catch (e) {
        console.error('A27 key oluşturma hatası:', e);
        showErr(e.message || 'Bilinmeyen hata');
    }
};

window.showV27KeyReveal = function (plainKey, durationLabel) {
    var overlay = document.getElementById('v27KeyRevealOverlay');
    if (!overlay) {
        // Fallback: modal olarak göster
        alert('🔑 A27 API Anahtarınız (BİR DAHA GÖSTERİLMEYECEK!):\n\n' + plainKey + '\n\n⏱️ Süre: ' + (durationLabel || 'Süresiz') + '\n\nLütfen güvenli bir yere kaydedin!\n\nAETHRION — Intelligence Without Limits.');
        return;
    }
    var keyEl = document.getElementById('v27RevealKeyValue');
    if (keyEl) keyEl.textContent = plainKey;
    window._v27RevealKey = plainKey;
    overlay.classList.add('open');
    overlay.style.display = 'flex';
};

window.closeV27KeyReveal = function () {
    var overlay = document.getElementById('v27KeyRevealOverlay');
    if (overlay) {
        overlay.classList.remove('open');
        overlay.style.display = 'none';
    }
    window._v27RevealKey = null;
    // MyVizyonApiKeys listesini yenile
    if (typeof window.loadMyVizyonApiKeys === 'function') {
        window.loadMyVizyonApiKeys();
    }
};

window.copyV27RevealKey = function () {
    var key = window._v27RevealKey;
    if (!key) return showNotification('Kopyalanacak anahtar yok!', 'error');
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(key).then(function () {
            showNotification('📋 Anahtar kopyalandı!', 'success');
        }).catch(function () {
            fallbackCopyText(key);
        });
    } else {
        fallbackCopyText(key);
    }
};

