// ============================================================
window.closeModal = function (id) {
    var modal = document.getElementById(id);
    if (modal) {
        modal.classList.remove('open');
        modal.style.display = '';
        modal.style.visibility = '';
        modal.style.opacity = '';
        var inputs = modal.querySelectorAll('input, textarea');
        inputs.forEach(function (inp) {
            if (inp.type !== 'submit' && inp.type !== 'button') inp.value = '';
        });
    }
};

document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') {
        if (window.aethrionFeaturesPanelOpen) {
            window.closeAethrionFeaturesPanel();
            return;
        }
        var openModals = document.querySelectorAll('.modal-overlay.open');
        openModals.forEach(function (modal) {
            if (modal.id === 'profileCompletionModal') return;
            if (modal.id === 'v27ApiKeyCreatedModal' || modal.id === 'a27ApiKeyCreatedModal') return;
            if (modal.id === 'v27KeyRevealOverlay' || modal.id === 'a27KeyRevealOverlay') return;
            if (modal.id === 'vizyonAlScreenPermissionModal' || modal.id === 'aethrionAlScreenPermissionModal') return;
            if (modal.id === 'moderatorAssignModal') return;
            if (modal.id === 'jobCreateOverlay') return;
            window.closeModal(modal.id);
        });
        if (window.vizyonAlOpened || window.aethrionAlOpened) {
            if (typeof window.closeAethrionAlPanel === 'function') window.closeAethrionAlPanel();
            else if (typeof window.closeVizyonAlPanel === 'function') window.closeVizyonAlPanel();
        }
        if (window.voiceChatActive) window.closeVoiceChatFullscreen();
        if (window.videoStudioActive) window.closeVideoStudio();
        if (window.videoEditorActive && window.closeVideoEditor) window.closeVideoEditor();
        if (window.jobMarketActive && window.closeJobMarket) window.closeJobMarket();
    }
});

document.addEventListener('click', function (e) {
    if (e.target.classList.contains('modal-overlay')) {
        if (e.target.id === 'profileCompletionModal') return;
        if (e.target.id === 'v27ApiKeyCreatedModal' || e.target.id === 'a27ApiKeyCreatedModal') return;
        if (e.target.id === 'v27KeyRevealOverlay' || e.target.id === 'a27KeyRevealOverlay') return;
        if (e.target.id === 'vizyonAlScreenPermissionModal' || e.target.id === 'aethrionAlScreenPermissionModal') return;
        if (e.target.id === 'moderatorAssignModal') return;
        if (e.target.id === 'jobCreateOverlay') return;
        window.closeModal(e.target.id);
    }
});

