window.loadContestPageData = async function () {
    if (!currentUser) return;
    try {
        var result = await Parse.Cloud.run('getActiveContest', {});
        window.currentContestData = result;
        try {
            var participantCheck = await Parse.Cloud.run('checkContestParticipation', {});
            window.contestIsParticipant = participantCheck && participantCheck.isParticipant;
        } catch (e) { window.contestIsParticipant = false; }
        var joinSection = document.getElementById('contestJoinStatusContent');
        var submitBtn = document.getElementById('contestSubmitProjectBtn');
        if (joinSection) {
            if (window.contestIsParticipant) {
                joinSection.innerHTML = `
                    <div style="text-align:center; padding:20px;">
                        <div style="font-size:48px; margin-bottom:12px;">✅</div>
                        <div style="font-size:18px; font-weight:700; color:var(--accent2); margin-bottom:8px;">Yarışmaya Katıldınız!</div>
                        <p style="color:var(--text2); font-size:13px; margin-bottom:16px;">Artık projenizi gönderebilirsiniz.</p>
                    </div>
                `;
                if (submitBtn) submitBtn.style.display = 'inline-block';
            } else {
                joinSection.innerHTML = `
                    <div style="text-align:center; padding:20px;">
                        <div style="font-size:48px; margin-bottom:12px;">🎯</div>
                        <div style="font-size:16px; font-weight:600; margin-bottom:16px;">Henüz katılmadınız</div>
                        <button class="btn-primary" onclick="window.openContestJoinWarning()" style="font-size:15px; padding:14px 32px;">
                            🚀 Yarışmaya Katıl
                        </button>
                    </div>
                `;
                if (submitBtn) submitBtn.style.display = 'none';
            }
        }
        await window.loadContestRankingV2();
    } catch (e) {
        console.error('Yarışma sayfası yüklenemedi:', e);
        showNotification('Yarışma verileri yüklenemedi: ' + e.message, 'error');
    }
};

window.loadContestRankingV2 = async function () {
    var container = document.getElementById('contestRankingList');
    if (!container) return;
    try {
        var result = await Parse.Cloud.run('getContestRankingV2', {});
        if (!result || !result.ranking || result.ranking.length === 0) {
            container.innerHTML = '<div class="contest-empty-state">📭 Henüz yarışmaya katılan yok. İlk sen katıl!</div>';
            return;
        }
        var html = '';
        var myEmail = currentUser ? currentUser.get('email') : null;
        result.ranking.forEach(function (item, index) {
            var medal = index === 0 ? '🥇' : index === 1 ? '🥈' : index === 2 ? '🥉' : (index + 1) + '.';
            var rankClass = index === 0 ? 'rank-1' : index === 1 ? 'rank-2' : index === 2 ? 'rank-3' : '';
            var isMyRow = (item.user_email === myEmail) ? 'my-row' : '';
            var displayEmail = item.user_email;
            var displayName = item.user_name || item.user_email.split('@')[0];
            html += `<div class="contest-ranking-row ${rankClass} ${isMyRow}">`;
            html += `<div><span class="contest-ranking-name">${medal} ${window.escapeHtml(displayName)}</span><br><span class="contest-ranking-email">${window.escapeHtml(displayEmail)}</span></div>`;
            html += `<div class="contest-ranking-points">${item.total_points || 0} Puan</div>`;
            html += `</div>`;
        });
        container.innerHTML = html;
    } catch (e) {
        console.error('Sıralama yüklenemedi:', e);
        container.innerHTML = '<div class="contest-empty-state">⚠️ Sıralama yüklenemedi.</div>';
    }
};

window.loadContestRanking = async function () {
    var container = document.getElementById('contestRanking');
    if (!container) return;
    try {
        var result = await Parse.Cloud.run('getContestRankingV2', {});
        if (!result || !result.ranking || result.ranking.length === 0) {
            container.innerHTML = '<div style="color:var(--text3);padding:12px;text-align:center;">📊 Henüz katılımcı yok.</div>';
            return;
        }
        var html = '<div style="font-size:13px;">';
        var medals = ['🥇', '🥈', '🥉'];
        result.ranking.slice(0, 5).forEach(function (item, index) {
            var medal = index < 3 ? medals[index] : (index + 1) + '.';
            html += `
                <div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--border);">
                    <span>${medal} ${window.escapeHtml(item.user_name || item.user_email.split('@')[0])}</span>
                    <span style="color:var(--gold);font-weight:600;">${item.total_points || 0} puan</span>
                </div>
            `;
        });
        html += '</div>';
        container.innerHTML = html;
    } catch (e) {
        console.error('Yarışma sıralaması yüklenemedi:', e);
        container.innerHTML = '<div style="color:var(--text3);padding:12px;text-align:center;">⚠️ Yüklenemedi.</div>';
    }
};

