window.reviewContestProject = function (projectId) {
    var proj = window.contestProjectsFounderCache.find(function (p) { return p.id === projectId; });
    if (!proj) return showNotification('Proje bulunamadı!', 'error');
    window.currentReviewingProject = proj;
    var emailEl = document.getElementById('contestReviewEmail');
    var nameEl = document.getElementById('contestReviewName');
    var projNameEl = document.getElementById('contestReviewProjectName');
    var codeEl = document.getElementById('contestReviewCode');
    if (emailEl) emailEl.textContent = proj.user_email || '-';
    if (nameEl) nameEl.textContent = proj.user_name || '-';
    if (projNameEl) projNameEl.textContent = proj.project_name || '-';
    if (codeEl) codeEl.textContent = proj.code || '-';
    var modal = document.getElementById('contestReviewModal');
    if (modal) { modal.classList.add('open'); modal.style.display = 'flex'; }
};

window.closeContestReview = function () {
    var modal = document.getElementById('contestReviewModal');
    if (modal) { modal.classList.remove('open'); modal.style.display = 'none'; }
    window.currentReviewingProject = null;
};

window.openContestScore = function (projectId) {
    var proj = window.contestProjectsFounderCache.find(function (p) { return p.id === projectId; });
    if (!proj) return showNotification('Proje bulunamadı!', 'error');
    window.currentScoringProject = proj;
    var projNameEl = document.getElementById('contestScoreProjectName');
    var userNameEl = document.getElementById('contestScoreUserName');
    var input = document.getElementById('contestScoreInput');
    if (projNameEl) projNameEl.textContent = proj.project_name || '-';
    if (userNameEl) userNameEl.textContent = (proj.user_name || 'Kullanıcı') + ' (' + proj.user_email + ')';
    if (input) input.value = proj.points || '';
    var modal = document.getElementById('contestScoreModal');
    if (modal) { modal.classList.add('open'); modal.style.display = 'flex'; }
};

window.closeContestScore = function () {
    var modal = document.getElementById('contestScoreModal');
    if (modal) { modal.classList.remove('open'); modal.style.display = 'none'; }
    window.currentScoringProject = null;
};

window.saveContestScore = async function () {
    if (!currentUser || currentUser.get('role') !== 'founder') return showNotification('Sadece kurucu puan verebilir!', 'error');
    if (!window.currentScoringProject) return showNotification('Proje seçilmedi!', 'error');
    var input = document.getElementById('contestScoreInput');
    var points = parseInt(input.value);
    if (isNaN(points) || points < 1 || points > 10000) return showNotification('Lütfen 1-10000 arası geçerli bir puan girin!', 'error');
    try {
        var result = await Parse.Cloud.run('scoreContestProject', { projectId: window.currentScoringProject.id, points: points });
        if (result.success) {
            showNotification('✅ Puan kaydedildi!', 'success');
            window.closeContestScore();
            await window.loadContestProjectsForFounder();
        } else {
            showNotification('❌ ' + (result.error || result.message), 'error');
        }
    } catch (e) { showNotification('Hata: ' + e.message, 'error'); }
};

