window.openAccountInfo = function () {
    if (!currentUser) return showNotification('Önce giriş yapın!', 'error');
    var user = currentUser;
    var name = user.get('name') || 'İsimsiz';
    var email = user.get('email') || '-';
    var username = user.get('username') || user.get('username_display') || '-';
    var role = user.get('role') || 'user';
    var plan = user.get('plan') || 'free';
    var points = user.get('points') || 0;
    var level = user.get('level') || 'Çaylak';
    var teamId = user.get('teamId') || null;
    var isVerified = user.get('isVerified') || false;
    var createdAt = user.get('createdAt');
    var lastLogin = user.get('updatedAt') || createdAt;
    var recoveryEmail = user.get('recovery_email') || 'Belirlenmemiş';
    var isBanned = user.get('isBanned') || false;
    var referralCode = user.get('referral_code') || 'Henüz oluşturulmamış';
    var walletBalance = user.get('wallet_balance') || 0;
    var roleLabels = { founder: '👑 KURUCU', admin: '⚙️ ADMIN', beta: '🔬 BETA', moderator: '🎨 MODERATÖR', user: '👤 KULLANICI' };
    var roleLabel = roleLabels[role] || '👤 KULLANICI';
    var planLabels = { free: '🆓 Ücretsiz', pro: '🌟 Pro', team: '👥 Takım' };
    var planLabel = planLabels[plan] || '🆓 Ücretsiz';
    var dateStr = '-';
    try { if (createdAt) dateStr = new Date(createdAt).toLocaleString('tr-TR'); } catch (e) {}
    var lastLoginStr = '-';
    try { if (lastLogin) lastLoginStr = new Date(lastLogin).toLocaleString('tr-TR'); } catch (e) {}
    var device = navigator.userAgent.indexOf('Mobile') !== -1 ? '📱 Mobil' : '💻 Masaüstü';
    var browser = 'Bilinmiyor';
    var ua = navigator.userAgent;
    if (ua.indexOf('Chrome') !== -1) browser = 'Chrome';
    else if (ua.indexOf('Firefox') !== -1) browser = 'Firefox';
    else if (ua.indexOf('Safari') !== -1) browser = 'Safari';
    else if (ua.indexOf('Edge') !== -1) browser = 'Edge';
    var teamInfo = teamId ? '👥 Takıma Kayıtlı' : 'Takım Yok';

    function infoRow(label, value, color) {
        var colorMap = { accent: 'var(--accent)', accent2: 'var(--accent2)', gold: 'var(--gold)', purple: 'var(--purple)', pink: 'var(--pink)', danger: 'var(--danger)', text2: 'var(--text2)', text3: 'var(--text3)' };
        var c = colorMap[color] || 'var(--text)';
        return '<div style="display:flex; justify-content:space-between; align-items:center; gap:12px; padding:10px 16px; border-bottom:1px solid rgba(255,255,255,0.04);">' +
            '<span style="font-size:12.5px; color:var(--text3); flex-shrink:0;">' + label + '</span>' +
            '<span style="font-size:13px; color:' + c + '; font-weight:600; word-break:break-all; text-align:right; font-family:var(--font-code);">' + value + '</span>' +
            '</div>';
    }

    var modalHtml = '<div id="accountInfoModalContent" class="modal-overlay open" style="display:flex; z-index:9999999;" onclick="if(event.target===this) this.remove()">' +
        '<div class="modal" style="max-width:580px; max-height:90vh; overflow-y:auto;" onclick="event.stopPropagation()">' +
            '<div class="modal-header">' +
                '<h3 style="color:var(--accent);">📋 Hesap Bilgilerim</h3>' +
                '<button class="modal-close" onclick="document.getElementById(\'accountInfoModalContent\').remove()">×</button>' +
            '</div>' +
            '<div style="padding:10px 0;">' +
                '<div style="text-align:center; margin-bottom:24px;">' +
                    '<div style="width:90px; height:90px; margin:0 auto 14px; border-radius:50%; background:linear-gradient(135deg, #d4af37, #b8c0d0, #7c5cff); display:flex; align-items:center; justify-content:center; font-size:40px; color:#0a0a0e; box-shadow: 0 0 40px rgba(212,175,55,0.5);">' + name.charAt(0).toUpperCase() + '</div>' +
                    '<div style="font-family:var(--font-display); font-size:22px; font-weight:800; color:var(--text); margin-bottom:6px;">' + window.escapeHtml(name) + '</div>' +
                    '<div style="display:inline-flex; gap:8px; flex-wrap:wrap; justify-content:center;">' +
                        '<span style="font-size:11px; padding:4px 12px; border-radius:20px; background:linear-gradient(135deg, rgba(212,175,55,0.15), rgba(124,92,255,0.08)); border:1px solid rgba(212,175,55,0.3); color:var(--accent); font-weight:700;">' + roleLabel + '</span>' +
                        '<span style="font-size:11px; padding:4px 12px; border-radius:20px; background:linear-gradient(135deg, rgba(212,175,55,0.15), rgba(232,197,85,0.08)); border:1px solid rgba(212,175,55,0.3); color:var(--gold); font-weight:700;">' + planLabel + '</span>' +
                        (isBanned ? '<span style="font-size:11px; padding:4px 12px; border-radius:20px; background:rgba(239,68,68,0.15); border:1px solid rgba(239,68,68,0.4); color:var(--danger); font-weight:700;">🚫 ENGELLİ</span>' : '') +
                    '</div>' +
                '</div>' +
                '<div style="display:flex; flex-direction:column; gap:2px; background:rgba(0,0,0,0.3); border-radius:14px; padding:6px 4px; border:1px solid var(--border2);">' +
                    infoRow('📧 E-posta', email, 'accent') +
                    infoRow('👤 Kullanıcı Adı', username, 'accent') +
                    infoRow('🔐 Kurtarma Maili', recoveryEmail, 'accent2') +
                    infoRow('🆔 Kullanıcı ID', user.id, 'text3') +
                    infoRow('⭐ Puan', points + ' Puan', 'gold') +
                    infoRow('🏷️ Seviye', level, 'purple') +
                    infoRow('🎁 Davet Kodu', referralCode, 'accent2') +
                    infoRow('👥 Takım', teamInfo, 'text2') +
                    infoRow('💰 Cüzdan', walletBalance.toFixed(2) + ' ₺', 'gold') +
                    infoRow('✅ Doğrulanmış', isVerified ? '✔️ Evet' : '❌ Hayır', isVerified ? 'accent2' : 'danger') +
                    infoRow('📅 Kayıt Tarihi', dateStr, 'text3') +
                    infoRow('🕒 Son Giriş', lastLoginStr, 'text3') +
                    infoRow('🖥️ Cihaz', device + ' · ' + browser, 'text3') +
                    infoRow('🌐 IP Adresi', '<span id="accInfoIP">Yükleniyor...</span>', 'text3') +
                '</div>' +
                '<div style="display:flex; gap:10px; margin-top:20px; flex-wrap:wrap;">' +
                    '<button class="btn-secondary" onclick="window.openProfileModal(); document.getElementById(\'accountInfoModalContent\').remove();" style="flex:1; padding:12px; border-radius:30px; font-size:13px;">✏️ Profili Düzenle</button>' +
                    '<button class="btn-primary" onclick="document.getElementById(\'accountInfoModalContent\').remove();" style="flex:1; padding:12px; border-radius:30px; font-size:13px;">✅ Kapat</button>' +
                '</div>' +
                '<div style="margin-top:14px; padding:12px 14px; background:linear-gradient(135deg, rgba(212,175,55,0.06), rgba(124,92,255,0.04)); border:1px solid rgba(212,175,55,0.2); border-radius:12px; font-size:11.5px; color:#8ab4cc; line-height:1.7; text-align:center;">' +
                    '🔒 <strong style="color:var(--accent);">Gizlilik:</strong> Bu bilgiler sadece size gösterilir. IP adresiniz hiçbir yerde saklanmaz.<br>' +
                    '<em style="color:var(--accent2); font-style:italic;">AETHRION — Intelligence Without Limits.</em>' +
                '</div>' +
            '</div>' +
        '</div>' +
    '</div>';

    var old = document.getElementById('accountInfoModalContent');
    if (old) old.remove();
    document.body.insertAdjacentHTML('beforeend', modalHtml);

    fetch('https://api.ipify.org?format=json')
        .then(function(res) { return res.json(); })
        .then(function(data) {
            var ipEl = document.getElementById('accInfoIP');
            if (ipEl && data && data.ip) ipEl.textContent = data.ip;
        })
        .catch(function() {
            var ipEl = document.getElementById('accInfoIP');
            if (ipEl) ipEl.textContent = 'Alınamadı';
        });
};

window.checkAndShowSubscriptionCard = async function () {
    if (!currentUser) return;
    try {
        var result = await Parse.Cloud.run('getMySubscriptions', {});
        var wrapper = document.getElementById('subscriptionsCardWrapper');
        var content = document.getElementById('subscriptionsContent');
        if (!wrapper || !content) return;
        if (!result || (!result.blogActive && !result.systemActive)) { wrapper.style.display = 'none'; return; }
        wrapper.style.display = 'block';
        var html = '<div style="display:flex; flex-direction:column; gap:10px;">';
        if (result.blogActive) html += '<div style="padding:10px 14px; background:linear-gradient(135deg, rgba(184,192,208,0.1), rgba(212,175,55,0.06)); border-left:3px solid var(--accent2); border-radius:10px; font-size:13px;">✅ <strong>Blog Güncellemeleri</strong> aktif</div>';
        if (result.systemActive) html += '<div style="padding:10px 14px; background:linear-gradient(135deg, rgba(212,175,55,0.1), rgba(124,92,255,0.06)); border-left:3px solid var(--accent); border-radius:10px; font-size:13px;">✅ <strong>Sistem Güncellemeleri</strong> aktif</div>';
        html += '<button class="btn-secondary btn-sm" onclick="window.unsubscribeAll()" style="font-size:12px; margin-top:6px;">🔕 Tüm Abonelikleri İptal Et</button>';
        html += '</div>';
        content.innerHTML = html;
    } catch (e) { console.warn('Abonelik kontrolü hatası:', e.message); }
};

