window.getJobLimitText = function () {
    if (!currentUser) return 'Giriş yapmalısınız';
    var limits = window.getPlanLimits(currentUser);
    var limit = limits.jobListings;
    if (limit === -1) return '♾️ Sınırsız';
    var used = getUsageData('jobListings', 'lifetime');
    var remaining = Math.max(0, limit - used);
    return remaining + ' / ' + limit;
};

window.openJobMarket = function () {
    if (!currentUser) {
        showNotification('Bu özelliği kullanmak için giriş yapın!', 'error');
        return;
    }
    var overlay = document.getElementById('jobMarketOverlay');
    if (!overlay) {
        console.warn('jobMarketOverlay bulunamadı, fallback kullanılıyor');
        window.openJobMarketFallback();
        return;
    }
    overlay.classList.add('open');
    overlay.style.display = 'flex';
    window.jobMarketActive = true;
    window.addLogInfo('A27 İş İlanları Mağazası açıldı');
    window.loadJobMarket();
    window.updateJobMarketLimitBadge();
};

window.openJobMarketFallback = function () {
    var modal = document.getElementById('jobMarketFallbackModal');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'jobMarketFallbackModal';
        modal.className = 'modal-overlay';
        modal.style.cssText = 'display:flex; z-index:999998;';
        modal.innerHTML = `
            <div class="modal" style="max-width:1000px; max-height:90vh; overflow-y:auto; padding:24px;">
                <div class="modal-header" style="display:flex; justify-content:space-between; align-items:center; margin-bottom:20px;">
                    <h3 style="color:var(--gold); font-size:22px;">💼 A27 İş İlanları Mağazası</h3>
                    <button class="modal-close" onclick="this.closest('.modal-overlay').remove()">×</button>
                </div>
                <div id="jobMarketFallbackList" style="display:grid; grid-template-columns:repeat(auto-fill, minmax(280px,1fr)); gap:14px;"></div>
                <div style="display:flex; justify-content:center; gap:12px; margin-top:20px; flex-wrap:wrap;">
                    <button class="btn-primary" onclick="window.openJobCreateFormFallback()">➕ İlan Ver</button>
                    <button class="btn-secondary" onclick="this.closest('.modal-overlay').remove()">Kapat</button>
                </div>
            </div>
        `;
        document.body.appendChild(modal);
    }
    modal.classList.add('open');
    window.loadJobMarketFallbackList();
};

window.loadJobMarketFallbackList = async function () {
    var list = document.getElementById('jobMarketFallbackList');
    if (!list) return;
    list.innerHTML = '<div style="grid-column:1/-1;text-align:center;color:var(--text3);padding:40px;">⏳ Yükleniyor...</div>';
    try {
        var result = await Parse.Cloud.run('getJobListings', { limit: 50 });
        var jobs = (result && result.listings) ? result.listings : ((result && result.jobs) ? result.jobs : []);
        if (jobs.length === 0) {
            list.innerHTML = '<div style="grid-column:1/-1;text-align:center;color:var(--text3);padding:40px;">📭 Henüz ilan yok. İlk ilanı sen ver!</div>';
            return;
        }
        var html = '';
        jobs.forEach(function(job) {
            var typeIcon = job.job_type === 'Kod' ? '💻' : job.job_type === 'Tasarım' ? '🎨' : job.job_type === 'Video' ? '🎬' : '📦';
            html += '<div style="background:linear-gradient(135deg,rgba(212,175,55,0.06),rgba(124,92,255,0.03)); border:1px solid var(--border2); border-radius:14px; padding:16px; cursor:pointer;" onclick="window.openJobDetail && window.openJobDetail(\'' + job.id + '\')">';
            html += '<div style="font-size:10px; color:var(--accent); font-family:var(--font-code); margin-bottom:6px;">' + window.escapeHtml(job.job_number || '') + '</div>';
            html += '<div style="font-weight:700; color:var(--text); margin-bottom:6px;">' + typeIcon + ' ' + window.escapeHtml(job.job_type || 'İlan') + '</div>';
            html += '<div style="font-size:12px; color:var(--text2); line-height:1.6; margin-bottom:8px;">' + window.escapeHtml((job.description || '').substring(0, 100)) + '</div>';
            html += '<div style="font-size:12px; color:var(--text3);">👤 ' + window.escapeHtml(job.owner_name || 'Kullanıcı') + '</div>';
            html += '<div style="color:var(--gold); font-weight:700; font-size:13px; margin-top:6px;">⭐ ' + (job.salary || 0) + '</div>';
            html += '</div>';
        });
        list.innerHTML = html;
    } catch (e) {
        list.innerHTML = '<div style="grid-column:1/-1;text-align:center;color:var(--danger);padding:40px;">⚠️ Yüklenemedi: ' + window.escapeHtml(e.message) + '</div>';
    }
};

window.openJobCreateFormFallback = function () {
    var type = prompt('İş türü (Kod / Tasarım / Video / Çeviri / Yazar / 3D / Müzik / Diğer):', 'Kod');
    if (!type) return;
    var desc = prompt('İş açıklaması:');
    if (!desc) return;
    var salary = prompt('Ücret / Ödül (örn: 5000 TL, 100 puan):');
    if (!salary) return;
    var payment = prompt('Ödeme yöntemi (örn: Nakit, Kripto, A27 Puan):', 'A27 Puan');
    if (!payment) return;
    window.submitJobCreateDirect({ jobType: type, description: desc, salary: salary, paymentMethod: payment });
};

window.submitJobCreateDirect = async function (params) {
    if (!currentUser) return showNotification('Giriş yapın!', 'error');
    try {
        var result = await Parse.Cloud.run('createJobListing', {
            jobType: params.jobType,
            description: params.description,
            salary: params.salary,
            paymentMethod: params.paymentMethod,
            imageUrl: params.imageUrl || null
        });
        if (result.success) {
            window.incrementUsage('jobListings', 'lifetime', 1);
            showNotification('✅ İlan yayınlandı! No: ' + result.job_number, 'success');
            if (typeof window.addLogSuccess === 'function') window.addLogSuccess('A27 İş ilanı oluşturuldu: ' + result.job_number);
            if (typeof window.loadJobMarketFallbackList === 'function') window.loadJobMarketFallbackList();
            if (typeof window.loadJobMarket === 'function') window.loadJobMarket();
            window.updateJobMarketLimitBadge();
        } else {
            showNotification('❌ ' + (result.error || 'İlan yayınlanamadı'), 'error');
        }
    } catch (e) {
        showNotification('Hata: ' + e.message, 'error');
    }
};

window.closeJobMarket = function () {
    var overlay = document.getElementById('jobMarketOverlay');
    if (overlay) {
        overlay.classList.remove('open');
        overlay.style.display = 'none';
    }
    window.jobMarketActive = false;
};

window.loadJobMarket = async function () {
    var grid = document.getElementById('jobMarketGrid');
    if (!grid) return;
    grid.innerHTML = '<div class="job-market-empty"><span class="empty-icon">⏳</span><div>İlanlar yükleniyor...</div></div>';
    try {
        var result = await Parse.Cloud.run('getJobListings', { limit: 100 });
        var jobs = (result && result.listings) ? result.listings : ((result && result.jobs) ? result.jobs : []);
        if (jobs.length === 0) {
            grid.innerHTML = '<div class="job-market-empty"><span class="empty-icon">💼</span><div>Henüz iş ilanı yok. İlk ilanı sen ver!</div></div>';
            window.jobMarketCache = [];
            return;
        }
        window.jobMarketCache = jobs;
        window.renderJobMarket(jobs);
        if (typeof window.addLogInfo === 'function') {
            window.addLogInfo('A27 İş ilanları yüklendi: ' + jobs.length);
        }
    } catch (e) {
        console.error('İş ilanları yüklenemedi:', e);
        grid.innerHTML = '<div class="job-market-empty"><span class="empty-icon">⚠️</span><div>Yüklenemedi: ' + window.escapeHtml(e.message) + '</div></div>';
        if (typeof window.addLogError === 'function') {
            window.addLogError('A27 İş ilanları yükleme hatası: ' + e.message);
        }
    }
};

window.renderJobMarket = function (jobs) {
    var grid = document.getElementById('jobMarketGrid');
    if (!grid) return;
    if (!jobs || jobs.length === 0) {
        grid.innerHTML = '<div class="job-market-empty"><span class="empty-icon">🔍</span><div>Filtreyle eşleşen ilan yok.</div></div>';
        return;
    }
    var html = '';
    jobs.forEach(function (job) {
        var typeClass = 'type-diger';
        var typeIcon = '📦';
        switch (job.job_type) {
            case 'Kod': typeClass = 'type-kod'; typeIcon = '💻'; break;
            case 'Tasarım': typeClass = 'type-tasarim'; typeIcon = '🎨'; break;
            case 'Video': typeClass = 'type-video'; typeIcon = '🎬'; break;
            case 'Çeviri': typeClass = 'type-ceviri'; typeIcon = '🌐'; break;
            case 'Yazar': typeClass = 'type-yazar'; typeIcon = '✍️'; break;
            case '3D': typeClass = 'type-3d'; typeIcon = '🧊'; break;
            case 'Müzik': typeClass = 'type-muzik'; typeIcon = '🎵'; break;
            default: typeClass = 'type-diger'; typeIcon = '📦';
        }
        var statusClass = '';
        if (job.status === 'accepted') statusClass = 'status-accepted';
        else if (job.status === 'closed') statusClass = 'status-closed';
        var safeTitle = window.escapeHtml(job.title || 'İlan');
        var safeDesc = window.escapeHtml((job.description || '').substring(0, 100));
        var safeOwnerName = window.escapeHtml(job.owner_name || 'Kullanıcı');
        var safeOwnerEmail = window.escapeHtml(job.owner_email || '');
        var safeJobNumber = window.escapeHtml(job.job_number || 'ILN-0000-00000');
        var ownerInitial = (job.owner_name || 'U').charAt(0).toUpperCase();
        html += '<div class="job-card ' + statusClass + '" onclick="window.openJobDetail(\'' + job.id + '\')">';
        html += '<div class="job-card-header">';
        html += '<span class="job-card-number">' + safeJobNumber + '</span>';
        html += '<span class="job-card-type ' + typeClass + '">' + typeIcon + ' ' + window.escapeHtml(job.job_type || 'Diğer') + '</span>';
        html += '</div>';
        if (job.image_url) {
            html += '<img class="job-card-image" src="' + window.escapeHtml(job.image_url) + '" alt="İlan görseli" onerror="this.style.display=\'none\'">';
        }
        html += '<div class="job-card-title">' + safeTitle + '</div>';
        html += '<div class="job-card-desc">' + safeDesc + '</div>';
        html += '<div class="job-card-meta">';
        html += '<div class="job-card-owner">';
        html += '<span class="owner-avatar">' + ownerInitial + '</span>';
        html += '<span style="flex:1;min-width:0;">';
        html += '<div style="font-weight:600;color:var(--text2);font-size:12px;">' + safeOwnerName + '</div>';
        html += '<div class="owner-email">' + safeOwnerEmail + '</div>';
        html += '</span>';
        html += '</div>';
        html += '<div class="job-card-footer">';
        html += '<div class="job-card-salary"><span class="salary-icon">⭐</span>' + window.escapeHtml(job.salary || '0') + '</div>';
        html += '<div class="job-card-views">👁️ ' + (job.views || 0) + '</div>';
        html += '</div>';
        html += '</div>';
        html += '</div>';
    });
    grid.innerHTML = html;
};

window.filterJobMarket = function () {
    var search = (document.getElementById('jobMarketSearchInput') || {}).value || '';
    var typeFilter = (document.getElementById('jobMarketTypeFilter') || {}).value || 'all';
    var statusFilter = (document.getElementById('jobMarketStatusFilter') || {}).value || 'all';
    var filtered = window.jobMarketCache.filter(function (job) {
        if (search) {
            var haystack = ((job.title || '') + ' ' + (job.description || '') + ' ' + (job.job_number || '')).toLowerCase();
            if (haystack.indexOf(search.toLowerCase()) === -1) return false;
        }
        if (typeFilter !== 'all' && job.job_type !== typeFilter) return false;
        if (statusFilter !== 'all' && job.status !== statusFilter) return false;
        return true;
    });
    window.renderJobMarket(filtered);
};

window.openJobCreateForm = function () {
    if (!currentUser) {
        showNotification('Önce giriş yapın!', 'error');
        return;
    }
    var check = window.canCreateJobListing();
    if (!check.allowed) {
        window.showLimitModal('jobListings', {
            allowed: false,
            limit: check.limit,
            used: check.used,
            remaining: 0,
            reason: check.reason
        });
        return;
    }
    var overlay = document.getElementById('jobCreateOverlay');
    if (!overlay) {
        window.openJobCreateFormFallback();
        return;
    }
    var typeSel = document.getElementById('jobCreateType');
    var titleInp = document.getElementById('jobCreateTitle');
    var descInp = document.getElementById('jobCreateDescription');
    var salaryInp = document.getElementById('jobCreateSalary');
    var payInp = document.getElementById('jobCreatePaymentMethod');
    var imgPreview = document.getElementById('jobCreateImagePreview');
    var errBox = document.getElementById('jobCreateError');
    if (typeSel) typeSel.value = '';
    if (titleInp) titleInp.value = '';
    if (descInp) descInp.value = '';
    if (salaryInp) salaryInp.value = '';
    if (payInp) payInp.value = '';
    if (imgPreview) imgPreview.innerHTML = '📷';
    if (errBox) errBox.classList.remove('show');
    window.currentJobCreateImage = null;
    overlay.classList.add('open');
    overlay.style.display = 'flex';
    window.addLogInfo('A27 İlan verme formu açıldı');
};

window.closeJobCreateForm = function () {
    var overlay = document.getElementById('jobCreateOverlay');
    if (overlay) {
        overlay.classList.remove('open');
        overlay.style.display = 'none';
    }
    window.currentJobCreateImage = null;
};

window.handleJobCreateImage = async function (input) {
    var file = input.files[0];
    if (!file) return;
    if (file.size > 2 * 1024 * 1024) {
        showNotification('Resim boyutu 2MB\'ı aşamaz!', 'error');
        input.value = '';
        return;
    }
    var allowed = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp'];
    if (allowed.indexOf(file.type) === -1) {
        showNotification('Sadece JPG, PNG veya WEBP yükleyebilirsin!', 'error');
        input.value = '';
        return;
    }
    try {
        showNotification('📤 Resim yükleniyor...', 'success');
        var parseFile = new Parse.File('job_' + Date.now() + '_' + file.name, file);
        await parseFile.save();
        window.currentJobCreateImage = parseFile.url();
        var preview = document.getElementById('jobCreateImagePreview');
        if (preview) {
            preview.innerHTML = '<img src="' + parseFile.url() + '" alt="Önizleme">';
        }
        showNotification('✅ Resim yüklendi!', 'success');
        if (typeof window.addLogInfo === 'function') {
            window.addLogInfo('A27 İş ilanı resmi yüklendi');
        }
    } catch (e) {
        console.error('Resim yükleme hatası:', e);
        showNotification('Resim yüklenemedi: ' + e.message, 'error');
        if (typeof window.addLogError === 'function') {
            window.addLogError('A27 İlan resmi yükleme hatası: ' + e.message);
        }
    }
};

window.submitJobCreate = async function () {
    if (!currentUser) return showNotification('Önce giriş yapın!', 'error');
    var typeEl = document.getElementById('jobCreateType');
    var titleEl = document.getElementById('jobCreateTitle');
    var descEl = document.getElementById('jobCreateDescription');
    var salaryEl = document.getElementById('jobCreateSalary');
    var payEl = document.getElementById('jobCreatePaymentMethod');
    var errBox = document.getElementById('jobCreateError');
    var submitBtn = document.getElementById('jobCreateSubmitBtn');

    var type = typeEl ? typeEl.value : '';
    var title = titleEl ? titleEl.value.trim() : '';
    var description = descEl ? descEl.value.trim() : '';
    var salary = salaryEl ? parseInt(salaryEl.value) : 0;
    var paymentMethod = payEl ? payEl.value.trim() : '';

    function showErr(msg) {
        if (errBox) { errBox.textContent = '❌ ' + msg; errBox.classList.add('show'); }
        showNotification('❌ ' + msg, 'error');
    }
    if (errBox) errBox.classList.remove('show');

    if (!type) return showErr('Lütfen ilan türünü seçin!');
    if (!title) return showErr('Lütfen ilan başlığı girin!');
    if (title.length < 3) return showErr('Başlık en az 3 karakter olmalı!');
    if (title.length > 120) return showErr('Başlık en fazla 120 karakter olabilir!');
    if (!description) return showErr('Lütfen açıklama yazın!');
    if (description.length < 10) return showErr('Açıklama en az 10 karakter olmalı!');
    if (description.length > 2000) return showErr('Açıklama en fazla 2000 karakter olabilir!');
    if (isNaN(salary) || salary < 1 || salary > 100000) return showErr('Maaş 1-100000 arası bir puan olmalı!');
    if (!paymentMethod) return showErr('Lütfen ödeme şeklini yazın!');

    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.textContent = '⏳ Yayınlanıyor...';
    }

    try {
        var result = await Parse.Cloud.run('createJobListing', {
            jobType: type,
            title: title,
            description: description,
            salary: salary,
            paymentMethod: paymentMethod,
            imageUrl: window.currentJobCreateImage || null
        });
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.textContent = '✅ İlanı Yayınla';
        }
        if (result.success) {
            window.incrementUsage('jobListings', 'lifetime', 1);
            showNotification('✅ İlan yayınlandı! İlan No: ' + result.job_number, 'success');
            if (typeof window.addLogSuccess === 'function') {
                window.addLogSuccess('A27 İş ilanı oluşturuldu: ' + result.job_number);
            }
            window.closeJobCreateForm();
            window.loadJobMarket();
            window.updateJobMarketLimitBadge();
            window.loadJobMarketDashboardPreview();
        } else {
            showErr(result.error || 'İlan yayınlanamadı.');
        }
    } catch (e) {
        console.error('İş ilanı oluşturma hatası:', e);
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.textContent = '✅ İlanı Yayınla';
        }
        showErr(e.message || 'Bilinmeyen hata');
        if (typeof window.addLogError === 'function') {
            window.addLogError('A27 İş ilanı oluşturma hatası: ' + e.message);
        }
    }
};

window.openJobDetail = async function (jobId) {
    if (!jobId) return showNotification('İlan ID gerekli!', 'error');
    var overlay = document.getElementById('jobDetailOverlay');
    if (!overlay) {
        window.openJobDetailFallback(jobId);
        return;
    }
    overlay.classList.add('open');
    overlay.style.display = 'flex';
    window.currentJobDetail = null;
    var titleEl = document.getElementById('jobDetailTitle');
    var numberEl = document.getElementById('jobDetailNumberBadge');
    var numberEl2 = document.getElementById('jobDetailNumberBadge2');
    var typeEl = document.getElementById('jobDetailType');
    var salaryEl = document.getElementById('jobDetailSalary');
    var payEl = document.getElementById('jobDetailPaymentMethod');
    var createdEl = document.getElementById('jobDetailCreatedAt');
    var viewsEl = document.getElementById('jobDetailViews');
    var statusEl = document.getElementById('jobDetailStatus');
    var imgEl = document.getElementById('jobDetailImage');
    var descEl = document.getElementById('jobDetailDescription');
    var ownerAvatar = document.getElementById('jobDetailOwnerAvatar');
    var ownerName = document.getElementById('jobDetailOwnerName');
    var ownerEmail = document.getElementById('jobDetailOwnerEmail');
    var actionsEl = document.getElementById('jobDetailActions');
    var editBtn = document.getElementById('jobDetailEditBtn');
    var delBtn = document.getElementById('jobDetailDeleteBtn');

    if (titleEl) titleEl.textContent = 'Yükleniyor...';
    if (imgEl) imgEl.style.display = 'none';
    if (editBtn) editBtn.style.display = 'none';
    if (delBtn) delBtn.style.display = 'none';

    try {
        var result = await Parse.Cloud.run('getJobDetail', { jobId: jobId });
        var job = (result && result.listing) ? result.listing : ((result && result.job) ? result.job : null);
        if (!job) {
            showNotification('❌ İlan bulunamadı!', 'error');
            window.closeJobDetail();
            return;
        }
        window.currentJobDetail = job;

        if (numberEl) numberEl.textContent = job.job_number || 'ILN-0000-00000';
        if (numberEl2) numberEl2.textContent = job.job_number || 'ILN-0000-00000';
        if (titleEl) titleEl.textContent = job.title || (job.job_type + ' İlanı') || 'İlan';
        if (typeEl) typeEl.textContent = job.job_type || '-';
        if (salaryEl) salaryEl.textContent = '⭐ ' + (job.salary || 0);
        if (payEl) payEl.textContent = job.payment_method || '-';
        var createdStr = job.createdAt ? new Date(job.createdAt).toLocaleString('tr-TR') : '-';
        if (createdEl) createdEl.textContent = createdStr;
        if (viewsEl) viewsEl.textContent = (job.views || 0) + ' görüntülenme';
        if (statusEl) {
            var statusLabels = { 'open': '✅ Açık', 'accepted': '🤝 Kabul Edildi', 'closed': '🔒 Kapalı' };
            statusEl.textContent = statusLabels[job.status] || '✅ Açık';
        }
        if (job.image_url && imgEl) {
            imgEl.src = job.image_url;
            imgEl.style.display = 'block';
        } else if (imgEl) {
            imgEl.style.display = 'none';
        }
        if (descEl) descEl.textContent = job.description || '-';
        var initial = (job.owner_name || 'U').charAt(0).toUpperCase();
        if (ownerAvatar) ownerAvatar.textContent = initial;
        if (ownerName) ownerName.textContent = job.owner_name || 'Kullanıcı';
        if (ownerEmail) ownerEmail.textContent = job.owner_email || '';

        var isOwner = (currentUser && (currentUser.get('email') === job.owner_email || currentUser.get('role') === 'founder'));
        if (isOwner) {
            if (editBtn) editBtn.style.display = 'inline-flex';
            if (delBtn) delBtn.style.display = 'inline-flex';
        }

        if (actionsEl) {
            if (job.status === 'accepted') {
                actionsEl.innerHTML = '<div style="text-align:center;padding:20px;color:var(--accent2);font-size:16px;font-weight:700;">🤝 Bu ilan kabul edilmiş.</div>';
            } else if (job.status === 'closed') {
                actionsEl.innerHTML = '<div style="text-align:center;padding:20px;color:var(--text3);font-size:16px;font-weight:700;">🔒 Bu ilan kapatılmış.</div>';
            } else if (isOwner) {
                actionsEl.innerHTML = '<div style="text-align:center;padding:16px;color:var(--gold);font-size:14px;">👑 Bu ilan sizin. Kabul edilmesini bekliyor.</div>';
            } else {
                actionsEl.innerHTML = '<button class="job-accept-btn" onclick="window.acceptJobListing()">🤝 İşi Kabul Et</button>';
            }
        }

        if (typeof window.addLogInfo === 'function') {
            window.addLogInfo('A27 İş ilanı görüntülendi: ' + job.job_number);
        }
    } catch (e) {
        console.error('İlan detay hatası:', e);
        showNotification('Hata: ' + e.message, 'error');
    }
};

window.openJobDetailFallback = async function (jobId) {
    try {
        var result = await Parse.Cloud.run('getJobDetail', { jobId: jobId });
        var job = (result && result.listing) ? result.listing : null;
        if (!job) return showNotification('İlan bulunamadı', 'error');
        alert('📋 ' + (job.job_number || '') + '\n\nTür: ' + job.job_type + '\nÜcret: ' + job.salary + '\nÖdeme: ' + job.payment_method + '\n\nAçıklama:\n' + job.description + '\n\n👤 ' + (job.owner_name || 'Kullanıcı') + ' (' + (job.owner_email || '') + ')');
    } catch (e) {
        showNotification('Hata: ' + e.message, 'error');
    }
};

window.closeJobDetail = function () {
    var overlay = document.getElementById('jobDetailOverlay');
    if (overlay) {
        overlay.classList.remove('open');
        overlay.style.display = 'none';
    }
    window.currentJobDetail = null;
};

window.acceptJobListing = async function () {
    if (!currentUser) return showNotification('Önce giriş yapın!', 'error');
    if (!window.currentJobDetail) return showNotification('İlan bilgisi yok!', 'error');
    var job = window.currentJobDetail;
    if (job.owner_email === currentUser.get('email')) {
        return showNotification('Kendi ilanınızı kabul edemezsiniz!', 'warning');
    }
    if (job.status !== 'open') {
        return showNotification('Bu ilan zaten kabul edilmiş veya kapatılmış!', 'warning');
    }
    if (!confirm('Bu işi kabul etmek istediğinize emin misiniz?\n\nİlan sahibine bildirim gönderilecek: "' + job.job_number + ' numaralı ilanınızı ' + currentUser.get('email') + ' kabul etti."')) {
        return;
    }
    try {
        var result = await Parse.Cloud.run('acceptJobListing', { jobId: job.id });
        if (result.success) {
            showNotification('✅ İşi kabul ettiniz! İlan sahibine bildirim gönderildi.', 'success');
            if (typeof window.addLogSuccess === 'function') {
                window.addLogSuccess('A27 İş ilanı kabul edildi: ' + job.job_number);
            }
            window.closeJobDetail();
            window.loadJobMarket();
        } else {
            showNotification('❌ ' + (result.error || 'İş kabul edilemedi.'), 'error');
        }
    } catch (e) {
        console.error('İş kabul hatası:', e);
        showNotification('Hata: ' + e.message, 'error');
    }
};

window.editJobListing = function () {
    if (!currentUser) return showNotification('Önce giriş yapın!', 'error');
    if (!window.currentJobDetail) return showNotification('İlan bilgisi yok!', 'error');
    var job = window.currentJobDetail;
    if (currentUser.get('email') !== job.owner_email && currentUser.get('role') !== 'founder') {
        return showNotification('Bu ilanı düzenleme yetkiniz yok!', 'error');
    }
    window.closeJobDetail();
    window.openJobCreateForm();
    setTimeout(function () {
        var typeSel = document.getElementById('jobCreateType');
        var titleInp = document.getElementById('jobCreateTitle');
        var descInp = document.getElementById('jobCreateDescription');
        var salaryInp = document.getElementById('jobCreateSalary');
        var payInp = document.getElementById('jobCreatePaymentMethod');
        if (typeSel) typeSel.value = job.job_type || '';
        if (titleInp) titleInp.value = job.title || '';
        if (descInp) descInp.value = job.description || '';
        if (salaryInp) salaryInp.value = job.salary || '';
        if (payInp) payInp.value = job.payment_method || '';
        window._editingJobId = job.id;
        var submitBtn = document.getElementById('jobCreateSubmitBtn');
        if (submitBtn) submitBtn.textContent = '💾 Güncelle';
        var modal = document.querySelector('#jobCreateOverlay .job-create-modal');
        if (modal) {
            var h3 = modal.querySelector('h3');
            if (h3) h3.textContent = '✏️ İlanı Düzenle';
        }
    }, 100);
};

window.deleteJobListing = async function () {
    if (!currentUser) return showNotification('Önce giriş yapın!', 'error');
    if (!window.currentJobDetail) return showNotification('İlan bilgisi yok!', 'error');
    var job = window.currentJobDetail;
    if (currentUser.get('email') !== job.owner_email && currentUser.get('role') !== 'founder') {
        return showNotification('Bu ilanı silme yetkiniz yok!', 'error');
    }
    if (!confirm('"' + job.job_number + '" numaralı ilanı silmek istediğinize emin misiniz? Bu işlem geri alınamaz!')) {
        return;
    }
    try {
        var result = await Parse.Cloud.run('deleteJobListing', { jobId: job.id });
        if (result.success) {
            showNotification('🗑️ İlan silindi.', 'success');
            if (typeof window.addLogInfo === 'function') {
                window.addLogInfo('A27 İş ilanı silindi: ' + job.job_number);
            }
            window.closeJobDetail();
            window.loadJobMarket();
            window.updateJobMarketLimitBadge();
        } else {
            showNotification('❌ ' + (result.error || 'İlan silinemedi.'), 'error');
        }
    } catch (e) {
        console.error('İlan silme hatası:', e);
        showNotification('Hata: ' + e.message, 'error');
    }
};

window.updateJobMarketLimitBadge = function () {
    if (!currentUser) return;
    var limits = window.getPlanLimits(currentUser);
    var limit = limits.jobListings;
    var used = getUsageData('jobListings', 'lifetime');
    var headerBadge = document.getElementById('jobMarketHeaderLimitBadge');
    var mainBadge = document.getElementById('jobMarketLimitBadge');
    var remainingText = document.getElementById('jobMarketRemainingText');
    var limitText;
    if (limit === -1) {
        limitText = '💼 ♾️ Sınırsız';
    } else {
        var remaining = Math.max(0, limit - used);
        limitText = '💼 ' + used + ' / ' + limit + ' kullanıldı · ' + remaining + ' kaldı';
    }
    if (headerBadge) {
        headerBadge.textContent = limitText;
        if (limit !== -1 && used >= limit) headerBadge.classList.add('danger');
        else if (limit === -1) headerBadge.classList.add('unlimited');
    }
    if (mainBadge) {
        mainBadge.textContent = limitText;
        if (limit !== -1 && used >= limit) mainBadge.classList.add('danger');
        else if (limit === -1) mainBadge.classList.add('unlimited');
    }
    if (remainingText) {
        if (limit === -1) remainingText.textContent = '♾️';
        else remainingText.textContent = Math.max(0, limit - used) + ' / ' + limit;
    }
};

window.loadJobMarketDashboardPreview = async function () {
    var container = document.getElementById('jobMarketDashboardPreview');
    if (!container) return;
    container.innerHTML = '<div style="color:var(--text3); font-size:12px; text-align:center; padding:20px; grid-column:1/-1;">⏳ Yükleniyor...</div>';
    try {
        var result = await Parse.Cloud.run('getJobListings', { limit: 3 });
        var jobs = (result && result.listings) ? result.listings : ((result && result.jobs) ? result.jobs : []);
        if (jobs.length === 0) {
            container.innerHTML = '<div style="color:var(--text3); font-size:12px; text-align:center; padding:20px; grid-column:1/-1;">📭 Henüz ilan yok. İlk ilanı sen ver!</div>';
            return;
        }
        var html = '';
        jobs.forEach(function (job) {
            var typeIcon = job.job_type === 'Kod' ? '💻' : job.job_type === 'Tasarım' ? '🎨' : job.job_type === 'Video' ? '🎬' : job.job_type === 'Çeviri' ? '🌐' : job.job_type === 'Yazar' ? '✍️' : job.job_type === '3D' ? '🧊' : job.job_type === 'Müzik' ? '🎵' : '📦';
            html += '<div style="background:linear-gradient(135deg, rgba(212,175,55,0.06), rgba(124,92,255,0.04)); border:1px solid var(--border2); border-radius:12px; padding:12px; cursor:pointer; transition:all 0.22s;" onclick="window.openJobDetail && window.openJobDetail(\'' + job.id + '\')" onmouseover="this.style.borderColor=\'var(--accent)\'; this.style.transform=\'translateY(-3px)\'" onmouseout="this.style.borderColor=\'var(--border2)\'; this.style.transform=\'translateY(0)\'">';
            html += '<div style="font-size:10px; color:var(--accent); font-family:var(--font-code); margin-bottom:4px;">' + window.escapeHtml(job.job_number || '') + '</div>';
            html += '<div style="font-weight:700; font-size:12.5px; margin-bottom:5px;">' + typeIcon + ' ' + window.escapeHtml((job.title || job.job_type || '').substring(0, 40)) + '</div>';
            html += '<div style="font-size:10.5px; color:var(--text3); margin-bottom:6px;">👤 ' + window.escapeHtml(job.owner_name || 'Kullanıcı') + '</div>';
            html += '<div style="color:var(--gold); font-weight:700; font-size:13px;">⭐ ' + window.escapeHtml(job.salary || '0') + '</div>';
            html += '</div>';
        });
        container.innerHTML = html;
    } catch (e) {
        console.error('Dashboard ilan önizleme hatası:', e);
        container.innerHTML = '<div style="color:var(--text3); font-size:12px; text-align:center; padding:20px; grid-column:1/-1;">⚠️ İlanlar yüklenemedi.</div>';
    }
};

