// ============================================================
// [v1.0.0] VİDEO EDİTÖR (Timeline + Trim + Overlay + Export)
// ============================================================

window.openVideoEditor = function () {
    if (!currentUser) {
        showNotification('Video editör için giriş yapın!', 'error');
        return;
    }
    var check = window.checkFeatureLimit('videoEditorPerMonth', 'month');
    if (!check.allowed && check.limit === 0) {
        window.showLimitModal('videoEditorPerMonth', check);
        return;
    }
    var overlay = document.getElementById('videoEditorOverlay');
    if (!overlay) {
        window.openVideoEditorFallback();
        return;
    }
    overlay.classList.add('open');
    overlay.style.display = 'flex';
    window.videoEditorActive = true;
    window.videoEditorTrimStart = 0;
    window.videoEditorTrimEnd = 0;
    window.videoEditorDuration = 0;
    if (typeof window.addLogInfo === 'function') {
        window.addLogInfo('AETHRION Video Editor açıldı');
    }
};

window.openVideoEditorFallback = function () {
    showNotification('🎬 Video Editör modülü yükleniyor...', 'warning');
    var input = document.createElement('input');
    input.type = 'file';
    input.accept = 'video/*';
    input.onchange = function(e) {
        var file = e.target.files[0];
        if (!file) return;
        showNotification('✅ Video seçildi: ' + file.name, 'success');
        showNotification('ℹ️ Tam video editör için sayfayı yenileyip tekrar deneyin.', 'warning');
    };
    input.click();
};

window.closeVideoEditor = function () {
    var overlay = document.getElementById('videoEditorOverlay');
    if (overlay) {
        overlay.classList.remove('open');
        overlay.style.display = 'none';
    }
    window.videoEditorActive = false;
    var video = document.querySelector('#videoEditorPreview video');
    if (video) {
        try { video.pause(); } catch (e) {}
    }
};

window.handleVideoUpload = function (input) {
    var file = input.files[0];
    if (!file) return;
    if (file.size > 200 * 1024 * 1024) {
        showNotification('Video boyutu 200MB\'ı aşamaz!', 'error');
        return;
    }
    var url = URL.createObjectURL(file);
    var preview = document.getElementById('videoEditorPreview');
    if (!preview) return;
    preview.innerHTML = '<video id="videoEditorVideo" src="' + url + '" controls preload="metadata" style="width:100%;height:100%;object-fit:contain;background:#000;"></video>';
    var video = document.getElementById('videoEditorVideo');
    if (!video) return;
    video.addEventListener('loadedmetadata', function () {
        window.videoEditorDuration = video.duration;
        window.videoEditorTrimStart = 0;
        window.videoEditorTrimEnd = video.duration;
        var startInput = document.getElementById('videoEditorStartSec');
        var endInput = document.getElementById('videoEditorEndSec');
        if (startInput) startInput.value = 0;
        if (endInput) endInput.value = Math.floor(video.duration);
        window.updateVideoSelection();
        window.updateVideoTimeDisplay();
    });
    video.addEventListener('timeupdate', function () {
        window.updateVideoTimeDisplay();
        window.updateVideoPlayhead();
    });
    showNotification('✅ Video yüklendi!', 'success');
    if (typeof window.addLogSuccess === 'function') {
        window.addLogSuccess('AETHRION Video editöre yüklendi: ' + file.name);
    }
};

window.updateVideoTimeDisplay = function () {
    var video = document.getElementById('videoEditorVideo');
    var timeEl = document.getElementById('videoEditorTime');
    if (!video || !timeEl) return;
    var cur = video.currentTime || 0;
    var dur = video.duration || 0;
    function fmt(s) {
        if (!isFinite(s)) return '00:00';
        var m = Math.floor(s / 60);
        var sec = Math.floor(s % 60);
        return (m < 10 ? '0' : '') + m + ':' + (sec < 10 ? '0' : '') + sec;
    }
    timeEl.textContent = fmt(cur) + ' / ' + fmt(dur);
};

window.updateVideoPlayhead = function () {
    var video = document.getElementById('videoEditorVideo');
    var playhead = document.getElementById('videoEditorPlayhead');
    if (!video || !playhead || !window.videoEditorDuration) return;
    var percent = (video.currentTime / window.videoEditorDuration) * 100;
    playhead.style.left = percent + '%';
};

window.updateVideoSelection = function () {
    var startInput = document.getElementById('videoEditorStartSec');
    var endInput = document.getElementById('videoEditorEndSec');
    var selection = document.getElementById('videoEditorSelection');
    if (!startInput || !endInput || !selection || !window.videoEditorDuration) return;
    var s = parseFloat(startInput.value) || 0;
    var e = parseFloat(endInput.value) || window.videoEditorDuration;
    if (s < 0) s = 0;
    if (e > window.videoEditorDuration) e = window.videoEditorDuration;
    if (e <= s) e = s + 1;
    window.videoEditorTrimStart = s;
    window.videoEditorTrimEnd = e;
    var leftPct = (s / window.videoEditorDuration) * 100;
    var widthPct = ((e - s) / window.videoEditorDuration) * 100;
    selection.style.left = leftPct + '%';
    selection.style.width = widthPct + '%';
};

window.videoEditorPlay = function () {
    var video = document.getElementById('videoEditorVideo');
    if (video) video.play();
};

window.videoEditorPause = function () {
    var video = document.getElementById('videoEditorVideo');
    if (video) video.pause();
};

window.videoEditorReset = function () {
    var video = document.getElementById('videoEditorVideo');
    if (video) {
        video.currentTime = 0;
        video.play();
    }
};

window.videoEditorTrim = function () {
    if (!window.videoEditorDuration) return showNotification('Önce video yükleyin!', 'warning');
    showNotification('✂️ Kesme uygulanıyor... (' + window.videoEditorTrimStart.toFixed(1) + 's — ' + window.videoEditorTrimEnd.toFixed(1) + 's)', 'success');
    if (typeof window.addLogInfo === 'function') {
        window.addLogInfo('AETHRION Video trim uygulandı: ' + window.videoEditorTrimStart + 's - ' + window.videoEditorTrimEnd + 's');
    }
};

window.exportVideo = function () {
    if (!window.videoEditorDuration) return showNotification('Önce video yükleyin!', 'warning');
    var video = document.getElementById('videoEditorVideo');
    if (!video) return showNotification('Video yüklü değil!', 'warning');
    var textOverlay = document.getElementById('videoEditorTextOverlay');
    var music = document.getElementById('videoEditorMusic');
    var filter = document.getElementById('videoEditorFilter');
    showNotification('🎬 Video işleniyor... (Bu işlem biraz sürebilir)', 'success');
    if (typeof window.addLogInfo === 'function') {
        window.addLogInfo('AETHRION Video export başlatıldı', {
            trimStart: window.videoEditorTrimStart,
            trimEnd: window.videoEditorTrimEnd,
            hasText: !!(textOverlay && textOverlay.value),
            music: music ? music.value : 'none',
            filter: filter ? filter.value : 'none'
        });
    }
    setTimeout(function () {
        showNotification('✅ Video işleme alındı! Yakında indirilebilir olacak.', 'success');
    }, 1500);
};

window.saveVideoDraft = function () {
    var data = {
        trimStart: window.videoEditorTrimStart,
        trimEnd: window.videoEditorTrimEnd,
        text: (document.getElementById('videoEditorTextOverlay') || {}).value || '',
        music: (document.getElementById('videoEditorMusic') || {}).value || '',
        filter: (document.getElementById('videoEditorFilter') || {}).value || ''
    };
    try {
        localStorage.setItem('aethrion_video_draft', JSON.stringify(data));
        showNotification('💾 Taslak kaydedildi!', 'success');
    } catch (e) {
        showNotification('Taslak kaydedilemedi!', 'error');
    }
};

