// ================================================================
// ========== YARDIMCI FONKSİYONLAR ==============================
// ================================================================
if (typeof window.escapeHtml !== 'function') {
    window.escapeHtml = function (text) {
        if (text === null || text === undefined) return '';
        return String(text)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;');
    };
}

function escapeHtml(text) {
    if (!text) return text;
    return String(text).replace(/[&<>"']/g, function (m) {
        return {
            '&': '&amp;',
            '<': '&lt;',
            '>': '&gt;',
            '"': '&quot;',
            "'": '&#39;'
        }[m];
    });
}

function escapeForOnclick(text) {
    if (text === null || text === undefined) return '';
    return String(text)
        .replace(/\\/g, '\\\\')
        .replace(/'/g, "\\'")
        .replace(/"/g, '&quot;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/&/g, '&amp;');
}

if (typeof window.escapeForOnclick !== 'function') {
    window.escapeForOnclick = escapeForOnclick;
}

function renderMessageContent(content) {
    if (!content) return '';
    var escaped = window.escapeHtml(content);
    escaped = escaped.replace(
        /!\[([^\]]*)\]\(([^)]+)\)/g,
        '<img src="$2" alt="$1" style="max-width:100%; max-height:250px; border-radius:12px; margin-top:6px; display:block; cursor:pointer;" onclick="window.open(\'$2\', \'_blank\')">'
    );
    escaped = escaped.replace(
        /\[([^\]]+)\]\(([^)]+)\)/g,
        '<a href="$2" target="_blank" style="color:var(--accent); text-decoration:underline;">$1</a>'
    );
    escaped = escaped.replace(/\n/g, '<br>');
    return escaped;
}

