window.openGifPicker = function () {
    var modal = document.getElementById('gifPickerModal');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'gifPickerModal';
        modal.className = 'modal-overlay';
        modal.style.display = 'flex';
        modal.innerHTML = `
            <div class="modal" style="max-width:700px; max-height:80vh; overflow-y:auto;">
                <div class="modal-header">
                    <h3>🎬 AETHRION GIF Seçici</h3>
                    <button class="modal-close" onclick="window.closeModal('gifPickerModal')">×</button>
                </div>
                <div style="display:flex; gap:8px; margin-bottom:12px;">
                    <input type="text" id="gifSearchInput" placeholder="GIF ara (örn: selam, gülen)..." class="glow-input" style="flex:1;" onkeypress="if(event.key==='Enter') window.searchGifAndShow()">
                    <button class="btn-primary btn-sm" onclick="window.searchGifAndShow()">🔍 Ara</button>
                </div>
                <div id="gifResults" style="display:grid; grid-template-columns:repeat(auto-fill, minmax(150px,1fr)); gap:10px; max-height:400px; overflow-y:auto;"></div>
                <div style="margin-top:12px; text-align:center;">
                    <button class="btn-secondary" onclick="window.closeModal('gifPickerModal')">Kapat</button>
                </div>
            </div>
        `;
        document.body.appendChild(modal);
    }
    modal.classList.add('open');
    modal.style.display = 'flex';
    document.getElementById('gifSearchInput').value = '';
    document.getElementById('gifResults').innerHTML = '<div style="grid-column:1/-1; text-align:center; color:var(--text3); padding:20px;">🔍 Bir GIF araması yapın veya popüler GIF\'leri görün.</div>';
    window.searchGifAndShow('popüler');
};

window.searchGifAndShow = async function (query) {
    var input = document.getElementById('gifSearchInput');
    var searchQuery = query || input.value.trim();
    if (!searchQuery) {
        searchQuery = 'popüler';
    }
    var container = document.getElementById('gifResults');
    if (!container) return;
    container.innerHTML = '<div style="grid-column:1/-1; text-align:center; color:var(--text3); padding:20px;">⏳ GIF\'ler yükleniyor...</div>';
    try {
        var result = await Parse.Cloud.run('searchGif', { query: searchQuery });
        if (!result || result.length === 0) {
            container.innerHTML = '<div style="grid-column:1/-1; text-align:center; color:var(--text3); padding:20px;">😕 GIF bulunamadı. Farklı bir arama deneyin.</div>';
            return;
        }
        var html = '';
        result.forEach(function (gif) {
            var url = gif.images.fixed_height.url;
            var safeUrl = window.escapeHtml(url);
            var safeTitle = window.escapeHtml(gif.title || 'GIF');
            html += `
                <div style="cursor:pointer; border-radius:8px; overflow:hidden; border:1px solid var(--border2); transition:all 0.2s;"
                     onmouseover="this.style.borderColor='var(--accent)'"
                     onmouseout="this.style.borderColor='var(--border2)'"
                     onclick="window.selectGif('${safeUrl}')">
                    <img src="${safeUrl}" alt="${safeTitle}" style="width:100%; height:150px; object-fit:cover;">
                </div>
            `;
        });
        container.innerHTML = html;
    } catch (e) {
        console.error('GIF arama hatası:', e);
        container.innerHTML = '<div style="grid-column:1/-1; text-align:center; color:var(--danger); padding:20px;">❌ GIF\'ler yüklenemedi: ' + window.escapeHtml(e.message) + '</div>';
    }
};

window.selectGif = function (gifUrl) {
    var msgInput = document.getElementById('teamPageInput');
    if (msgInput) {
        msgInput.value = '![GIF](' + gifUrl + ')';
        window.sendTeamPageMessage();
        window.closeModal('gifPickerModal');
        showNotification('✅ GIF gönderildi!', 'success');
    } else {
        showNotification('Takım sohbeti bulunamadı!', 'error');
    }
};

