(function addJarvisButtonToTeamPage() {
    var checkInterval = setInterval(function () {
        var teamHeader = document.querySelector('#teamPage .team-page-header');
        if (teamHeader && !document.getElementById('teamPageJarvisBtn')) {
            var btn = document.createElement('button');
            btn.id = 'teamPageJarvisBtn';
            btn.className = 'koc-assistant-btn';
            btn.style.cssText = 'margin-left:8px;background:linear-gradient(135deg,#d4af37,#7c5cff,#7fd4ff) !important;background-size:250% 250% !important;';
            btn.innerHTML = '<span class="koc-icon">🤖</span><span class="koc-text">JARVIS</span>';
            btn.onclick = window.openJarvisFromTeamPage;
            var closeBtn = teamHeader.querySelector('.team-page-close');
            if (closeBtn) {
                teamHeader.insertBefore(btn, closeBtn);
            } else {
                teamHeader.appendChild(btn);
            }
            clearInterval(checkInterval);
        }
    }, 500);
    setTimeout(function () { clearInterval(checkInterval); }, 10000);
})();

