window.voiceChatActive = false;
window.voiceChatStartTime = null;
window.voiceChatTimer = null;
window.voiceChatCountedMinutes = 0;
window.voiceChatLastTick = null;

window.openVoiceChatFullscreen = async function () {
    if (!window.currentUser) {
        showNotification('Sesli sohbet için önce giriş yapın!', 'error');
        return;
    }

    if (typeof window.checkFeatureLimit === 'function') {
        var limitCheck = window.checkFeatureLimit('voiceChatMinutesPerDay', 'day');
        if (!limitCheck.allowed) {
            if (typeof window.showLimitModal === 'function') {
                window.showLimitModal('voiceChatMinutesPerDay', limitCheck);
            }
            return;
        }
    }

    var modal = document.getElementById('voiceChatFullscreen') || document.getElementById('vzVoiceFullscreen');
    if (!modal) {
        console.warn('Sesli sohbet modali bulunamadı');
        return;
    }

    modal.classList.add('open');
    modal.style.display = 'flex';
    window.voiceChatActive = true;
    window.voiceChatStartTime = Date.now();
    window.voiceChatCountedMinutes = 0;
    window.voiceChatLastTick = Date.now();

    if (window.voiceChatTimer) clearInterval(window.voiceChatTimer);
    window.voiceChatTimer = setInterval(function () {
        if (!window.voiceChatActive) return;
        var now = Date.now();
        var elapsed = Math.floor((now - window.voiceChatStartTime) / 60000);
        var newMinutes = elapsed - window.voiceChatCountedMinutes;
        if (newMinutes > 0) {
            window.voiceChatCountedMinutes += newMinutes;
            if (typeof window.incrementUsage === 'function') {
                window.incrementUsage('voiceChatMinutesPerDay', 'day', newMinutes);
            }
            if (typeof window.checkFeatureLimit === 'function') {
                var check = window.checkFeatureLimit('voiceChatMinutesPerDay', 'day');
                if (!check.allowed) {
                    window.closeVoiceChatFullscreen();
                    showNotification('⚠️ Günlük sesli sohbet süreniz doldu!', 'warning');
                    return;
                }
            }
        }
        var badge = document.getElementById('voiceChatLimitBadge');
        if (badge && typeof window.getLimitText === 'function') {
            badge.textContent = '📅 ' + window.getLimitText('voiceChatMinutesPerDay', 'day') + ' (günlük)';
        }
    }, 10000);

    if (typeof window.startVoiceChatRecognition === 'function') {
        window.startVoiceChatRecognition();
    }
};

window.closeVoiceChatFullscreen = function () {
    var modal = document.getElementById('voiceChatFullscreen') || document.getElementById('vzVoiceFullscreen');
    if (modal) {
        modal.classList.remove('open');
        modal.style.display = 'none';
    }

    window.voiceChatActive = false;
    if (window.voiceChatTimer) {
        clearInterval(window.voiceChatTimer);
        window.voiceChatTimer = null;
    }

    if (window.voiceChatRecognition) {
        try { window.voiceChatRecognition.stop(); } catch (e) {}
        window.voiceChatRecognition = null;
    }

    if (window.speechSynthesis && window.speechSynthesis.speaking) {
        window.speechSynthesis.cancel();
    }

    showNotification('🔊 Sesli sohbet kapatıldı', 'success');
};

window.toggleVoiceChatMute = function () {
    if (window.speechSynthesis && window.speechSynthesis.speaking) {
        window.speechSynthesis.cancel();
        showNotification('🔇 Ses kapatıldı', 'warning');
    } else {
        showNotification('🔊 Ses açık', 'success');
    }
};

