// ========== [v1.0.0 FIX] MAVİ İMLEÇ TAKİP =====================
// ================================================================
(function initCursorFix() {
    console.log('🖱️ [Cursor] Başlatılıyor (JS-6 içi)...');

    function waitForElements(callback, retries) {
        retries = retries || 0;
        var cursor = document.getElementById('customCursor');
        var ring = document.getElementById('customCursorRing');

        if (cursor && ring) {
            callback(cursor, ring);
            return;
        }

        if (retries > 50) {
            console.error('❌ [Cursor] Element bulunamadı (5 saniye bekledi)');
            return;
        }

        setTimeout(function () { waitForElements(callback, retries + 1); }, 100);
    }

    waitForElements(function (cursor, ring) {
        console.log('✅ [Cursor] Elementler bulundu, başlatılıyor...');

        var hasMouse = true;
        try {
            var fineMatch = window.matchMedia('(pointer: fine)').matches;
            var anyHover = window.matchMedia('(any-hover: hover)').matches;
            var hoverMatch = window.matchMedia('(hover: hover)').matches;
            hasMouse = fineMatch || anyHover || hoverMatch;
        } catch (e) { hasMouse = true; }

        if (!hasMouse) {
            cursor.style.display = 'none';
            ring.style.display = 'none';
            console.log('📱 [Cursor] Touch cihaz, imleç kapatıldı');
            return;
        }

        cursor.style.display = 'block';
        ring.style.display = 'block';
        cursor.style.position = 'fixed';
        ring.style.position = 'fixed';
        cursor.style.top = '0';
        cursor.style.left = '0';
        ring.style.top = '0';
        ring.style.left = '0';
        cursor.style.pointerEvents = 'none';
        ring.style.pointerEvents = 'none';
        cursor.style.zIndex = '999999';
        ring.style.zIndex = '999998';
        cursor.style.willChange = 'transform';
        ring.style.willChange = 'transform';
        cursor.style.transform = 'translate3d(-100px, -100px, 0)';
        ring.style.transform = 'translate3d(-100px, -100px, 0)';

        var mx = -100, my = -100;
        var rx = -100, ry = -100;
        var isMoving = false;
        var moveTimer = null;
        var rafId = null;

        function onMouseMove(e) {
            mx = e.clientX;
            my = e.clientY;
            cursor.style.transform = 'translate3d(' + (mx - 7) + 'px, ' + (my - 7) + 'px, 0)';

            if (!isMoving) {
                isMoving = true;
                animateRing();
            }

            if (moveTimer) clearTimeout(moveTimer);
            moveTimer = setTimeout(function () {
                isMoving = false;
                if (rafId) { cancelAnimationFrame(rafId); rafId = null; }
            }, 1500);
        }

        function animateRing() {
            if (!isMoving) return;
            rx += (mx - rx) * 0.15;
            ry += (my - ry) * 0.15;
            ring.style.transform = 'translate3d(' + (rx - 20) + 'px, ' + (ry - 20) + 'px, 0)';
            rafId = requestAnimationFrame(animateRing);
        }

        document.addEventListener('mousemove', onMouseMove, { passive: true });

        var hoverSelector = 'a, button, .btn, .feature-card, .price-card, ' +
                           '.store-item, .nav-links a, .secret-btn, .nav-cta, ' +
                           '[onclick], input, textarea, select, .f3d-shape-item, ' +
                           '.comment-item, .koc-assistant-btn, .vizyon-al-trigger, ' +
                           '.aethrion-al-trigger, .btn-primary, .btn-secondary, ' +
                           '.btn-danger, .btn-success';

        function bindHover() {
            var els = document.querySelectorAll(hoverSelector);
            for (var i = 0; i < els.length; i++) {
                var el = els[i];
                if (el._cursorBound) continue;
                el._cursorBound = true;
                el.addEventListener('mouseenter', function () {
                    cursor.classList.add('hover');
                });
                el.addEventListener('mouseleave', function () {
                    cursor.classList.remove('hover');
                });
            }
        }

        setTimeout(bindHover, 500);

        if (typeof MutationObserver !== 'undefined') {
            try {
                var obs = new MutationObserver(function () {
                    clearTimeout(window._cursorBindTimer);
                    window._cursorBindTimer = setTimeout(bindHover, 300);
                });
                obs.observe(document.body, { childList: true, subtree: true });
            } catch (e) {}
        }

        document.addEventListener('mouseleave', function () {
            cursor.style.opacity = '0';
            ring.style.opacity = '0';
        });
        document.addEventListener('mouseenter', function () {
            cursor.style.opacity = '1';
            ring.style.opacity = '0.65';
        });

        console.log('✅ [Cursor] Mavi imleç takip BAŞLATILDI!');
    });

})();

