// ========== [v1.0.0] NVIDIA NIM VE CUSTOM API DESTEK ===========
// ================================================================
window.callNvidiaNIM = async function (prompt, model) {
    try {
        var result = await Parse.Cloud.run('callNvidiaNIM', {
            prompt: prompt,
            model: model || 'meta/llama-3.3-70b-instruct'
        });
        return result;
    } catch (e) {
        console.error('NVIDIA NIM hatası:', e);
        throw e;
    }
};

window.callCustomAPIWithFallback = async function (prompt, apiKeys) {
    if (!apiKeys || apiKeys.length === 0) {
        throw new Error('API anahtarı bulunamadı');
    }
    var lastError = null;
    for (var i = 0; i < apiKeys.length; i++) {
        try {
            var result = await Parse.Cloud.run('callCustomAIWithKeys', {
                prompt: prompt,
                keyIds: [apiKeys[i].id]
            });
            if (result && result.success && result.reply) {
                return result.reply;
            }
        } catch (e) {
            console.warn('API anahtarı ' + (i + 1) + ' başarısız:', e.message);
            lastError = e;
        }
    }
    throw lastError || new Error('Tüm API anahtarları başarısız oldu');
};

// ================================================================
// ========== [v1.0.0] BUTON ÇALIŞMAMA SORUNU FIX ================
// ================================================================
(function fixButtonHandlers() {
    function bindButtonHandlers() {
        var buttons = document.querySelectorAll('button[onclick], a[onclick], [onclick]');
        buttons.forEach(function (btn) {
            if (btn._handlerBound) return;
            btn._handlerBound = true;
            var onclickAttr = btn.getAttribute('onclick');
            if (!onclickAttr) return;

            if (onclickAttr.indexOf('window.') === -1 && onclickAttr.indexOf('document.') === -1 && onclickAttr.indexOf('this.') === -1) {
                try {
                    var fnName = onclickAttr.replace(/\(.*\)/, '').trim();
                    if (typeof window[fnName] === 'function') {
                        btn.addEventListener('click', function (e) {
                            e.preventDefault();
                            try {
                                window[fnName]();
                            } catch (err) {
                                console.error('Buton handler hatası (' + fnName + '):', err);
                                if (typeof showNotification === 'function') {
                                    showNotification('İşlem hatası: ' + err.message, 'error');
                                }
                            }
                        });
                    }
                } catch (e) {
                    console.warn('Buton handler bağlanamadı:', onclickAttr);
                }
            }
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function () {
            setTimeout(bindButtonHandlers, 1000);
            setTimeout(bindButtonHandlers, 3000);
        });
    } else {
        setTimeout(bindButtonHandlers, 1000);
        setTimeout(bindButtonHandlers, 3000);
    }

    setTimeout(bindButtonHandlers, 5000);
})();

