document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') {
        var kocShareModal = document.getElementById('kocShareModalOverlay');
        if (kocShareModal && kocShareModal.classList.contains('open')) {
            window.closeKocShareModal();
            return;
        }
        var kocPanel = document.getElementById('kocPanelOverlay');
        if (kocPanel && kocPanel.classList.contains('open')) {
            window.closeKocPanel();
            return;
        }
        if (window.vizyonAlOpened || window.aethrionAlOpened) {
            window.closeAethrionAlPanel();
            return;
        }
        if (window.voiceChatActive) {
            window.closeVoiceChatFullscreen();
            return;
        }
        var a27Reveal = document.getElementById('a27KeyRevealOverlay') || document.getElementById('v27KeyRevealOverlay');
        if (a27Reveal && a27Reveal.classList.contains('open')) {
            return;
        }
        if (window.jarvisActive && typeof window.closeJarvisPanel === 'function') {
            window.closeJarvisPanel();
            return;
        }
    }
});

