if (!window.submitQuickA27Key) {
    window.submitQuickA27Key = async function () {
        if (!window.currentUser) {
            if (typeof showNotification === 'function') showNotification('Önce giriş yapın!', 'error');
            return;
        }
        var nameEl = document.getElementById('v27QuickKeyName') || document.getElementById('a27QuickKeyName');
        var descEl = document.getElementById('v27QuickKeyDesc') || document.getElementById('a27QuickKeyDesc');
        var errEl = document.getElementById('v27QuickCreateError') || document.getElementById('a27QuickCreateError');
        var keyName = nameEl ? nameEl.value.trim() : '';
        var keyDesc = descEl ? descEl.value.trim() : '';
        if (!keyName) {
            if (errEl) { errEl.textContent = '❌ Anahtar adı gerekli!'; errEl.style.display = 'block'; }
            return;
        }
        if (keyName.length < 2) {
            if (errEl) { errEl.textContent = '❌ Anahtar adı en az 2 karakter olmalı!'; errEl.style.display = 'block'; }
            return;
        }
        try {
            var result = await Parse.Cloud.run('createV27ApiKey', {
                keyName: keyName,
                keyDescription: keyDesc,
                duration: window._a27QuickSelectedDuration || 'unlimited',
                viaVizyonAl: true
            });
            if (!result.success) {
                if (errEl) { errEl.textContent = '❌ ' + (result.error || 'Anahtar oluşturulamadı.'); errEl.style.display = 'block'; }
                return;
            }
            window.closeA27QuickCreate();
            window.showA27KeyReveal(result.plainKey, result.durationLabel);
            if (typeof showNotification === 'function') showNotification('✅ A27 API anahtarı oluşturuldu!', 'success');
            if (typeof window.addLogSuccess === 'function') window.addLogSuccess('AETHRION Al üzerinden A27 API anahtarı oluşturuldu');
        } catch (e) {
            if (errEl) { errEl.textContent = '❌ ' + e.message; errEl.style.display = 'block'; }
        }
    };
}
if (!window.submitQuickV27Key) {
    window.submitQuickV27Key = window.submitQuickA27Key;
}

