if (!window.copyA27ApiKey) {
    window.copyA27ApiKey = function () {
        var key = window._a27LastKey || window._v27LastKey;
        if (!key) {
            if (typeof showNotification === 'function') showNotification('Kopyalanacak anahtar yok!', 'error');
            return;
        }
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(key).then(function () {
                if (typeof showNotification === 'function') showNotification('📋 A27 API anahtarı kopyalandı!', 'success');
            }).catch(function () {
                if (typeof fallbackCopyText === 'function') fallbackCopyText(key);
            });
        } else {
            if (typeof fallbackCopyText === 'function') fallbackCopyText(key);
        }
    };
}
if (!window.copyV27ApiKey) {
    window.copyV27ApiKey = window.copyA27ApiKey;
}

