    window.toggleSuspend = async function () {
        if (!window.currentUser) return _pNotify('Önce giriş yapın!', 'error');
        if (!window.parentLoggedIn) return _pNotify('Önce ebeveyn girişi yapın!', 'error');
        if (!_lockAction('toggleSuspend')) return;

        var isSuspended = window.currentUser.get('is_suspended') || false;

        try {
            if (isSuspended) {
                var r = await Parse.Cloud.run('unsuspendChildAccount', {
                    childEmail: window.currentUser.get('email')
                });
                if (r && r.success) {
                    _pNotify('✅ Hesap aktif edildi!', 'success');
                    var statusEl = document.getElementById('accountStatus');
                    if (statusEl) statusEl.textContent = '✅ Aktif';
                }
            } else {
                var hours = prompt('Kaç saat askıya alınsın? (örn: 2, 24, 168)', '2');
                if (!hours) {
                    window._parentActionLock['toggleSuspend'] = false;
                    return;
                }
                var r2 = await Parse.Cloud.run('suspendChildAccount', {
                    childEmail: window.currentUser.get('email'),
                    durationHours: parseInt(hours)
                });
                if (r2 && r2.success) {
                    _pNotify('⏸️ Hesap ' + hours + ' saat askıya alındı', 'success');
                    var statusEl2 = document.getElementById('accountStatus');
                    if (statusEl2) statusEl2.textContent = '⏸️ Askıda';
                }
            }
            await window.currentUser.fetch();
        } catch (e) {
            _pNotify('Hata: ' + e.message, 'error');
        } finally {
            window._parentActionLock['toggleSuspend'] = false;
        }
    };

    // ============================================================
