// ================================================================
// [v8.0.0 FIX] window.loadUserList — Eksik fonksiyon
// Admin/Kurucu panelinde tüm kullanıcıları listeler
// ================================================================
window.loadUserList = async function () {
    var container = document.getElementById('userList');
    if (!container) {
        console.warn('⚠️ userList elementi bulunamadı');
        return;
    }

    // Yetki kontrolü — sadece founder/admin görebilir
    if (!window.currentUser) {
        container.innerHTML = '<div class="user-item">⚠️ Giriş yapmalısınız.</div>';
        return;
    }

    var role = window.currentUser.get('role');
    if (role !== 'founder' && role !== 'admin') {
        container.innerHTML = '<div class="user-item">🔒 Bu listeyi sadece Kurucu ve Admin görebilir.</div>';
        return;
    }

    container.innerHTML = '<div class="user-item" style="color:var(--text3);text-align:center;">⏳ Kullanıcılar yükleniyor...</div>';

    try {
        var result = await Parse.Cloud.run('getAllUsers', {});
        if (!result || !result.success || !result.users || result.users.length === 0) {
            container.innerHTML = '<div class="user-item">📭 Hiç kullanıcı bulunamadı.</div>';
            return;
        }

        var html = '';
        result.users.forEach(function (u) {
            var safeEmail = window.escapeHtml(u.email || '');
            var safeName = window.escapeHtml(u.name || 'İsimsiz');
            var safeRole = u.role || 'user';
            var roleLabel = safeRole === 'founder' ? '👑 KURUCU' :
                           safeRole === 'admin' ? '⚙️ ADMIN' :
                           safeRole === 'beta' ? '🔬 BETA' :
                           safeRole === 'moderator' ? '🎨 MODERATÖR' :
                           '👤 KULLANICI';
            var isBanned = u.isBanned ? ' 🚫 ENGELLİ' : '';
            var planLabel = u.plan === 'team' ? '👥 Takım' :
                           u.plan === 'pro' ? '🌟 Pro' : '🆓 Ücretsiz';
            var points = u.points || 0;

            html += '<div class="user-item">';
            html += '<div style="flex:1;min-width:0;">';
            html += '<div class="user-email">' + safeEmail + isBanned + '</div>';
            html += '<div style="font-size:11px;color:var(--text3);margin-top:3px;">' +
                    safeName + ' · ' + roleLabel + ' · ' + planLabel + ' · ⭐ ' + points + '</div>';
            html += '</div>';
            html += '<div class="user-actions">';
            if (safeRole !== 'founder') {
                if (safeRole === 'admin') {
                    html += '<button class="btn-user" onclick="window.setUserRole(\'' + window.escapeForOnclick(u.email) + '\', \'user\')">👤 Üye Yap</button>';
                } else {
                    html += '<button class="btn-admin" onclick="window.setUserRole(\'' + window.escapeForOnclick(u.email) + '\', \'admin\')">⚙️ Admin</button>';
                }
                if (safeRole === 'moderator') {
                    html += '<button class="btn-user" onclick="window.setUserRole(\'' + window.escapeForOnclick(u.email) + '\', \'user\')">🚫 Mod Kaldır</button>';
                } else {
                    html += '<button class="btn-mod" onclick="window.setUserRole(\'' + window.escapeForOnclick(u.email) + '\', \'moderator\')">🎨 Mod</button>';
                }
                if (u.isBanned) {
                    html += '<button class="btn-user" onclick="window.unbanUserEmail(\'' + window.escapeForOnclick(u.email) + '\')">🔓 Aç</button>';
                } else {
                    html += '<button class="btn-ban" onclick="window.banUserEmail(\'' + window.escapeForOnclick(u.email) + '\')">🚫 Ban</button>';
                }
            } else {
                html += '<span style="font-size:10px;color:var(--gold);padding:4px 10px;">👑 Kurucu</span>';
            }
            html += '</div>';
            html += '</div>';
        });
        container.innerHTML = html;
        console.log('✅ loadUserList tamamlandı: ' + result.users.length + ' kullanıcı');
    } catch (e) {
        console.error('loadUserList hatası:', e);
        container.innerHTML = '<div class="user-item" style="color:var(--danger);">⚠️ Yüklenemedi: ' + window.escapeHtml(e.message) + '</div>';
        if (typeof window.addLogError === 'function') {
            window.addLogError('Kullanıcı listesi yüklenemedi: ' + e.message);
        }
    }
};

// ================================================================
// [v8.0.0 FIX] searchAllUsers — Kullanıcı arama (admin panel)
// ================================================================
window.searchAllUsers = async function () {
    var input = document.getElementById('userSearchInput');
    var container = document.getElementById('userList');
    if (!input || !container) return;
    var query = input.value.trim();
    if (!query) {
        return window.loadUserList();
    }
    container.innerHTML = '<div class="user-item" style="color:var(--text3);text-align:center;">⏳ Aranıyor...</div>';
    try {
        var result = await Parse.Cloud.run('searchUsers', { query: query });
        if (!result || result.length === 0) {
            container.innerHTML = '<div class="user-item">🔍 Eşleşen kullanıcı bulunamadı.</div>';
            return;
        }
        var html = '';
        result.forEach(function (u) {
            var safeEmail = window.escapeHtml(u.email || '');
            var safeName = window.escapeHtml(u.name || 'İsimsiz');
            html += '<div class="user-item">';
            html += '<div class="user-email">' + safeEmail + '</div>';
            html += '<div style="font-size:11px;color:var(--text3);">' + safeName + '</div>';
            html += '</div>';
        });
        container.innerHTML = html;
    } catch (e) {
        container.innerHTML = '<div class="user-item" style="color:var(--danger);">⚠️ ' + window.escapeHtml(e.message) + '</div>';
    }
};

// ================================================================
// [v8.0.0 FIX] getUserListRefresh — Periyodik yenileme
// ================================================================
window.refreshUserList = async function () {
    if (window.currentUser && (window.currentUser.get('role') === 'founder' || window.currentUser.get('role') === 'admin')) {
        await window.loadUserList();
    }
};

console.log('✅ JS-DUZELTME v8.0.0 yüklendi');
console.log('   → window.loadUserList (FIX)');
console.log('   → window.searchAllUsers (FIX)');
console.log('   → window.refreshUserList (FIX)');


/* Extracted inline script 13; source attributes: none */
(function AethrionSplashController() {
    'use strict';

    function run() {
        var splash    = document.getElementById('splashScreen');
        var barEl     = document.getElementById('splashProgressBar');
        var percentEl = document.getElementById('splashPercent');
        var stageEl   = document.getElementById('splashStage');
        var statusEl  = document.getElementById('splashStatus');
        var readyEl   = document.getElementById('splashReady');

        // Create splash particles once; this controller is the only progress owner.
        var particlesEl = document.getElementById('splashParticles');
        if (particlesEl && !particlesEl.getAttribute('data-aethrion-initialized')) {
            particlesEl.setAttribute('data-aethrion-initialized', 'true');
            var particleCount = window.innerWidth < 768 ? 12 : 24;
            for (var pi = 0; pi < particleCount; pi++) {
                var particle = document.createElement('span');
                particle.className = 'splash-particle';
                particle.style.left = (Math.random() * 100) + '%';
                particle.style.animationDuration = (5 + Math.random() * 6) + 's';
                particle.style.animationDelay = (Math.random() * 5) + 's';
                particlesEl.appendChild(particle);
            }
        }

        // Element yoksa hemen çık
        if (!splash) {
            console.warn('🛡️ [Splash] splashScreen bulunamadı, iptal');
            return;
        }
        // Zaten kapalıysa çalışma
        if (splash.style.display === 'none') {
            console.log('🛡️ [Splash] Zaten kapalı, iptal');
            return;
        }

        console.log('🛡️ [Splash] Override controller başlatıldı');

        var progress = 0;
        var done = false;

        var stages = [
            { p: 5,   text: 'AETHRION CORE BAŞLATILIYOR' },
            { p: 18,  text: '13 OLLAMA MODELİ HAZIRLANIYOR' },
            { p: 32,  text: '7 NVIDIA NIM MODELLERİ YÜKLENİYOR' },
            { p: 46,  text: '8 BULUT API BAĞLANIYOR' },
            { p: 60,  text: 'VERİTABANI BAĞLANTISI KURULUYOR' },
            { p: 72,  text: 'GÜVENLİK KATMANI AKTİF' },
            { p: 84,  text: 'AETHRION AL HAZIR' },
            { p: 94,  text: 'ARAYÜZ OPTİMİZE EDİLİYOR' },
            { p: 100, text: 'HAZIR!' }
        ];

        function tick() {
            if (done) return;

            progress += Math.random() * 8 + 4;
            if (progress >= 100) progress = 100;

            var pInt = Math.floor(progress);

            // Bar genişliği ve yüzde
            if (barEl) barEl.style.width = pInt + '%';
            if (percentEl) percentEl.textContent = pInt + '%';

            // Aktif aşamayı bul
            var current = stages[0];
            for (var i = 0; i < stages.length; i++) {
                if (progress >= stages[i].p) current = stages[i];
            }
            if (stageEl) stageEl.textContent = current.text;
            if (statusEl) {
                statusEl.innerHTML = '<span class="splash-status-dot"></span> ' + current.text;
            }

            if (progress < 100) {
                setTimeout(tick, 100 + Math.random() * 120);
            } else {
                done = true;
                if (readyEl) {
                    readyEl.textContent = '✨ AETHRION EKOSİSTEMİ HAZIR';
                    readyEl.style.color = 'var(--accent2)';
                    readyEl.style.textShadow = '0 0 25px rgba(184, 192, 208, 0.7)';
                }
                setTimeout(closeSplash, 400);
            }
        }

        function closeSplash() {
            if (!splash) return;
            splash.classList.add('hidden', 'hide');
            splash.style.opacity = '0';
            splash.style.visibility = 'hidden';
            splash.style.pointerEvents = 'none';
            splash.style.transition = 'opacity 0.5s ease, visibility 0.5s ease';
            setTimeout(function () {
                splash.style.display = 'none';
                splash.style.zIndex = '-1';
                document.body.style.overflow = '';
                document.documentElement.style.overflow = '';
                document.body.style.height = '';
                document.body.style.width = '';
                console.log('✅ [Splash] Başarıyla kapatıldı');
            }, 550);
        }

        // Başlat
        tick();

        // 🛡️ 6 saniye timeout güvenlik ağı
        setTimeout(function () {
            if (!done) {
                console.warn('🛡️ [Splash] Timeout — zorla kapatılıyor');
                done = true;
                if (barEl) barEl.style.width = '100%';
                if (percentEl) percentEl.textContent = '100%';
                closeSplash();
            }
        }, 6000);
    }

    // DOM hazır olduğunda başlat
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function () {
            setTimeout(run, 150);
        });
    } else {
        setTimeout(run, 150);
    }
})();


