                var codeInput = document.getElementById('teamPageCodeInput');
                if (codeInput) codeInput.style.display = 'inline-block';
                var leaveBtn = document.getElementById('teamPageLeaveBtn');
                if (leaveBtn) leaveBtn.style.display = 'none';
