(function fixModalPlacement() {
    'use strict';
    
    var modalIds = [
        'authModal',
        'profileCompletionModal',
        'recoveryLoginModal',
        'notificationModal'
    ];
    
    function tryMoveModals() {
        var moved = 0;
        modalIds.forEach(function(id) {
            var modal = document.getElementById(id);
            if (modal && modal.closest('#dashboardArea')) {
                document.body.appendChild(modal);
                console.log('✅ ' + id + ' dashboardArea\'dan body\'ye taşındı');
                moved++;
            }
        });
        if (moved > 0) {
            console.log('📦 ' + moved + ' modal taşındı');
        }
    }
    
    // Sayfa yüklendiğinde çalıştır
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() {
            setTimeout(tryMoveModals, 100);
            setTimeout(tryMoveModals, 1000);
            setTimeout(tryMoveModals, 3000);
        });
    } else {
        setTimeout(tryMoveModals, 100);
        setTimeout(tryMoveModals, 1000);
        setTimeout(tryMoveModals, 3000);
    }
    
    // MutationObserver ile sonradan eklenen modalleri de taşı
    if (typeof MutationObserver !== 'undefined') {
        setTimeout(function() {
            if (document.body) {
                var observer = new MutationObserver(function() {
                    tryMoveModals();
                });
                observer.observe(document.body, { childList: true, subtree: false });
            }
        }, 2000);
    }
    
    // openModal fonksiyonunu override et — taşımayı garantile
    window.openModal = function (type) {
        var modal = document.getElementById('authModal');
        if (!modal) {
            console.error('authModal elementi bulunamadı!');
            return;
        }
        
        // Dashboard içindeyse body'ye taşı
        if (modal.closest('#dashboardArea')) {
            document.body.appendChild(modal);
        }
        
        modal.classList.add('open');
        modal.style.display = 'flex';
        
        // switchTab varsa çağır
        if (typeof window.switchTab === 'function') {
            window.switchTab(type);
        } else {
            // Fallback: manuel tab switch
            var loginForm = document.getElementById('formLogin');
            var registerForm = document.getElementById('formRegister');
            var verifyForm = document.getElementById('formVerify');
            var tabs = document.querySelectorAll('.modal-tab');
            
            if (loginForm) loginForm.style.display = 'none';
            if (registerForm) registerForm.style.display = 'none';
            if (verifyForm) verifyForm.style.display = 'none';
            
            tabs.forEach(function(t) { t.classList.remove('active'); });
            
            if (type === 'login') {
                if (loginForm) loginForm.style.display = 'block';
                if (tabs[0]) tabs[0].classList.add('active');
            } else if (type === 'register') {
                if (registerForm) registerForm.style.display = 'block';
                if (tabs[1]) tabs[1].classList.add('active');
            } else if (type === 'verify') {
                if (verifyForm) verifyForm.style.display = 'block';
                if (tabs[2]) tabs[2].classList.add('active');
            }
        }
    };
    
    console.log('✅ [MODAL PLACEMENT FIX] Yüklendi');
})();


