// [AETHRION SAFETY NET] Otomatik Acil Temizlik
// Sayfa 3 saniye içinde açılmazsa veya bir modal takılırsa
// otomatik sıfırlar
// ═══════════════════════════════════════════════════════════════
(function aethrionSafetyNet() {
    'use strict';

    // Sayfa yüklendikten 3 saniye sonra kontrol
    setTimeout(function () {
        // Eğer body overflow hidden ise ve hiçbir panel açık değilse, sıfırla
        if (document.body.style.overflow === 'hidden') {
            var anyPanelOpen = document.querySelector('.modal-overlay.open, #aethrionFeaturesPanel.open, #vizyonAlPanel.open, #kocPanelOverlay.open, [class*="overlay"].open');
            if (!anyPanelOpen) {
                console.warn('🛡️ [SafetyNet] Body overflow takılı, sıfırlanıyor...');
                document.body.style.overflow = '';
                document.documentElement.style.overflow = '';
            }
        }

        // Cursor görünmüyorsa yeniden başlat
        var cursor = document.getElementById('customCursor');
        var ring = document.getElementById('customCursorRing');
        if (cursor && cursor.style.display === 'none' && window.innerWidth > 768) {
            console.log('🛡️ [SafetyNet] Cursor yeniden başlatılıyor...');
            cursor.style.display = 'block';
            cursor.style.pointerEvents = 'none';
            cursor.style.position = 'fixed';
            cursor.style.zIndex = '999999';
            cursor.style.transform = 'translate3d(-100px, -100px, 0)';
            if (ring) {
                ring.style.display = 'block';
                ring.style.pointerEvents = 'none';
                ring.style.position = 'fixed';
                ring.style.zIndex = '999998';
                ring.style.transform = 'translate3d(-100px, -100px, 0)';
            }

            // Mousemove dinleyicisi yoksa ekle
            if (!window._cursorMousemoveBound) {
                window._cursorMousemoveBound = true;
                var mx = -100, my = -100;
                var rx = -100, ry = -100;
                var isMoving = false;
                var animId = null;

                document.addEventListener('mousemove', function(e) {
                    mx = e.clientX;
                    my = e.clientY;
                    cursor.style.transform = 'translate3d(' + (mx - 7) + 'px, ' + (my - 7) + 'px, 0)';

                    if (!isMoving) {
                        isMoving = true;
                        (function loop() {
                            if (!isMoving) return;
                            rx += (mx - rx) * 0.15;
                            ry += (my - ry) * 0.15;
                            ring.style.transform = 'translate3d(' + (rx - 20) + 'px, ' + (ry - 20) + 'px, 0)';
                            animId = requestAnimationFrame(loop);
                        })();
                    }

                    clearTimeout(window._cursorStopTimer);
                    window._cursorStopTimer = setTimeout(function() {
                        isMoving = false;
                        if (animId) cancelAnimationFrame(animId);
                    }, 1000);
                }, { passive: true });
            }
        }

        // Çıkış butonunu kontrol et
        var logoutBtns = document.querySelectorAll('[onclick*="logout"], .logout-btn');
        logoutBtns.forEach(function(btn) {
            if (!btn._logoutBound) {
                btn._logoutBound = true;
                // Eski onclick'i kaldır
                btn.removeAttribute('onclick');
                btn.addEventListener('click', function(e) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (confirm('AETHRION\'dan çıkış yapmak istediğinize emin misiniz?')) {
                        if (typeof Parse !== 'undefined') {
                            Parse.User.logOut().then(function() {
                                localStorage.removeItem('aethrion_user');
                                window.currentUser = null;
                                location.reload();
                            });
                        } else {
                            location.reload();
                        }
                    }
                });
            }
        });
    }, 3000);

    // Her 5 saniyede bir modal takılma kontrolü
    setInterval(function() {
        // Eğer body overflow hidden ve hiçbir panel açık değilse, sıfırla
        if (document.body.style.overflow === 'hidden') {
            var anyOpen = document.querySelector('.modal-overlay.open, #aethrionFeaturesPanel.open, [class*="overlay"].open');
            if (!anyOpen) {
                document.body.style.overflow = '';
            }
        }
    }, 5000);

    console.log('🛡️ [AETHRION SafetyNet] Aktif');
})();


