            { group: '👤 Hesap', icon: '📋', name: 'Hesap Bilgilerim', desc: 'IP, cihaz, üyelik', action: 'openAccountInfo', color: '#8a8aa8' },
            { group: '👤 Hesap', icon: '⚙️', name: 'Ayarlar', desc: 'Dil, tema, tercihler', action: 'openSettingsModal', color: '#8a8aa8' },
            { group: '👤 Hesap', icon: '🚪', name: 'Çıkış Yap', desc: 'Oturumu kapat', action: 'doLogout', color: '#ff4d5e' }
