                { group: '👑 Yönetim', icon: '⚙️', name: 'Admin Ata', desc: 'Yönetici yetkisi', action: 'openAdminAssign', color: '#e8c555' },
                { group: '👑 Yönetim', icon: '📊', name: 'Anket Oluştur', desc: 'Topluluk oylaması', action: 'openPollCreator', color: '#e8c555' }
