// [AETHRION v1.0.0] KESİN BEKÇİ SCRIPT
// ═══════════════════════════════════════════════════════════════
(function AethrionGuard() {
    'use strict';

    // ═══ 1. KULLANICI DURUMUNU KONTROL ET ═══
    function checkUserAndSetGuard() {
        // Parse hazır mı?
        if (typeof Parse === 'undefined' || !Parse.User) {
            // Parse hazır değilse, kullanıcı YOK kabul et ve ana sayfayı göster.
            document.body.classList.remove('logged-in-user');
            var dash = document.getElementById('dashboardArea');
            if (dash) dash.style.display = 'none';
            var main = document.getElementById('mainSite');
            if (main) {
                main.style.display = 'block';
                main.style.visibility = 'visible';
            }
            console.log('🛡️ Bekçi: Parse hazır değil, ana sayfa gösterildi.');
            return false;
        }

        // Kullanıcıyı kontrol et
        var user = null;
        try {
            user = Parse.User.current();
        } catch (e) {
            console.warn('🛡️ Bekçi: Parse.User.current hatası:', e.message);
        }

        if (user) {
            // KULLANICI VAR: Dashboard'u göster, ana sayfayı gizle
            document.body.classList.add('logged-in-user');
            window.currentUser = user;
            if (typeof currentUser !== 'undefined') {
                try { currentUser = user; } catch(e) {}
            }

            var dash = document.getElementById('dashboardArea');
            if (dash) {
                dash.style.display = 'block';
                dash.style.visibility = 'visible';
                dash.style.pointerEvents = 'auto';
            }
            var main = document.getElementById('mainSite');
            if (main) {
                main.style.display = 'none';
            }

            // Moderatör panelini kontrol et (sadece moderatör için)
            var modCard = document.getElementById('moderatorInfoCard');
            if (modCard) {
                if (user.get('role') === 'moderator') {
                    modCard.style.display = 'block';
                } else {
                    modCard.style.display = 'none';
                }
            }

            console.log('🛡️ Bekçi: Kullanıcı bulundu (' + user.get('email') + '), dashboard gösterildi.');
            return true;
        } else {
            // KULLANICI YOK: Dashboard'u gizle, ana sayfayı göster
            document.body.classList.remove('logged-in-user');
            window.currentUser = null;
            if (typeof currentUser !== 'undefined') {
                try { currentUser = null; } catch(e) {}
            }

            var dash = document.getElementById('dashboardArea');
            if (dash) {
                dash.style.display = 'none';
                dash.style.visibility = 'hidden';
            }
            var main = document.getElementById('mainSite');
            if (main) {
                main.style.display = 'block';
                main.style.visibility = 'visible';
                main.style.pointerEvents = 'auto';
            }

            // Moderatör panelini gizle
            var modCard = document.getElementById('moderatorInfoCard');
            if (modCard) modCard.style.display = 'none';

            console.log('🛡️ Bekçi: Kullanıcı yok, ana sayfa gösterildi.');
            return false;
        }
    }

    // ═══ 2. showDashboard'u KİLİTLE ═══
    // Kullanıcı yoksa showDashboard çağrılsa bile çalışmasın.
    var originalShow = window.showDashboard;
    window.showDashboard = async function() {
        var user = null;
        try { user = Parse.User.current(); } catch(e) {}
        if (!user) {
            console.log('🛡️ Bekçi: showDashboard engellendi (kullanıcı yok).');
            checkUserAndSetGuard(); // Ana sayfayı göster
            return;
        }
        // Kullanıcı varsa orijinal fonksiyonu çalıştır
        if (typeof originalShow === 'function') {
            return originalShow.apply(this, arguments);
        }
    };

    // ═══ 3. logout'u KİLİTLE ═══
    window.logout = function() {
        if (!confirm('Çıkış yapmak istediğinize emin misiniz?')) return;
        try { Parse.User.logOut(); } catch(e) {}
        try {
            localStorage.clear();
            sessionStorage.clear();
        } catch(e) {}
        window.currentUser = null;
        // Ana sayfaya dön
        document.body.classList.remove('logged-in-user');
        var dash = document.getElementById('dashboardArea');
        if (dash) dash.style.display = 'none';
        var main = document.getElementById('mainSite');
        if (main) main.style.display = 'block';
        setTimeout(function() { location.reload(true); }, 500);
    };

    // ═══ 4. SAYFA YÜKLENDİĞİNDE VE PERİYODİK OLARAK ÇALIŞTIR ═══
    // İlk kontrol
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() {
            setTimeout(checkUserAndSetGuard, 500);
            setTimeout(checkUserAndSetGuard, 2000);
            setTimeout(checkUserAndSetGuard, 4000);
        });
    } else {
        setTimeout(checkUserAndSetGuard, 500);
        setTimeout(checkUserAndSetGuard, 2000);
        setTimeout(checkUserAndSetGuard, 4000);
    }

    // Her 2 saniyede bir kontrol et (sayfa donmasın diye)
    setInterval(function() {
        // Eğer kullanıcı yoksa ama dashboard açıksa, zorla kapat.
        var user = null;
        try { user = Parse.User.current(); } catch(e) {}
        if (!user) {
            var dash = document.getElementById('dashboardArea');
            if (dash && dash.style.display === 'block') {
                console.log('🛡️ Bekçi: Kullanıcı yok ama dashboard açık, kapatılıyor...');
                checkUserAndSetGuard();
            }
        }
    }, 2000);

    console.log('✅ [AETHRION] Kesin Bekçi yüklendi!');
})();


