            beta: { icon: '🔬', label: 'BETA TESTER', cls: 'beta', desc: 'Sınırsız kullanım · 28 model · Tüm özellikler' },
            moderator: { icon: '🎨', label: 'MODERATÖR', cls: 'moderator', desc: 'Sınırsız yetki · 28 model · Tüm özellikler' },
