/* AETHRION homepage repair: reset stale feature-drawer state on first load. */
(function () {
  function resetStaleFeatureDrawer() {
    var panel = document.getElementById('aethrionFeaturesPanel');
    var backdrop = document.getElementById('aethrionFeaturesBackdrop');
    if (panel) panel.classList.remove('open');
    if (backdrop) backdrop.classList.remove('show');
    document.body.classList.remove('aethrion-features-open');
    window.aethrionFeaturesPanelOpen = false;
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', resetStaleFeatureDrawer, { once: true });
  else resetStaleFeatureDrawer();
})();


