        <div style="padding:10px 24px;border-radius:999px;font-size:14px;font-weight:700;margin-bottom:24px;background:rgba(232,197,85,0.2);border:1.5px solid #e8c555;color:#e8c555;">${role === 'founder' ? '👑 KURUCU' : '👤 ÜYE'}</div>
